/* Organic ball renderer — used by the workshop preview and all arenas. */

export function hexToRgb(hex) {
  const h = hex.replace('#', '');
  const full = h.length === 3 ? h.split('').map((c) => c + c).join('') : h;
  return {
    r: parseInt(full.slice(0, 2), 16),
    g: parseInt(full.slice(2, 4), 16),
    b: parseInt(full.slice(4, 6), 16),
  };
}

export function mix(hexA, hexB, amount) {
  const a = hexToRgb(hexA);
  const b = hexToRgb(hexB);
  const c = (x, y) => Math.round(x + (y - x) * amount);
  return `rgb(${c(a.r, b.r)},${c(a.g, b.g)},${c(a.b, b.b)})`;
}

export const lighten = (hex, amt) => mix(hex, '#ffffff', amt);
export const darken = (hex, amt) => mix(hex, '#05070a', amt);
export function alpha(hex, a) {
  const { r, g, b } = hexToRgb(hex);
  return `rgba(${r},${g},${b},${a})`;
}

function hashString(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i += 1) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function rng(seed) {
  let s = seed || 1;
  return () => {
    s ^= s << 13; s ^= s >>> 17; s ^= s << 5;
    return ((s >>> 0) % 10000) / 10000;
  };
}

function blobPath(ctx, r, t, wobble = 1, points = 44) {
  ctx.beginPath();
  for (let i = 0; i <= points; i += 1) {
    const a = (i / points) * Math.PI * 2;
    const wob = 1 + (Math.sin(a * 3 + t * 1.3) * 0.016 + Math.sin(a * 5 - t * 1.9) * 0.011) * wobble;
    const x = Math.cos(a) * r * wob;
    const y = Math.sin(a) * r * wob;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

function drawPattern(ctx, config, r, accent) {
  const pat = config.pattern;
  if (!pat || pat === 'solid') return;
  ctx.save();
  blobPath(ctx, r * 0.995, 0, 0);
  ctx.clip();
  if (pat === 'split') {
    ctx.fillStyle = alpha(accent, 0.88);
    ctx.beginPath();
    ctx.moveTo(-r * 1.2, -r * 0.1);
    ctx.quadraticCurveTo(0, -r * 0.35, r * 1.2, r * 0.05);
    ctx.lineTo(r * 1.2, r * 1.2);
    ctx.lineTo(-r * 1.2, r * 1.2);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = alpha('#ffffff', 0.22);
    ctx.lineWidth = Math.max(1.4, r * 0.025);
    ctx.stroke();
  } else if (pat === 'dots') {
    ctx.fillStyle = alpha(accent, 0.55);
    for (let yy = -r; yy < r * 1.1; yy += r * 0.33) {
      for (let xx = -r; xx < r * 1.1; xx += r * 0.33) {
        const off = (Math.round(yy / (r * 0.33)) % 2) * r * 0.16;
        ctx.beginPath();
        ctx.arc(xx + off, yy, r * 0.075, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  } else if (pat === 'stripes') {
    ctx.strokeStyle = alpha(accent, 0.6);
    ctx.lineWidth = r * 0.17;
    for (let i = -6; i < 8; i += 1) {
      ctx.beginPath();
      const x = i * r * 0.36;
      ctx.moveTo(x - r, -r * 1.3);
      ctx.lineTo(x + r * 0.9, r * 1.3);
      ctx.stroke();
    }
  } else if (pat === 'swirl') {
    ctx.strokeStyle = alpha(accent, 0.6);
    ctx.lineWidth = r * 0.1;
    ctx.lineCap = 'round';
    for (let k = 0; k < 3; k += 1) {
      ctx.beginPath();
      for (let i = 0; i < 42; i += 1) {
        const a = i * 0.2 + k * 2.1;
        const rad = (i / 42) * r * 0.98;
        const x = Math.cos(a) * rad;
        const y = Math.sin(a) * rad;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
  } else if (pat === 'checker') {
    ctx.fillStyle = alpha(accent, 0.48);
    const s = r * 0.3;
    for (let yy = -5; yy < 5; yy += 1) {
      for (let xx = -5; xx < 5; xx += 1) {
        if ((xx + yy) % 2 === 0) ctx.fillRect(xx * s, yy * s, s, s);
      }
    }
  } else if (pat === 'stars') {
    ctx.fillStyle = alpha(accent, 0.62);
    const rnd = rng(hashString(config.name + config.pattern + config.accent));
    for (let i = 0; i < 16; i += 1) {
      const x = (rnd() * 2 - 1) * r;
      const y = (rnd() * 2 - 1) * r;
      const s = r * (0.045 + rnd() * 0.05);
      ctx.beginPath();
      for (let k = 0; k < 8; k += 1) {
        const a = (k / 8) * Math.PI * 2;
        const rad = k % 2 === 0 ? s : s * 0.4;
        if (k === 0) ctx.moveTo(x + Math.cos(a) * rad, y + Math.sin(a) * rad);
        else ctx.lineTo(x + Math.cos(a) * rad, y + Math.sin(a) * rad);
      }
      ctx.closePath();
      ctx.fill();
    }
  } else if (pat === 'hazard') {
    ctx.fillStyle = alpha(accent, 0.5);
    for (let i = -8; i < 10; i += 2) {
      ctx.beginPath();
      ctx.moveTo(i * r * 0.24, -r * 1.2);
      ctx.lineTo(i * r * 0.24 + r * 0.12, -r * 1.2);
      ctx.lineTo(i * r * 0.24 + r * 1.2, r * 1.2);
      ctx.lineTo(i * r * 0.24 + r * 1.08, r * 1.2);
      ctx.closePath();
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawTexture(ctx, config, r, color) {
  const tex = config.texture;
  ctx.save();
  blobPath(ctx, r * 0.99, 0, 0);
  ctx.clip();
  if (tex === 'pearl') {
    const g = ctx.createLinearGradient(-r, -r, r, r);
    g.addColorStop(0, 'rgba(255,255,255,0.24)');
    g.addColorStop(0.4, 'rgba(120,220,255,0.08)');
    g.addColorStop(0.7, 'rgba(255,150,220,0.12)');
    g.addColorStop(1, 'rgba(255,255,255,0.05)');
    ctx.fillStyle = g;
    ctx.fillRect(-r * 1.1, -r * 1.1, r * 2.2, r * 2.2);
  } else if (tex === 'grit') {
    const rnd = rng(hashString(config.name + 'grit'));
    ctx.fillStyle = alpha('#1b2027', 0.28);
    for (let i = 0; i < 42; i += 1) {
      const a = rnd() * Math.PI * 2;
      const d = Math.sqrt(rnd()) * r;
      ctx.beginPath();
      ctx.arc(Math.cos(a) * d, Math.sin(a) * d, r * (0.008 + rnd() * 0.016), 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (tex === 'matte') {
    ctx.fillStyle = 'rgba(10,12,16,0.12)';
    ctx.fillRect(-r, -r, r * 2, r * 2);
  }
  ctx.restore();

  if (tex === 'gloss' || tex === 'pearl') {
    const hi = ctx.createRadialGradient(-r * 0.36, -r * 0.44, 0, -r * 0.36, -r * 0.44, r * 0.8);
    hi.addColorStop(0, `rgba(255,255,255,${tex === 'gloss' ? 0.55 : 0.38})`);
    hi.addColorStop(0.5, 'rgba(255,255,255,0.09)');
    hi.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = hi;
    ctx.beginPath();
    ctx.ellipse(-r * 0.33, -r * 0.4, r * 0.52, r * 0.31, -0.6, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.beginPath();
    ctx.ellipse(-r * 0.4, -r * 0.47, r * 0.14, r * 0.065, -0.6, 0, Math.PI * 2);
    ctx.fill();
  }
  if (tex === 'gloss') {
    ctx.strokeStyle = 'rgba(255,255,255,0.18)';
    ctx.lineWidth = Math.max(1.5, r * 0.035);
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.86, r * 0.86, 0, Math.PI * 0.15, Math.PI * 0.62);
    ctx.stroke();
  }
  if (tex === 'grit') {
    ctx.strokeStyle = 'rgba(0,0,0,0.22)';
    ctx.lineWidth = Math.max(1, r * 0.02);
    ctx.beginPath();
    ctx.ellipse(r * 0.2, r * 0.25, r * 0.5, r * 0.34, 0.7, 0, Math.PI * 0.5);
    ctx.stroke();
  }
}

function starPath(ctx, x, y, outer, inner, points = 5) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i += 1) {
    const a = (i / (points * 2)) * Math.PI * 2 - Math.PI / 2;
    const rad = i % 2 === 0 ? outer : inner;
    if (i === 0) ctx.moveTo(x + Math.cos(a) * rad, y + Math.sin(a) * rad);
    else ctx.lineTo(x + Math.cos(a) * rad, y + Math.sin(a) * rad);
  }
  ctx.closePath();
}

function drawEyes(ctx, config, r, t, look, blink, expression) {
  const mood = config.mood;
  const eyeY = -r * 0.16;
  const ex = r * 0.31;
  const iris = config.accent;
  const blinkNow = blink || (Math.sin(t * 0.9 + 1.4) > 0.995) || (Math.sin(t * 1.7 + 4.2) > 0.998);
  const lid = Math.max(0.12, Math.abs(blinkNow ? 0.06 : 1));
  const lx = look ? look.x : Math.sin(t * 0.5) * 0.4;
  const ly = look ? look.y : Math.cos(t * 0.7) * 0.3;
  const gaze = { x: lx * r * 0.075, y: ly * r * 0.06 };

  ctx.save();
  ctx.lineCap = 'round';
  const style = config.eyes;

  if (style === 'visor') {
    ctx.fillStyle = 'rgba(8,12,16,0.88)';
    ctx.beginPath();
    ctx.roundRect(-r * 0.58, eyeY - r * 0.18, r * 1.16, r * 0.36, r * 0.16);
    ctx.fill();
    ctx.strokeStyle = alpha(config.glow > 0.2 ? config.accent : '#67e8f9', 0.85);
    ctx.lineWidth = Math.max(1.5, r * 0.03);
    ctx.stroke();
    const glow = config.glow > 0.2 ? config.accent : '#67e8f9';
    ctx.fillStyle = glow;
    ctx.shadowColor = glow;
    ctx.shadowBlur = r * 0.25;
    ctx.beginPath();
    ctx.roundRect(-r * 0.38 + gaze.x, eyeY - r * 0.06, r * 0.22, r * 0.12, r * 0.06);
    ctx.roundRect(r * 0.16 + gaze.x, eyeY - r * 0.06, r * 0.22, r * 0.12, r * 0.06);
    ctx.fill();
    ctx.restore();
    return;
  }

  for (const side of [-1, 1]) {
    const cx = side * ex;
    const w = style === 'wide' ? r * 0.24 : style === 'sleepy' ? r * 0.22 : r * 0.2;
    const h = style === 'wide' ? r * 0.3 : r * 0.24;
    const sy = lid;
    ctx.save();
    ctx.translate(cx, eyeY);
    if (style === 'grumpy' || mood === 'angry') {
      ctx.rotate(side * -0.14);
    }
    ctx.fillStyle = '#f7f2e8';
    ctx.beginPath();
    ctx.ellipse(0, 0, w, h * sy, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#10141a';
    if (style === 'star' && !blinkNow) {
      ctx.shadowColor = config.accent;
      ctx.shadowBlur = r * 0.2;
      starPath(ctx, gaze.x, gaze.y, w * 0.8, w * 0.34, 5);
      ctx.fill();
      ctx.shadowBlur = 0;
    } else {
      ctx.beginPath();
      ctx.ellipse(gaze.x, gaze.y + h * 0.06, w * 0.48, Math.min(h * 0.62, w * 0.56) * sy, 0, 0, Math.PI * 2);
      ctx.fill();
      if (!blinkNow) {
        ctx.fillStyle = 'rgba(255,255,255,0.9)';
        ctx.beginPath();
        ctx.arc(gaze.x - w * 0.18, gaze.y - h * 0.12, Math.max(1.2, w * 0.13), 0, Math.PI * 2);
        ctx.fill();
      }
    }
    if (style === 'sleepy') {
      ctx.fillStyle = alpha(config.color, 1);
      ctx.beginPath();
      ctx.ellipse(0, -h * 0.38, w * 1.06, h * 0.5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#10141a';
      ctx.lineWidth = Math.max(1.4, r * 0.025);
      ctx.beginPath();
      ctx.arc(0, -h * 0.15, w * 0.9, Math.PI * 1.08, Math.PI * 1.92);
      ctx.stroke();
    }
    ctx.restore();

    // brows for mood
    if (style !== 'sleepy') {
      ctx.strokeStyle = 'rgba(15,19,24,0.7)';
      ctx.lineWidth = Math.max(1.5, r * 0.032);
      ctx.beginPath();
      if (mood === 'angry') {
        ctx.moveTo(cx - side * w * 0.8, eyeY - h * 1.15);
        ctx.lineTo(cx + side * w * 0.45, eyeY - h * 0.72);
      } else if (mood === 'scared') {
        ctx.moveTo(cx - side * w * 0.7, eyeY - h * 1.3);
        ctx.lineTo(cx + side * w * 0.55, eyeY - h * 1.22);
      } else if (mood === 'giddy') {
        ctx.moveTo(cx - side * w * 0.65, eyeY - h * 1.22);
        ctx.quadraticCurveTo(cx, eyeY - h * 1.5, cx + side * w * 0.6, eyeY - h * 1.15);
      }
      ctx.stroke();
    }
  }

  ctx.restore();
}

function drawMouth(ctx, config, r, t, expression) {
  const mood = config.mood;
  let style = config.mouth;
  if (expression === 'hit') style = 'ooo';
  if (expression === 'happy') style = 'grin';
  if (expression === 'ko') style = 'flat';
  const y = r * 0.26;
  const w = r * 0.17;
  const dark = 'rgba(22,15,18,0.82)';
  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = dark;
  ctx.lineWidth = Math.max(1.8, r * 0.038);
  if (style === 'smile' || style === 'grin' || style === 'fangs') {
    const grin = style !== 'smile';
    ctx.beginPath();
    ctx.arc(0, y - r * 0.03, w * (grin ? 1.45 : 1.25), 0.18 * Math.PI, 0.82 * Math.PI);
    if (grin) {
      ctx.quadraticCurveTo(0, y + r * 0.13, -w * 1.38, y + r * 0.06);
      ctx.closePath();
      ctx.fillStyle = dark;
      ctx.fill();
      ctx.strokeStyle = alpha('#ffffff', 0.22);
      ctx.lineWidth = 1;
      ctx.stroke();
      if (style === 'fangs') {
        ctx.fillStyle = '#f7f2e8';
        ctx.beginPath();
        ctx.moveTo(-w * 0.95, y + r * 0.01);
        ctx.lineTo(-w * 0.6, y + r * 0.13);
        ctx.lineTo(-w * 0.32, y + r * 0.01);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(w * 0.24, y + r * 0.01);
        ctx.lineTo(w * 0.52, y + r * 0.13);
        ctx.lineTo(w * 0.8, y + r * 0.01);
        ctx.fill();
      } else {
        ctx.strokeStyle = 'rgba(255,255,255,0.16)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-w, y + r * 0.02);
        ctx.lineTo(w, y + r * 0.02);
        ctx.stroke();
      }
    } else {
      ctx.stroke();
    }
  } else if (style === 'ooo') {
    ctx.fillStyle = dark;
    ctx.beginPath();
    ctx.ellipse(0, y + r * 0.02, w * 0.6, w * 0.82, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,120,130,0.55)';
    ctx.beginPath();
    ctx.ellipse(0, y + r * 0.06, w * 0.32, w * 0.33, 0, 0, Math.PI * 2);
    ctx.fill();
  } else if (style === 'flat') {
    ctx.beginPath();
    if (mood === 'scared') {
      ctx.moveTo(-w, y + r * 0.01);
      for (let i = 1; i <= 6; i += 1) {
        ctx.lineTo(-w + (i * w * 2) / 6, y + (i % 2 ? -1 : 1) * r * 0.035);
      }
    } else {
      ctx.moveTo(-w, y);
      ctx.quadraticCurveTo(0, y + r * 0.01, w, y);
    }
    ctx.stroke();
  } else if (style === 'zigzag') {
    ctx.beginPath();
    ctx.moveTo(-w, y);
    for (let i = 1; i <= 5; i += 1) {
      ctx.lineTo(-w + (i * w * 2) / 5, y + (i % 2 ? -1 : 1) * r * 0.055);
    }
    ctx.stroke();
  }
  ctx.restore();
}

function drawCoreBadge(ctx, config, r, t) {
  const colors = { fire: '#ff6b3d', ice: '#67e8f9', electric: '#c084fc', gravity: '#8b5cf6' };
  const c = colors[config.core] || '#ffb545';
  const x = -r * 0.62;
  const y = r * 0.6;
  const s = r * 0.16;
  ctx.save();
  ctx.translate(x, y);
  ctx.shadowColor = c;
  ctx.shadowBlur = r * 0.25;
  ctx.fillStyle = 'rgba(8,11,16,0.7)';
  ctx.beginPath();
  ctx.arc(0, 0, s, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = alpha(c, 0.9);
  ctx.lineWidth = Math.max(1.2, r * 0.025);
  ctx.stroke();
  ctx.fillStyle = c;
  ctx.strokeStyle = c;
  ctx.lineWidth = Math.max(1.3, r * 0.025);
  if (config.core === 'fire') {
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.6);
    ctx.quadraticCurveTo(s * 0.55, -s * 0.05, 0, s * 0.58);
    ctx.quadraticCurveTo(-s * 0.55, -s * 0.05, 0, -s * 0.6);
    ctx.fill();
  } else if (config.core === 'ice') {
    for (let i = 0; i < 3; i += 1) {
      const a = (i / 3) * Math.PI;
      ctx.beginPath();
      ctx.moveTo(-Math.cos(a) * s * 0.55, -Math.sin(a) * s * 0.55);
      ctx.lineTo(Math.cos(a) * s * 0.55, Math.sin(a) * s * 0.55);
      ctx.stroke();
    }
  } else if (config.core === 'electric') {
    ctx.beginPath();
    ctx.moveTo(s * 0.18, -s * 0.62);
    ctx.lineTo(-s * 0.26, s * 0.06);
    ctx.lineTo(s * 0.06, s * 0.06);
    ctx.lineTo(-s * 0.14, s * 0.66);
    ctx.lineTo(s * 0.42, -s * 0.08);
    ctx.lineTo(s * 0.04, -s * 0.08);
    ctx.closePath();
    ctx.fill();
  } else {
    ctx.beginPath();
    ctx.ellipse(0, 0, s * 0.6, s * 0.26, t * 0.6, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, 0, s * 0.28, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

/* ── Gadget attachment drawing ─────────────────────────────────────────── */

function partColor(gadget) {
  return gadget.color || '#b9c6d6';
}

export function drawPart(ctx, kind, s, gadget, t, config) {
  const col = partColor(gadget);
  const dark = darken(col, 0.34);
  const light = lighten(col, 0.38);
  const line = Math.max(1.5, s * 0.09);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  switch (kind) {
    case 'spike': {
      const grad = ctx.createLinearGradient(0, 0, s * 1.25, 0);
      grad.addColorStop(0, dark);
      grad.addColorStop(0.55, light);
      grad.addColorStop(1, '#f7f2e8');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(0, -s * 0.34);
      ctx.lineTo(s * 1.25, 0);
      ctx.lineTo(0, s * 0.34);
      ctx.quadraticCurveTo(-s * 0.1, 0, 0, -s * 0.34);
      ctx.fill();
      ctx.strokeStyle = 'rgba(8,11,16,0.35)';
      ctx.lineWidth = 1;
      ctx.stroke();
      break;
    }
    case 'drill': {
      ctx.fillStyle = dark;
      ctx.beginPath();
      ctx.moveTo(0, -s * 0.32);
      ctx.lineTo(s * 1.15, 0);
      ctx.lineTo(0, s * 0.32);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = light;
      ctx.lineWidth = line * 0.6;
      for (let i = 0; i < 3; i += 1) {
        ctx.beginPath();
        ctx.moveTo(s * (0.25 + i * 0.25), -s * 0.22 + i * s * 0.12);
        ctx.lineTo(s * (0.1 + i * 0.25), s * 0.2 - i * s * 0.1);
        ctx.stroke();
      }
      break;
    }
    case 'arm': {
      ctx.strokeStyle = col;
      ctx.lineWidth = s * 0.3;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(s * 0.45, -s * 0.28, s * 0.95, 0);
      ctx.stroke();
      ctx.fillStyle = light;
      ctx.strokeStyle = dark;
      ctx.lineWidth = line * 0.5;
      ctx.beginPath();
      ctx.arc(s * 1.02, 0, s * 0.28, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      break;
    }
    case 'leg': {
      const wob = Math.sin(t * 3 + s) * s * 0.04;
      ctx.strokeStyle = col;
      ctx.lineWidth = s * 0.26;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(s * 0.72, wob);
      ctx.stroke();
      ctx.fillStyle = dark;
      ctx.beginPath();
      ctx.ellipse(s * 0.9, wob + s * 0.05, s * 0.35, s * 0.19, 0.15, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'wing': {
      const flap = Math.sin(t * 5 + 1) * 0.12;
      ctx.save();
      ctx.rotate(flap);
      for (let i = 0; i < 3; i += 1) {
        ctx.fillStyle = alpha(col, 0.62 - i * 0.12);
        ctx.strokeStyle = alpha(light, 0.7);
        ctx.lineWidth = line * 0.4;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(s * (0.5 + i * 0.16), -s * (0.42 + i * 0.12), s * (1.1 + i * 0.05), -s * (0.2 + i * 0.2));
        ctx.quadraticCurveTo(s * (0.62 + i * 0.1), s * (0.06 + i * 0.04), 0, 0);
        ctx.fill();
        ctx.stroke();
      }
      ctx.restore();
      break;
    }
    case 'tentacle': {
      ctx.strokeStyle = col;
      ctx.lineWidth = s * 0.22;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      const seg = 4;
      for (let i = 1; i <= seg; i += 1) {
        const p = i / seg;
        ctx.quadraticCurveTo(
          s * p * 0.9,
          Math.sin(t * 2 + i * 1.2) * s * 0.22 * p,
          s * p * 1.0,
          Math.sin(t * 2 + i * 1.6) * s * 0.3,
        );
      }
      ctx.stroke();
      ctx.fillStyle = light;
      ctx.beginPath();
      ctx.arc(s, Math.sin(t * 2 + 4) * s * 0.12, s * 0.09, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'spring': {
      ctx.strokeStyle = col;
      ctx.lineWidth = line;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      const coils = 4;
      for (let i = 0; i < coils * 2; i += 1) {
        const x = s * 0.15 + (i / (coils * 2)) * s * 0.7;
        ctx.lineTo(x, (i % 2 ? 1 : -1) * s * 0.25);
      }
      ctx.lineTo(s * 0.96, 0);
      ctx.stroke();
      ctx.fillStyle = light;
      ctx.beginPath();
      ctx.ellipse(s * 1.04, 0, s * 0.17, s * 0.26, 0, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'tread': {
      ctx.save();
      ctx.translate(s * 0.36, 0);
      ctx.fillStyle = 'rgba(10,14,19,0.85)';
      ctx.beginPath();
      ctx.roundRect(-s * 0.5, -s * 0.32, s * 1.0, s * 0.64, s * 0.24);
      ctx.fill();
      ctx.strokeStyle = alpha(col, 0.85);
      ctx.lineWidth = line * 0.5;
      ctx.stroke();
      ctx.fillStyle = col;
      for (let i = -1; i <= 1; i += 1) {
        ctx.beginPath();
        ctx.arc(i * s * 0.3, 0, s * 0.14, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
      break;
    }
    case 'hammer': {
      ctx.strokeStyle = dark;
      ctx.lineWidth = line;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(s * 0.8, 0);
      ctx.stroke();
      ctx.save();
      ctx.translate(s * 0.88, 0);
      ctx.rotate(-0.28);
      ctx.fillStyle = col;
      ctx.strokeStyle = dark;
      ctx.lineWidth = line * 0.45;
      ctx.beginPath();
      ctx.roundRect(-s * 0.13, -s * 0.42, s * 0.44, s * 0.84, s * 0.08);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = light;
      ctx.fillRect(-s * 0.05, -s * 0.35, s * 0.08, s * 0.7);
      ctx.restore();
      break;
    }
    case 'saw': {
      ctx.save();
      ctx.translate(s * 0.55, 0);
      ctx.rotate(t * 7);
      ctx.fillStyle = col;
      ctx.beginPath();
      const teeth = 9;
      for (let i = 0; i < teeth * 2; i += 1) {
        const a = (i / (teeth * 2)) * Math.PI * 2;
        const rad = i % 2 === 0 ? s * 0.5 : s * 0.35;
        if (i === 0) ctx.moveTo(Math.cos(a) * rad, Math.sin(a) * rad);
        else ctx.lineTo(Math.cos(a) * rad, Math.sin(a) * rad);
      }
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = 'rgba(10,14,19,0.8)';
      ctx.beginPath();
      ctx.arc(0, 0, s * 0.13, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      break;
    }
    case 'tail': {
      ctx.strokeStyle = col;
      ctx.lineWidth = s * 0.2;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(s * 0.6, -s * 0.1, s * 0.9, s * 0.35);
      ctx.stroke();
      ctx.fillStyle = light;
      ctx.beginPath();
      const tx = s * 0.95;
      const ty = s * 0.38;
      ctx.moveTo(tx, ty - s * 0.2);
      ctx.lineTo(tx + s * 0.3, ty + s * 0.05);
      ctx.lineTo(tx - s * 0.02, ty + s * 0.18);
      ctx.closePath();
      ctx.fill();
      break;
    }
    case 'cannon': {
      ctx.fillStyle = dark;
      ctx.beginPath();
      ctx.roundRect(0, -s * 0.22, s * 0.95, s * 0.44, s * 0.1);
      ctx.fill();
      ctx.strokeStyle = col;
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.roundRect(s * 0.82, -s * 0.28, s * 0.22, s * 0.56, s * 0.06);
      ctx.fill();
      ctx.fillStyle = alpha(col, 0.5);
      ctx.beginPath();
      ctx.arc(s * 0.95, 0, s * (0.1 + Math.sin(t * 5) * 0.03), 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'eye': {
      ctx.fillStyle = '#f7f2e8';
      ctx.beginPath();
      ctx.ellipse(s * 0.45, 0, s * 0.48, s * 0.4, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.arc(s * 0.55, 0, s * 0.22, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#10141a';
      ctx.beginPath();
      ctx.arc(s * 0.58, 0, s * 0.09, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'fang': {
      ctx.fillStyle = '#f7f2e8';
      ctx.beginPath();
      ctx.moveTo(s * 0.15, -s * 0.28);
      ctx.lineTo(s * 0.72, -s * 0.06);
      ctx.lineTo(s * 0.2, s * 0.04);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(s * 0.22, s * 0.18);
      ctx.lineTo(s * 0.78, s * 0.24);
      ctx.lineTo(s * 0.24, s * 0.42);
      ctx.closePath();
      ctx.fill();
      break;
    }
    case 'rocket': {
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.roundRect(0, -s * 0.18, s * 0.72, s * 0.36, s * 0.16);
      ctx.fill();
      ctx.fillStyle = dark;
      ctx.beginPath();
      ctx.moveTo(s * 0.42, -s * 0.18);
      ctx.lineTo(s * 0.64, -s * 0.36);
      ctx.lineTo(s * 0.72, -s * 0.18);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(s * 0.42, s * 0.18);
      ctx.lineTo(s * 0.64, s * 0.36);
      ctx.lineTo(s * 0.72, s * 0.18);
      ctx.closePath();
      ctx.fill();
      const flame = s * (0.28 + Math.sin(t * 20) * 0.08);
      const fg = ctx.createLinearGradient(0, 0, -flame, 0);
      fg.addColorStop(0, 'rgba(255,220,120,0.95)');
      fg.addColorStop(0.5, 'rgba(255,120,50,0.7)');
      fg.addColorStop(1, 'rgba(255,80,50,0)');
      ctx.fillStyle = fg;
      ctx.beginPath();
      ctx.moveTo(0, -s * 0.16);
      ctx.lineTo(-flame, 0);
      ctx.lineTo(0, s * 0.16);
      ctx.fill();
      break;
    }
    case 'hook': {
      ctx.strokeStyle = col;
      ctx.lineWidth = line;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(s * 0.5, 0);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(s * 0.62, s * 0.12, s * 0.28, Math.PI * 0.9, Math.PI * 2.15);
      ctx.stroke();
      ctx.fillStyle = light;
      ctx.beginPath();
      ctx.arc(s * 0.9, s * 0.06, s * 0.07, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'bubble': {
      const r = s * 0.9;
      const g = ctx.createRadialGradient(-r * 0.3, -r * 0.3, r * 0.1, 0, 0, r);
      g.addColorStop(0, 'rgba(255,255,255,0.22)');
      g.addColorStop(0.7, alpha(col, 0.1));
      g.addColorStop(1, alpha(col, 0.28));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(s * 0.5, 0, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = alpha(col, 0.55);
      ctx.lineWidth = line * 0.5;
      ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,0.6)';
      ctx.beginPath();
      ctx.arc(s * 0.5, 0, r * 0.8, Math.PI * 1.05, Math.PI * 1.6);
      ctx.stroke();
      break;
    }
    case 'magnet': {
      ctx.strokeStyle = col;
      ctx.lineWidth = s * 0.22;
      ctx.beginPath();
      ctx.arc(s * 0.5, 0, s * 0.34, Math.PI * 0.15, Math.PI * 1.1);
      ctx.stroke();
      ctx.strokeStyle = '#ff5d5d';
      ctx.beginPath();
      ctx.moveTo(s * 0.5 + Math.cos(Math.PI * 0.15) * s * 0.34, Math.sin(Math.PI * 0.15) * s * 0.34);
      ctx.lineTo(s * 0.5 + Math.cos(Math.PI * 0.15) * s * 0.34 + s * 0.2, Math.sin(Math.PI * 0.15) * s * 0.34);
      ctx.stroke();
      break;
    }
    case 'hat': {
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.moveTo(0, -s * 0.3);
      ctx.lineTo(s * 0.82, 0);
      ctx.lineTo(0, s * 0.3);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = dark;
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = light;
      ctx.beginPath();
      ctx.arc(s * 0.84, 0, s * 0.11, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'orb': {
      ctx.shadowColor = col;
      ctx.shadowBlur = s * 0.5;
      const og = ctx.createRadialGradient(s * 0.4, -s * 0.2, 0, s * 0.5, 0, s * 0.48);
      og.addColorStop(0, light);
      og.addColorStop(0.6, col);
      og.addColorStop(1, dark);
      ctx.fillStyle = og;
      ctx.beginPath();
      ctx.arc(s * 0.55, 0, s * 0.46, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.strokeStyle = alpha('#ffffff', 0.4);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(s * 0.55, 0, s * 0.34, Math.PI * 1.1, Math.PI * 1.7);
      ctx.stroke();
      break;
    }
    case 'blade': {
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.moveTo(0, -s * 0.2);
      ctx.quadraticCurveTo(s * 0.8, -s * 0.55, s * 1.22, 0);
      ctx.quadraticCurveTo(s * 0.6, s * 0.06, 0, s * 0.2);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = alpha('#ffffff', 0.55);
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(s * 0.18, -s * 0.08);
      ctx.quadraticCurveTo(s * 0.7, -s * 0.26, s * 1.02, -s * 0.02);
      ctx.stroke();
      break;
    }
    case 'claw': {
      ctx.strokeStyle = col;
      ctx.lineWidth = s * 0.18;
      for (let i = -1; i <= 1; i += 1) {
        ctx.beginPath();
        ctx.moveTo(s * 0.1, i * s * 0.16);
        ctx.quadraticCurveTo(s * 0.65, i * s * 0.36 - s * 0.1, s * 0.9, i * s * 0.34 + s * 0.18);
        ctx.stroke();
      }
      break;
    }
    case 'antenna': {
      ctx.strokeStyle = col;
      ctx.lineWidth = line * 0.65;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(s * 0.4, -s * 0.18, s * 0.84, -s * 0.08);
      ctx.stroke();
      ctx.shadowColor = gadget.color;
      ctx.shadowBlur = s * 0.4;
      ctx.fillStyle = light;
      ctx.beginPath();
      ctx.arc(s * 0.88, -s * 0.09, s * 0.16, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
      break;
    }
    default: {
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.arc(s * 0.5, 0, s * 0.3, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function drawParts(ctx, layouts, r, t, config, behind, alphaMul = 1) {
  for (const part of layouts) {
    if (part.behind !== behind) continue;
    ctx.save();
    ctx.globalAlpha = alphaMul;
    ctx.rotate(part.angle);
    ctx.translate(r * part.dist, 0);
    if (part.flip) ctx.scale(1, -1);
    drawPart(ctx, part.gadget.visual, r * part.size, part.gadget, t, config);
    ctx.restore();
  }
}

/* Main blob draw */
export function drawBlob(ctx, opts) {
  const {
    x, y, r, config, t = 0, face = null, expression = null, alpha: opacity = 1,
    glow = 0, squashDir = null, speedRatio = 0, noShadow = false, blink = false,
    layouts = [], showParts = true,
  } = opts;

  const color = config.color || '#ffb545';
  const accent = config.accent || '#ff6b3d';
  const glowColor = { fire: '#ff6b3d', ice: '#67e8f9', electric: '#c084fc', gravity: '#8b5cf6' }[config.core] || color;
  const squash = config.squash ?? 0.3;

  ctx.save();
  ctx.globalAlpha = opacity;

  if (!noShadow) {
    const sh = ctx.createRadialGradient(x, y + r * 0.96, 0, x, y + r * 0.96, r * 1.1);
    sh.addColorStop(0, 'rgba(0,0,0,0.38)');
    sh.addColorStop(0.6, 'rgba(0,0,0,0.13)');
    sh.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = sh;
    ctx.beginPath();
    ctx.ellipse(x, y + r * 0.97, r * 0.92, r * 0.26, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  if (config.glow > 0 || glow > 0) {
    const strength = (config.glow || 0) * 0.65 + glow;
    const g = ctx.createRadialGradient(x, y, r * 0.35, x, y, r * (1.5 + strength * 0.5));
    g.addColorStop(0, alpha(glowColor, 0.26 * Math.min(1, strength)));
    g.addColorStop(0.6, alpha(glowColor, 0.09 * Math.min(1, strength)));
    g.addColorStop(1, alpha(glowColor, 0));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r * (1.55 + strength * 0.5), 0, Math.PI * 2);
    ctx.fill();
  }

  // aura ring when dashing / powered
  if (glow > 0.05) {
    ctx.strokeStyle = alpha(glowColor, Math.min(0.7, glow * 0.7));
    ctx.lineWidth = Math.max(1.4, r * 0.035);
    ctx.beginPath();
    ctx.arc(x, y, r * (1.18 + Math.sin(t * 3) * 0.03), 0, Math.PI * 2);
    ctx.stroke();
  }

  if (showParts) {
    ctx.save();
    ctx.translate(x, y);
    if (squashDir !== null) {
      ctx.rotate(squashDir);
      ctx.scale(1 + speedRatio * 0.1, 1 - speedRatio * 0.07);
      ctx.rotate(-squashDir);
    } else {
      ctx.scale(1 + squash * 0.08, 1 - squash * 0.07);
    }
    drawParts(ctx, layouts, r, t, config, true);
    ctx.restore();
  }

  ctx.save();
  ctx.translate(x, y);
  if (squashDir !== null) {
    ctx.rotate(squashDir);
    ctx.scale(1 + speedRatio * 0.13, 1 - speedRatio * 0.1);
    ctx.rotate(-squashDir);
  } else {
    ctx.scale(1 + squash * 0.12, 1 - squash * 0.1);
  }

  const grad = ctx.createRadialGradient(-r * 0.34, -r * 0.42, r * 0.06, 0, 0, r * 1.16);
  grad.addColorStop(0, mix(color, '#ffffff', 0.48));
  grad.addColorStop(0.35, mix(color, '#ffffff', 0.16));
  grad.addColorStop(0.72, color);
  grad.addColorStop(1, darken(color, 0.4));
  ctx.fillStyle = grad;
  blobPath(ctx, r, t, 1);
  ctx.fill();

  if (config.material === 'metal') {
    const sheen = ctx.createLinearGradient(-r, -r, r, r);
    sheen.addColorStop(0, 'rgba(255,255,255,0.34)');
    sheen.addColorStop(0.28, 'rgba(255,255,255,0.04)');
    sheen.addColorStop(0.52, 'rgba(0,0,0,0.18)');
    sheen.addColorStop(0.7, 'rgba(255,255,255,0.1)');
    sheen.addColorStop(1, 'rgba(0,0,0,0.28)');
    ctx.fillStyle = sheen;
    blobPath(ctx, r, t, 1);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.5)';
    ctx.lineWidth = Math.max(1.2, r * 0.024);
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.72, r * 0.72, -0.5, Math.PI * 1.15, Math.PI * 1.52);
    ctx.stroke();
  } else if (config.material === 'jelly') {
    ctx.globalAlpha = opacity * 0.35;
    ctx.fillStyle = lighten(color, 0.55);
    ctx.beginPath();
    ctx.ellipse(0, r * 0.12, r * 0.72, r * 0.6, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = opacity;
    ctx.strokeStyle = 'rgba(255,255,255,0.4)';
    ctx.lineWidth = Math.max(1.4, r * 0.03);
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 0.9, 0, Math.PI * 0.1, Math.PI * 0.5);
    ctx.stroke();
  } else if (config.material === 'stone') {
    const rnd = rng(hashString(config.name + 'stone'));
    ctx.fillStyle = 'rgba(20,24,28,0.24)';
    for (let i = 0; i < 26; i += 1) {
      const a = rnd() * Math.PI * 2;
      const d = Math.sqrt(rnd()) * r * 0.86;
      ctx.beginPath();
      ctx.ellipse(Math.cos(a) * d, Math.sin(a) * d, r * (0.012 + rnd() * 0.03), r * (0.008 + rnd() * 0.018), rnd() * 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  drawPattern(ctx, config, r, accent);
  drawTexture(ctx, config, r, color);

  ctx.strokeStyle = 'rgba(8,11,15,0.28)';
  ctx.lineWidth = Math.max(1.5, r * 0.03);
  blobPath(ctx, r * 0.985, t, 1);
  ctx.stroke();

  if ((config.glow || 0) > 0.12) {
    ctx.strokeStyle = alpha(glowColor, Math.min(0.7, config.glow * 0.55));
    ctx.lineWidth = Math.max(1, r * 0.02);
    blobPath(ctx, r * 0.93, t, 1);
    ctx.stroke();
  }

  ctx.fillStyle = 'rgba(255,255,255,0.16)';
  ctx.beginPath();
  ctx.ellipse(-r * 0.38, -r * 0.45, r * 0.22, r * 0.1, -0.7, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();

  drawEyes(ctx, config, r, t, face, blink, expression);
  drawMouth(ctx, config, r, t, expression);
  drawCoreBadge(ctx, config, r, t);

  if (showParts) {
    ctx.save();
    ctx.translate(x, y);
    if (squashDir !== null) {
      ctx.rotate(squashDir);
      ctx.scale(1 + speedRatio * 0.13, 1 - speedRatio * 0.1);
      ctx.rotate(-squashDir);
    } else {
      ctx.scale(1 + squash * 0.12, 1 - squash * 0.1);
    }
    drawParts(ctx, layouts, r, t, config, false);
    ctx.restore();
  }

  ctx.restore();
}

/* Small portrait used by cards / results */
export function drawPortrait(canvas, config, layouts, size = 96) {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = size * dpr;
  canvas.height = size * dpr;
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, size, size);
  drawBlob(ctx, {
    x: size / 2, y: size * 0.53, r: size * 0.32, config,
    t: 1.1, layouts, squashDir: null, showParts: true,
  });
}

/* Tiny procedural audio engine — no external assets. */

const NOTE = (n) => 440 * Math.pow(2, (n - 69) / 12);

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.musicTimer = null;
    this.musicMode = 'workshop';
    this.step = 0;
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    this.master.connect(this.ctx.destination);
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.5, this.ctx.currentTime, 0.05);
    }
  }

  tone({ freq = 440, dur = 0.12, type = 'sine', gain = 0.16, slide = 0, delay = 0, detune = 0 }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    if (detune) osc.detune.value = detune;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  noise(dur = 0.12, gain = 0.12, freq = 900, type = 'lowpass') {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const len = Math.floor(this.ctx.sampleRate * dur);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i += 1) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    const g = this.ctx.createGain();
    g.gain.value = gain;
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(t);
  }

  click() {
    this.ensure();
    this.tone({ freq: 620, dur: 0.055, type: 'triangle', gain: 0.08, slide: 120 });
  }

  hover() {
    this.tone({ freq: 880, dur: 0.03, type: 'sine', gain: 0.025 });
  }

  equip() {
    this.ensure();
    this.tone({ freq: 330, dur: 0.09, type: 'square', gain: 0.05 });
    this.tone({ freq: 494, dur: 0.12, type: 'triangle', gain: 0.07, delay: 0.06 });
  }

  unequip() {
    this.tone({ freq: 420, dur: 0.07, type: 'square', gain: 0.04, slide: -120 });
  }

  denied() {
    this.tone({ freq: 170, dur: 0.11, type: 'sawtooth', gain: 0.05 });
    this.tone({ freq: 150, dur: 0.14, type: 'sawtooth', gain: 0.04, delay: 0.08 });
  }

  coin() {
    this.ensure();
    this.tone({ freq: NOTE(84), dur: 0.08, type: 'triangle', gain: 0.08 });
    this.tone({ freq: NOTE(91), dur: 0.15, type: 'triangle', gain: 0.06, delay: 0.06 });
  }

  bump(power = 1) {
    const p = Math.min(2, power);
    this.noise(0.09 + p * 0.04, 0.06 + p * 0.05, 420 + p * 300);
    this.tone({ freq: 100 + p * 55, dur: 0.13, type: 'sine', gain: 0.1 * p, slide: -40 });
  }

  dash() {
    this.noise(0.18, 0.06, 1400, 'bandpass');
    this.tone({ freq: 180, dur: 0.16, type: 'sawtooth', gain: 0.05, slide: 300 });
  }

  core(kind) {
    this.ensure();
    const base = { fire: 220, ice: 660, electric: 330, gravity: 110 }[kind] || 220;
    this.noise(0.3, 0.06, 600);
    for (let i = 0; i < 4; i += 1) {
      this.tone({
        freq: base * (1 + i * 0.5), dur: 0.25, type: i % 2 ? 'triangle' : 'sine',
        gain: 0.09, delay: i * 0.035, slide: 80,
      });
    }
  }

  hit(power = 1) {
    this.bump(Math.max(0.6, power * 0.7));
    this.tone({ freq: 900, dur: 0.05, type: 'square', gain: 0.03, slide: -300 });
  }

  ringout() {
    this.ensure();
    this.tone({ freq: 300, dur: 0.5, type: 'sawtooth', gain: 0.08, slide: -220 });
    this.noise(0.5, 0.09, 500);
  }

  win() {
    this.ensure();
    const seq = [60, 64, 67, 72, 76];
    seq.forEach((n, i) => {
      this.tone({ freq: NOTE(n), dur: 0.22, type: 'triangle', gain: 0.12, delay: i * 0.12 });
      this.tone({ freq: NOTE(n + 12), dur: 0.2, type: 'sine', gain: 0.05, delay: i * 0.12 + 0.02 });
    });
  }

  lose() {
    this.ensure();
    const seq = [60, 57, 53, 48];
    seq.forEach((n, i) => {
      this.tone({ freq: NOTE(n), dur: 0.28, type: 'sawtooth', gain: 0.08, delay: i * 0.15 });
    });
  }

  unlock() {
    this.ensure();
    this.tone({ freq: 440, dur: 0.1, type: 'triangle', gain: 0.1 });
    this.tone({ freq: 660, dur: 0.12, type: 'triangle', gain: 0.09, delay: 0.08 });
    this.tone({ freq: 880, dur: 0.26, type: 'sine', gain: 0.1, delay: 0.17 });
  }

  voice(mood = 'bold', voiceId = 'squeak') {
    this.ensure();
    const pitch = { squeak: 1.7, baritone: 0.6, glitch: 1.05, choir: 0.95 }[voiceId] || 1;
    const base = { angry: 130, calm: 240, scared: 330, bold: 190, giddy: 300 }[mood] || 200;
    const type = { squeak: 'triangle', baritone: 'sine', glitch: 'square', choir: 'sine' }[voiceId] || 'triangle';
    this.tone({ freq: base * pitch, dur: 0.11, type, gain: 0.07, slide: 70 * pitch });
    this.tone({ freq: base * pitch * 0.82, dur: 0.14, type, gain: 0.05, delay: 0.1, slide: -30 });
  }

  startMusic(mode = 'workshop') {
    this.ensure();
    if (!this.ctx) return;
    if (this.musicMode === mode && this.musicTimer) return;
    this.musicMode = mode;
    if (this.musicTimer) clearInterval(this.musicTimer);
    const sequences = {
      workshop: [48, 55, 53, 51],
      arena: [45, 48, 45, 43, 50, 48, 45, 41],
      boss: [40, 40, 43, 40, 38, 40, 46, 43],
    };
    const seq = sequences[mode] || sequences.workshop;
    const tempo = mode === 'workshop' ? 1400 : 560;
    this.step = 0;
    const play = () => {
      if (!this.ctx || this.muted) return;
      const n = seq[this.step % seq.length];
      const t = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = mode === 'boss' ? 380 : 620;
      osc.type = mode === 'workshop' ? 'sine' : 'triangle';
      osc.frequency.value = NOTE(n);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(mode === 'workshop' ? 0.018 : 0.035, t + 0.06);
      g.gain.exponentialRampToValueAtTime(0.0001, t + tempo / 1000 * 0.9);
      osc.connect(filter);
      filter.connect(g);
      g.connect(this.master);
      osc.start(t);
      osc.stop(t + tempo / 1000);
      if (mode !== 'workshop' && this.step % 2 === 0) {
        const hat = this.ctx.createBufferSource();
        const len = Math.floor(this.ctx.sampleRate * 0.04);
        const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
        const d = buf.getChannelData(0);
        for (let i = 0; i < len; i += 1) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
        hat.buffer = buf;
        const hp = this.ctx.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = 6000;
        const hg = this.ctx.createGain();
        hg.gain.value = 0.018;
        hat.connect(hp); hp.connect(hg); hg.connect(this.master);
        hat.start(t);
      }
      this.step += 1;
    };
    play();
    this.musicTimer = setInterval(play, tempo);
  }

  stopMusic() {
    if (this.musicTimer) clearInterval(this.musicTimer);
    this.musicTimer = null;
    this.musicMode = null;
  }
}

export const audio = new AudioEngine();

/* ═══════════════════════════════════════════════════════════════
   BLOBSMITH — Ball Foundry
   ═══════════════════════════════════════════════════════════════ */

:root {
  --bg: #080b10;
  --bg-2: #0b0f15;
  --panel: #10151c;
  --panel-2: #0d1218;
  --panel-3: #151b23;
  --line: rgba(247, 242, 232, 0.09);
  --line-strong: rgba(247, 242, 232, 0.17);
  --cream: #f7f2e8;
  --muted: #8e9aa8;
  --muted-2: #636e7b;
  --amber: #ffb545;
  --orange: #ff6b3d;
  --teal: #5ce1c6;
  --pink: #ff9ed2;
  --blue: #67e8f9;
  --lime: #a7f36b;
  --violet: #c084fc;
  --red: #ff5d5d;
  --radius: 20px;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
  --display: 'Bricolage Grotesque', 'Arial Black', sans-serif;
  --body: 'Space Grotesk', ui-sans-serif, system-ui, sans-serif;
  --mono: 'JetBrains Mono', ui-monospace, monospace;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
html { background: var(--bg); }
body {
  background:
    radial-gradient(ellipse 90% 60% at 50% -20%, rgba(255, 181, 69, 0.08), transparent 60%),
    radial-gradient(ellipse 60% 50% at 100% 100%, rgba(92, 225, 198, 0.05), transparent 65%),
    var(--bg);
  color: var(--cream);
  font-family: var(--body);
  font-size: 14px;
  line-height: 1.45;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button, input { font-family: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
button:focus-visible, input:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid var(--amber);
  outline-offset: 2px;
}
::selection { background: var(--amber); color: #131313; }
.hidden { display: none !important; }
.mono { font-family: var(--mono); font-size: 10px; letter-spacing: 0.08em; }
.muted { color: var(--muted); }
.small { font-size: 12px; }
.eyebrow {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.19em;
  color: var(--muted);
  text-transform: uppercase;
}
h1, h2, h3, p { margin: 0; }

/* ── app frame ─────────────────────────────────────────────── */
.app-shell { height: 100dvh; display: flex; flex-direction: column; }

.topbar {
  height: 66px;
  flex: 0 0 66px;
  display: flex;
  align-items: center;
  gap: 26px;
  padding: 0 22px;
  border-bottom: 1px solid var(--line);
  background: rgba(8, 11, 16, 0.86);
  backdrop-filter: blur(18px);
  z-index: 40;
  position: relative;
}
.app-shell.playing .topbar { display: none; }
.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0;
  text-align: left;
}
.brand-mark { width: 38px; height: 38px; display: grid; place-items: center; filter: drop-shadow(0 0 14px rgba(255, 181, 69, 0.25)); }
.brand-mark svg { width: 38px; height: 38px; }
.brand-text {
  font-family: var(--display);
  font-weight: 800;
  font-size: 21px;
  letter-spacing: 0.015em;
  line-height: 0.93;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.brand-text small {
  font-family: var(--mono);
  font-weight: 500;
  font-size: 7.5px;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.mainnav { display: flex; gap: 4px; height: 100%; align-items: center; }
.mainnav button {
  height: 38px;
  padding: 0 18px;
  border-radius: 10px;
  font-family: var(--mono);
  font-weight: 700;
  font-size: 10.5px;
  letter-spacing: 0.13em;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 9px;
  transition: 0.18s ease;
  border: 1px solid transparent;
}
.mainnav button span { font-size: 8px; color: var(--muted-2); }
.mainnav button:hover { color: var(--cream); background: rgba(255, 255, 255, 0.035); }
.mainnav button.active {
  color: var(--cream);
  background: rgba(255, 181, 69, 0.08);
  border-color: rgba(255, 181, 69, 0.25);
}
.mainnav button.active span { color: var(--amber); }

.topbar-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }
.wallet { display: flex; gap: 6px; margin-right: 4px; }
.wallet-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 30px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.025);
  font-family: var(--mono);
  font-size: 11px;
}
.wallet-chip i { font-style: normal; color: var(--amber); font-size: 11px; }
.wallet-chip.core i { color: var(--violet); }
.wallet-chip b { font-weight: 700; color: var(--cream); }
.icon-btn {
  width: 32px; height: 32px;
  border: 1px solid var(--line);
  border-radius: 50%;
  display: grid; place-items: center;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 12px;
  transition: 0.18s;
}
.icon-btn:hover { color: var(--cream); border-color: var(--line-strong); background: rgba(255,255,255,0.04); }
.icon-btn.off { color: var(--muted-2); text-decoration: line-through; }

main { flex: 1; min-height: 0; position: relative; }
.screen { display: none; height: 100%; overflow: hidden; }
.screen.active { display: block; animation: screenIn 0.4s ease both; }
@keyframes screenIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

/* ── workshop layout ───────────────────────────────────────── */
.workshop-grid {
  height: 100%;
  display: grid;
  grid-template-columns: 294px minmax(0, 1fr) 382px;
  gap: 13px;
  padding: 13px 16px 16px;
}
.panel {
  background: linear-gradient(165deg, rgba(22, 28, 37, 0.92), rgba(11, 15, 21, 0.96));
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035), 0 20px 50px rgba(0, 0, 0, 0.18);
  min-height: 0;
}

/* stats panel */
.stats-panel {
  padding: 17px 16px 15px;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.12) transparent;
}
.panel-head { display: flex; justify-content: space-between; align-items: center; }
.live-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 0 4px rgba(167, 243, 107, 0.09), 0 0 10px var(--lime);
  animation: pulse 2.4s infinite;
}
@keyframes pulse { 50% { opacity: 0.4; } }
.name-line { display: flex; align-items: center; gap: 6px; margin: 10px 0 2px; }
.name-input {
  background: none;
  border: 0;
  border-bottom: 1px dashed transparent;
  padding: 0;
  width: 100%;
  font-family: var(--display);
  font-size: 33px;
  font-weight: 800;
  letter-spacing: 0.01em;
  line-height: 1.15;
  color: var(--cream);
  text-transform: uppercase;
  transition: border-color 0.2s;
  min-width: 0;
}
.name-input:hover { border-bottom-color: var(--line-strong); }
.name-input:focus { outline: none; border-bottom-color: var(--amber); }
.dice-btn {
  flex: 0 0 26px; width: 26px; height: 26px;
  border-radius: 50%;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
  transition: 0.2s;
}
.dice-btn:hover { color: var(--amber); border-color: var(--amber); transform: rotate(90deg); }

.build-tags { display: flex; flex-wrap: wrap; gap: 4px; min-height: 18px; margin-top: 4px; }
.build-tag {
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.11em;
  padding: 3px 7px;
  border-radius: 99px;
  border: 1px solid currentColor;
  opacity: 0.82;
  white-space: nowrap;
}
.build-tag.empty { color: var(--muted-2); border-color: var(--line); }

.budget-stack { margin-top: 16px; display: flex; flex-direction: column; gap: 12px; }
.budget-top { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 5px; }
.budget-top > span { font-family: var(--mono); font-size: 9px; letter-spacing: 0.14em; color: var(--muted); }
.budget-top b { font-family: var(--mono); font-size: 13px; font-weight: 700; }
.budget-top b em { font-style: normal; color: var(--amber); }
.budget-top b small { color: var(--muted-2); font-size: 10px; font-weight: 500; margin-left: 3px; }
.budget-bar { height: 7px; border-radius: 99px; background: rgba(255, 255, 255, 0.055); overflow: hidden; }
.budget-bar i {
  display: block; height: 100%; width: 0%;
  border-radius: 99px;
  background: linear-gradient(90deg, #ff9c3c, var(--amber));
  box-shadow: 0 0 10px rgba(255, 181, 69, 0.4);
  transition: width 0.35s cubic-bezier(0.22, 1, 0.36, 1), background 0.3s;
}
.budget.energy .budget-top b em { color: var(--teal); }
.budget.energy .budget-bar i { background: linear-gradient(90deg, #36b9b0, var(--teal)); box-shadow: 0 0 10px rgba(92, 225, 198, 0.35); }
.budget.over .budget-top b em { color: var(--red); }
.budget.over .budget-bar i { background: linear-gradient(90deg, #ff5d5d, #ff8f5d); box-shadow: 0 0 12px rgba(255, 93, 93, 0.5); }

.rule { height: 1px; background: var(--line); margin: 16px 0 13px; }
.stats-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 11px; }
.stats-head span:first-child { font-family: var(--mono); font-size: 9px; letter-spacing: 0.16em; color: var(--muted); }
.stats-head .mono { color: var(--muted-2); }
.stat-list { display: flex; flex-direction: column; gap: 9px; }
.stat-row { display: grid; grid-template-columns: 60px 1fr 34px; align-items: center; gap: 8px; }
.stat-row .label { font-family: var(--mono); font-size: 9px; letter-spacing: 0.1em; color: var(--muted); }
.stat-row .bar { height: 5px; background: rgba(255,255,255,0.055); border-radius: 99px; overflow: hidden; }
.stat-row .bar i {
  display: block; height: 100%; border-radius: 99px;
  background: linear-gradient(90deg, rgba(255,181,69,0.45), var(--amber));
  transition: width 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.stat-row .val { font-family: var(--mono); font-size: 10px; text-align: right; color: var(--cream); }
.stat-row:nth-child(2) .bar i, .stat-row:nth-child(6) .bar i { background: linear-gradient(90deg, rgba(92,225,198,0.4), var(--teal)); }
.stat-row:nth-child(3) .bar i { background: linear-gradient(90deg, rgba(255,93,93,0.4), #ff6b5b); }
.stat-row:nth-child(7) .bar i { background: linear-gradient(90deg, rgba(255,158,210,0.35), var(--pink)); }

.load-hint {
  margin-top: auto;
  border: 1px dashed var(--line);
  border-radius: 12px;
  padding: 11px 12px;
  display: flex;
  gap: 10px;
  margin-top: 18px;
  background: rgba(255,255,255,0.014);
}
.load-hint .load-icon { color: var(--amber); font-size: 14px; line-height: 1.2; }
.load-hint p { color: var(--muted); font-size: 11px; line-height: 1.45; }
.load-hint.warn { border-color: rgba(255, 93, 93, 0.45); background: rgba(255, 93, 93, 0.06); }
.load-hint.warn .load-icon, .load-hint.warn p { color: #ffb0a0; }

/* stage */
.stage-panel {
  position: relative;
  border-radius: 24px;
  overflow: hidden;
  border: 1px solid var(--line);
  background:
    radial-gradient(ellipse 65% 52% at 50% 38%, rgba(255, 181, 69, 0.11), transparent 65%),
    radial-gradient(ellipse 90% 80% at 50% 110%, rgba(28, 34, 42, 0.9), transparent 70%),
    linear-gradient(160deg, #15171a 0%, #0b0e12 60%, #080a0e 100%);
  box-shadow: inset 0 0 120px rgba(0,0,0,0.6), var(--shadow);
  min-height: 0;
}
.stage-panel::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.022) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.022) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse at 50% 40%, black 5%, transparent 70%);
  pointer-events: none;
}
.stage-panel::after {
  content: '';
  position: absolute;
  left: 50%; bottom: 19%;
  width: 60%; height: 14%;
  transform: translateX(-50%);
  border: 1px solid rgba(255, 181, 69, 0.11);
  border-radius: 50%;
  box-shadow: 0 0 80px rgba(255, 181, 69, 0.05) inset;
  pointer-events: none;
}
#previewCanvas { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 1; touch-action: none; }
.stage-grain {
  position: absolute; inset: 0; z-index: 2; pointer-events: none; opacity: 0.35; mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.14'/%3E%3C/svg%3E");
}
.stage-top {
  position: absolute; top: 16px; left: 18px; right: 18px; z-index: 3;
  display: flex; justify-content: space-between; pointer-events: none;
}
.chip {
  font-family: var(--mono); font-size: 8.5px; font-weight: 700;
  letter-spacing: 0.14em;
  border: 1px solid var(--line);
  background: rgba(8, 11, 16, 0.55);
  backdrop-filter: blur(8px);
  border-radius: 99px;
  padding: 5px 9px;
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--muted);
}
.chip.live i { width: 5px; height: 5px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 7px var(--lime); }
.chip.mood { color: var(--amber); border-color: rgba(255,181,69,0.28); background: rgba(255,181,69,0.07); }
.stage-rail {
  position: absolute; right: 13px; top: 50%; z-index: 3;
  transform: translateY(-50%) rotate(90deg);
  transform-origin: center;
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.28em;
  color: rgba(247, 242, 232, 0.22);
  display: flex; gap: 22px; pointer-events: none;
}
.stage-bottom {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 4;
  padding: 60px 24px 22px;
  display: flex; align-items: flex-end; justify-content: space-between; gap: 18px;
  background: linear-gradient(transparent, rgba(8, 10, 14, 0.72) 48%, rgba(8, 10, 14, 0.94));
  pointer-events: none;
}
.stage-bottom > * { pointer-events: auto; }
.stage-name-block { min-width: 0; }
.stage-kicker { font-family: var(--mono); font-size: 8px; letter-spacing: 0.24em; color: var(--muted); display: block; margin-bottom: 3px; }
.stage-name-block h1 {
  font-family: var(--display);
  font-size: clamp(42px, 5.4vw, 78px);
  font-weight: 800;
  line-height: 0.9;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  text-shadow: 0 6px 34px rgba(0,0,0,0.6);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.stage-sub { display: block; margin-top: 7px; font-family: var(--mono); font-size: 9px; letter-spacing: 0.16em; color: var(--amber); }
.stage-tip {
  position: absolute; left: 24px; bottom: 6px; z-index: 4;
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.14em; color: rgba(247, 242, 232, 0.28);
  pointer-events: none;
}
.stage-badge {
  position: absolute; right: 18px; top: 54px; z-index: 3;
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.1em; color: var(--muted);
  border: 1px solid var(--line); border-radius: 99px; padding: 4px 8px;
  background: rgba(8, 11, 16, 0.4);
  pointer-events: none;
}

/* buttons */
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border-radius: 12px;
  padding: 0 20px;
  height: 44px;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.13em;
  transition: transform 0.16s, box-shadow 0.2s, background 0.2s, border-color 0.2s;
  white-space: nowrap;
  border: 1px solid transparent;
}
.btn:active { transform: translateY(1px) scale(0.995); }
.btn.primary {
  color: #17120a;
  background: linear-gradient(135deg, #ffd071, var(--amber) 55%, #ff9c3c);
  box-shadow: 0 8px 30px rgba(255, 166, 55, 0.24), inset 0 1px 0 rgba(255,255,255,0.5);
}
.btn.primary:hover { transform: translateY(-2px); box-shadow: 0 12px 36px rgba(255, 166, 55, 0.34), inset 0 1px 0 rgba(255,255,255,0.5); }
.btn.primary:disabled { opacity: 0.4; transform: none; cursor: not-allowed; }
.btn.ghost { border-color: var(--line-strong); color: var(--cream); background: rgba(255,255,255,0.02); }
.btn.ghost:hover { background: rgba(255,255,255,0.055); border-color: rgba(255,255,255,0.26); }
.btn.danger { border-color: rgba(255,93,93,0.4); color: #ffb0a0; background: rgba(255,93,93,0.07); }
.btn.big { height: 56px; padding: 0 24px; border-radius: 14px; font-size: 10.5px; }
.btn.big i { font-style: normal; font-size: 18px; transition: transform 0.2s; }
.btn.big:hover i { transform: translateX(4px); }
.btn.wide { width: 100%; }
.mini-btn {
  font-family: var(--mono); font-size: 8.5px; font-weight: 700; letter-spacing: 0.1em;
  color: var(--muted); padding: 6px 9px; border: 1px solid var(--line); border-radius: 8px;
  transition: 0.18s;
}
.mini-btn:hover { color: var(--cream); border-color: var(--line-strong); background: rgba(255,255,255,0.04); }

/* build panel */
.build-panel { display: flex; flex-direction: column; overflow: hidden; }
.tabs {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  padding: 8px 8px 0;
  gap: 2px;
  border-bottom: 1px solid var(--line);
}
.tabs button {
  position: relative;
  height: 41px;
  border-radius: 8px 8px 0 0;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--muted-2);
  transition: 0.18s;
}
.tabs button:hover { color: var(--cream); background: rgba(255,255,255,0.025); }
.tabs button.active { color: var(--amber); }
.tabs button.active::after {
  content: ''; position: absolute; left: 20%; right: 20%; bottom: -1px; height: 2px;
  background: var(--amber); border-radius: 2px;
  box-shadow: 0 0 12px rgba(255,181,69,0.6);
}
.tab-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.13) transparent;
}
.tab-scroll::-webkit-scrollbar, .stats-panel::-webkit-scrollbar { width: 5px; }
.tab-scroll::-webkit-scrollbar-thumb, .stats-panel::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.13); border-radius: 9px; }
.build-footer {
  flex: 0 0 auto;
  height: 42px;
  border-top: 1px solid var(--line);
  padding: 0 14px;
  display: flex; align-items: center; justify-content: space-between;
}
.build-footer span { font-family: var(--mono); font-size: 8px; letter-spacing: 0.1em; color: var(--muted-2); }
.section { margin-bottom: 21px; }
.section:last-child { margin-bottom: 4px; }
.section-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 9px; }
.section-head h3 { font-family: var(--mono); font-size: 9px; font-weight: 700; letter-spacing: 0.15em; color: var(--muted); }
.section-head span { font-family: var(--mono); font-size: 9px; color: var(--amber); }
.section-desc { font-size: 11px; color: var(--muted); margin: -4px 0 10px; line-height: 1.4; }

/* sliders */
.slider-row { margin-bottom: 13px; }
.slider-row:last-child { margin-bottom: 0; }
.slider-top { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 4px; }
.slider-top label { font-size: 11px; color: var(--muted); }
.slider-top output { font-family: var(--mono); font-size: 10px; color: var(--cream); }
.slider-hint { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.07em; color: var(--muted-2); margin-top: 3px; display: flex; justify-content: space-between; }
input[type='range'] {
  -webkit-appearance: none; appearance: none;
  width: 100%; height: 18px; background: transparent; margin: 0; cursor: pointer;
}
input[type='range']::-webkit-slider-runnable-track {
  height: 4px; border-radius: 99px;
  background: linear-gradient(90deg, var(--amber) var(--fill, 50%), rgba(255,255,255,0.09) var(--fill, 50%));
}
input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 13px; height: 13px; margin-top: -4.5px;
  border-radius: 50%;
  background: var(--cream);
  border: 2px solid #1c2129;
  box-shadow: 0 0 0 1px rgba(255,255,255,0.25), 0 2px 8px rgba(0,0,0,0.4);
  transition: transform 0.15s;
}
input[type='range']:hover::-webkit-slider-thumb { transform: scale(1.18); }
input[type='range']::-moz-range-track { height: 4px; border-radius: 99px; background: rgba(255,255,255,0.09); }
input[type='range']::-moz-range-progress { height: 4px; border-radius: 99px; background: var(--amber); }
input[type='range']::-moz-range-thumb { width: 11px; height: 11px; border-radius: 50%; background: var(--cream); border: 2px solid #1c2129; }

/* option grids */
.option-grid { display: grid; gap: 6px; }
.option-grid.two { grid-template-columns: 1fr 1fr; }
.option-grid.four { grid-template-columns: repeat(4, 1fr); }
.option-card {
  position: relative;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.018);
  border-radius: 10px;
  padding: 9px 8px;
  text-align: left;
  transition: 0.17s;
  overflow: hidden;
}
.option-card:hover { border-color: var(--line-strong); background: rgba(255,255,255,0.04); }
.option-card.active { border-color: var(--amber); background: rgba(255,181,69,0.075); box-shadow: inset 0 0 0 1px rgba(255,181,69,0.15); }
.option-card .oc-icon { font-size: 15px; line-height: 1; display: block; margin-bottom: 5px; }
.option-card .oc-name { display: block; font-size: 10.5px; font-weight: 600; }
.option-card .oc-sub { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: 0.05em; color: var(--muted-2); margin-top: 2px; }
.option-card.active .oc-sub { color: rgba(255,181,69,0.72); }
.option-card .oc-cost { position: absolute; top: 6px; right: 6px; font-family: var(--mono); font-size: 7px; color: var(--muted-2); }
.mat-card { padding: 10px 8px; }
.mat-card .swatch { width: 18px; height: 18px; border-radius: 50%; margin-bottom: 6px; box-shadow: inset 2px 2px 4px rgba(255,255,255,0.32), inset -3px -3px 5px rgba(0,0,0,0.4); }
.mat-card .desc { font-size: 9px; color: var(--muted); line-height: 1.35; margin-top: 3px; min-height: 24px; }

.chip-row { display: flex; flex-wrap: wrap; gap: 5px; }
.chip-opt {
  font-family: var(--mono); font-size: 8.5px; font-weight: 600; letter-spacing: 0.05em;
  color: var(--muted); border: 1px solid var(--line); border-radius: 7px;
  padding: 6px 9px; transition: 0.16s;
}
.chip-opt:hover { color: var(--cream); border-color: var(--line-strong); }
.chip-opt.active { color: #14100a; background: var(--amber); border-color: var(--amber); font-weight: 700; }

/* swatches */
.swatch-grid { display: grid; grid-template-columns: repeat(8, 1fr); gap: 5px; }
.swatch-btn {
  aspect-ratio: 1; border-radius: 50%;
  border: 2px solid transparent;
  box-shadow: inset 2px 2px 4px rgba(255,255,255,0.28), inset -3px -3px 5px rgba(0,0,0,0.32), 0 0 0 1px rgba(0,0,0,0.2);
  transition: transform 0.15s;
  position: relative;
}
.swatch-btn:hover { transform: scale(1.14); }
.swatch-btn.active { border-color: var(--cream); transform: scale(1.12); box-shadow: 0 0 0 2px rgba(255,255,255,0.2), 0 0 16px rgba(255,255,255,0.15); }
.swatch-btn.custom { display: grid; place-items: center; overflow: hidden; color: var(--muted); font-size: 10px; }
.swatch-btn.custom input { position: absolute; inset: -10px; opacity: 0; cursor: pointer; width: 200%; height: 200%; }

/* patterns */
.pattern-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.pattern-btn {
  border: 1px solid var(--line); border-radius: 9px; overflow: hidden;
  background: #1a2028; padding: 0; transition: 0.16s;
}
.pattern-btn:hover { border-color: var(--line-strong); }
.pattern-btn.active { border-color: var(--amber); box-shadow: 0 0 0 1px rgba(255,181,69,0.25); }
.pattern-btn .p-preview {
  aspect-ratio: 1.15; display: block; width: 100%;
  background-color: var(--p-color, #ffb545);
  position: relative; overflow: hidden;
}
.pattern-btn .p-preview::after { content: ''; position: absolute; inset: 0; opacity: 0.85; }
.pattern-btn[data-p='split'] .p-preview::after { background: linear-gradient(transparent 46%, var(--p-accent, #ff6b3d) 46%); }
.pattern-btn[data-p='dots'] .p-preview::after { background-image: radial-gradient(circle, var(--p-accent, #ff6b3d) 22%, transparent 24%); background-size: 9px 9px; }
.pattern-btn[data-p='stripes'] .p-preview::after { background: repeating-linear-gradient(45deg, transparent 0 4px, var(--p-accent, #ff6b3d) 4px 7px); }
.pattern-btn[data-p='swirl'] .p-preview::after { background: repeating-radial-gradient(circle at 30% 40%, transparent 0 3px, var(--p-accent, #ff6b3d) 3px 5px); }
.pattern-btn[data-p='checker'] .p-preview::after { background-image: linear-gradient(45deg, var(--p-accent, #ff6b3d) 25%, transparent 25% 75%, var(--p-accent, #ff6b3d) 75%), linear-gradient(45deg, var(--p-accent, #ff6b3d) 25%, transparent 25% 75%, var(--p-accent, #ff6b3d) 75%); background-size: 10px 10px; background-position: 0 0, 5px 5px; }
.pattern-btn[data-p='stars'] .p-preview::after { background-image: radial-gradient(circle, var(--p-accent, #ff6b3d) 15%, transparent 17%); background-size: 13px 13px; }
.pattern-btn[data-p='hazard'] .p-preview::after { background: repeating-linear-gradient(45deg, var(--p-accent, #ff6b3d) 0 4px, #1a2028 4px 9px); }
.pattern-btn .p-label { display: block; padding: 4px 3px 5px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.04em; color: var(--muted); }
.pattern-btn.active .p-label { color: var(--amber); }

/* soul */
.mood-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 5px; }
.mood-btn {
  border: 1px solid var(--line); border-radius: 10px; padding: 8px 4px 7px; text-align: center;
  transition: 0.17s;
}
.mood-btn:hover { border-color: var(--line-strong); background: rgba(255,255,255,0.03); }
.mood-btn.active { border-color: var(--mo-color, var(--amber)); background: color-mix(in srgb, var(--mo-color, var(--amber)) 10%, transparent); }
.mood-btn .mo-icon { display: block; font-size: 16px; line-height: 1; color: var(--mo-color, var(--amber)); }
.mood-btn .mo-name { display: block; font-family: var(--mono); font-size: 7.5px; font-weight: 700; margin-top: 5px; }
.voice-list { display: flex; flex-direction: column; gap: 5px; }
.voice-row {
  display: flex; align-items: center; gap: 9px;
  border: 1px solid var(--line); border-radius: 9px; padding: 7px 9px;
  transition: 0.16s; text-align: left;
}
.voice-row:hover { border-color: var(--line-strong); background: rgba(255,255,255,0.03); }
.voice-row.active { border-color: var(--teal); background: rgba(92,225,198,0.06); }
.voice-row .vr-icon { width: 22px; height: 22px; border-radius: 50%; background: rgba(255,255,255,0.05); display: grid; place-items: center; font-size: 9px; color: var(--teal); }
.voice-row .vr-name { font-size: 11px; }
.voice-row .vr-desc { font-family: var(--mono); font-size: 7.5px; color: var(--muted-2); margin-left: auto; }
.voice-row .eq { display: flex; gap: 2px; align-items: flex-end; height: 12px; margin-left: 4px; }
.voice-row .eq i { width: 2px; background: var(--teal); border-radius: 2px; animation: eq 1s infinite ease-in-out; }
@keyframes eq { 0%, 100% { height: 3px; } 50% { height: 11px; } }

/* parts */
.pack-filter { display: flex; gap: 4px; flex-wrap: wrap; margin-bottom: 10px; }
.pack-filter button {
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.06em; color: var(--muted);
  border: 1px solid var(--line); border-radius: 99px; padding: 5px 8px; transition: 0.16s;
}
.pack-filter button:hover { color: var(--cream); }
.pack-filter button.active { color: #14100a; background: var(--cream); border-color: var(--cream); }
.gadget-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.gadget-card {
  position: relative; border: 1px solid var(--line); border-radius: 11px;
  background: rgba(255, 255, 255, 0.018);
  padding: 8px 8px 7px; text-align: left; transition: 0.17s; overflow: hidden;
}
.gadget-card:hover { border-color: var(--line-strong); background: rgba(255,255,255,0.04); transform: translateY(-1px); }
.gadget-card.equipped { border-color: var(--gb-color, var(--amber)); background: color-mix(in srgb, var(--gb-color, var(--amber)) 8%, transparent); }
.gadget-card.locked { opacity: 0.65; }
.gadget-card .gc-head { display: flex; align-items: center; gap: 6px; }
.gadget-card .gc-icon {
  flex: 0 0 24px; width: 24px; height: 24px; border-radius: 50%;
  display: grid; place-items: center; font-size: 11px;
  background: radial-gradient(circle at 35% 30%, color-mix(in srgb, var(--gb-color, #b9c6d6) 65%, white), color-mix(in srgb, var(--gb-color, #b9c6d6) 35%, black));
  color: #11161d;
  box-shadow: 0 0 10px color-mix(in srgb, var(--gb-color, #b9c6d6) 28%, transparent);
}
.gadget-card .gc-name { font-size: 9.5px; font-weight: 600; line-height: 1.15; }
.gadget-card .gc-pack { font-family: var(--mono); font-size: 6.5px; color: var(--muted-2); letter-spacing: 0.08em; margin-top: 1px; }
.gadget-card .gc-cost { display: flex; gap: 6px; margin-top: 6px; font-family: var(--mono); font-size: 7.5px; color: var(--muted); }
.gadget-card .gc-cost b { color: var(--amber); font-weight: 500; }
.gadget-card .gc-cost b.en { color: var(--teal); }
.gadget-card .gc-blurb { font-size: 8px; color: var(--muted-2); line-height: 1.3; margin-top: 4px; display: none; }
.gadget-card:hover .gc-blurb { display: block; }
.gadget-card .gc-check {
  position: absolute; top: 6px; right: 6px;
  width: 13px; height: 13px; border-radius: 50%;
  background: var(--gb-color, var(--amber)); color: #11161d;
  font-size: 8px; display: grid; place-items: center; font-weight: 700;
}
.gadget-card .gc-lock {
  position: absolute; top: 5px; right: 5px; font-family: var(--mono); font-size: 7px; color: var(--violet);
  display: flex; align-items: center; gap: 2px;
}
.gadget-card .gc-unlock {
  margin-top: 5px; width: 100%; font-family: var(--mono); font-size: 7.5px; font-weight: 700;
  padding: 4px 0; border-radius: 5px; border: 1px solid rgba(192,132,252,0.35);
  color: var(--violet); background: rgba(192,132,252,0.06);
}
.gadget-card .gc-unlock:hover { background: rgba(192,132,252,0.16); }
.gadget-card .gc-unlock:disabled { opacity: 0.4; cursor: not-allowed; }
.locked-note { font-family: var(--mono); font-size: 7px; color: var(--violet); margin-top: 4px; letter-spacing: 0.04em; }

.loadout-list { display: flex; flex-direction: column; gap: 4px; margin-bottom: 12px; }
.loadout-row {
  display: flex; align-items: center; gap: 7px;
  border: 1px solid var(--line); border-radius: 8px; padding: 5px 7px;
  background: rgba(255,255,255,0.02);
}
.loadout-row .lo-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--lr-color, var(--amber)); flex: 0 0 auto; }
.loadout-row .lo-name { font-size: 9px; flex: 1; }
.loadout-row .lo-cost { font-family: var(--mono); font-size: 7px; color: var(--muted-2); }
.loadout-row .lo-remove { color: var(--muted-2); font-size: 10px; padding: 2px 3px; }
.loadout-row .lo-remove:hover { color: var(--red); }
.toggle-row {
  display: flex; align-items: center; justify-content: space-between;
  border: 1px solid var(--line); border-radius: 9px; padding: 8px 10px; margin-bottom: 8px;
  width: 100%; transition: 0.16s; text-align: left;
}
.toggle-row:hover { background: rgba(255,255,255,0.03); }
.toggle-row.active { border-color: rgba(255,181,69,0.4); background: rgba(255,181,69,0.055); }
.toggle-row .tr-label { font-size: 10px; }
.toggle-row .tr-sub { font-family: var(--mono); font-size: 7px; color: var(--muted-2); margin-top: 1px; }
.toggle-switch { width: 28px; height: 15px; border-radius: 99px; background: rgba(255,255,255,0.1); position: relative; transition: 0.18s; flex: 0 0 auto; }
.toggle-switch i { position: absolute; top: 2px; left: 2px; width: 11px; height: 11px; border-radius: 50%; background: var(--muted); transition: 0.18s; }
.toggle-row.active .toggle-switch { background: rgba(255,181,69,0.4); }
.toggle-row.active .toggle-switch i { left: 15px; background: var(--amber); }

/* forge */
.forge-head {
  display: flex; gap: 8px; margin-bottom: 14px;
}
.forge-wallet {
  flex: 1; border: 1px solid var(--line); border-radius: 10px; padding: 8px 10px;
  background: rgba(255,255,255,0.02);
}
.forge-wallet span { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; color: var(--muted-2); }
.forge-wallet b { display: block; font-family: var(--mono); font-size: 16px; margin-top: 2px; color: var(--amber); }
.forge-wallet.core b { color: var(--violet); }
.forge-list { display: flex; flex-direction: column; gap: 6px; }
.forge-row {
  border: 1px solid var(--line); border-radius: 11px; padding: 9px 10px;
  background: rgba(255,255,255,0.018);
}
.forge-row .fr-top { display: flex; align-items: center; gap: 8px; }
.forge-row .fr-icon { width: 24px; height: 24px; border-radius: 7px; display: grid; place-items: center; background: rgba(255,255,255,0.05); color: var(--fr-color, var(--amber)); font-size: 12px; }
.forge-row .fr-name { font-size: 10.5px; font-weight: 600; flex: 1; }
.forge-row .fr-level { font-family: var(--mono); font-size: 8px; color: var(--muted); }
.forge-row .fr-desc { font-size: 8.5px; color: var(--muted-2); margin: 4px 0 6px; }
.forge-row .fr-bottom { display: flex; align-items: center; gap: 8px; }
.pips { display: flex; gap: 3px; flex: 1; }
.pips i { width: 100%; max-width: 22px; height: 3px; border-radius: 2px; background: rgba(255,255,255,0.09); }
.pips i.on { background: var(--fr-color, var(--amber)); box-shadow: 0 0 6px color-mix(in srgb, var(--fr-color, var(--amber)) 50%, transparent); }
.forge-buy {
  font-family: var(--mono); font-size: 8px; font-weight: 700; padding: 5px 9px;
  border-radius: 6px; border: 1px solid var(--line-strong); color: var(--cream); transition: 0.16s;
}
.forge-buy:hover { background: var(--cream); color: #11161d; }
.forge-buy:disabled { opacity: 0.32; cursor: not-allowed; }
.forge-buy:disabled:hover { background: none; color: var(--cream); }
.forge-note { font-size: 9px; color: var(--muted-2); line-height: 1.5; margin-top: 12px; border-top: 1px dashed var(--line); padding-top: 10px; }

/* ── arenas select ─────────────────────────────────────────── */
#arenasScreen { overflow-y: auto; }
.arenas-wrap { max-width: 1180px; margin: 0 auto; padding: 34px 28px 48px; }
.arenas-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 30px; margin-bottom: 26px; }
.arenas-title h1 {
  font-family: var(--display); font-size: clamp(38px, 5.2vw, 66px); line-height: 0.92;
  font-weight: 800; letter-spacing: -0.02em; margin: 9px 0 12px;
}
.arenas-title h1 em { font-style: normal; color: var(--amber); }
.arenas-title p { color: var(--muted); max-width: 520px; font-size: 13px; }
.build-mini {
  flex: 0 0 auto; display: flex; align-items: center; gap: 12px;
  border: 1px solid var(--line); border-radius: 14px; padding: 10px 14px 10px 10px;
  background: rgba(255,255,255,0.02);
}
.build-mini canvas { width: 54px; height: 54px; }
.build-mini .bm-name { font-family: var(--display); font-size: 20px; font-weight: 800; line-height: 1; }
.build-mini .bm-sub { font-family: var(--mono); font-size: 8px; color: var(--muted); margin-top: 4px; letter-spacing: 0.08em; }

.arena-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.arena-card {
  position: relative; overflow: hidden;
  border: 1px solid var(--line); border-radius: 20px;
  background: linear-gradient(155deg, #151b23, #0b0f15 70%);
  min-height: 236px; padding: 20px;
  text-align: left; transition: 0.22s cubic-bezier(0.22,1,0.36,1);
  display: flex; flex-direction: column;
}
.arena-card::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(circle at 82% 18%, var(--ac, rgba(255,181,69,0.18)), transparent 55%);
  opacity: 0.8; transition: opacity 0.25s;
}
.arena-card::after {
  content: ''; position: absolute; inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.018) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.018) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: radial-gradient(circle at 80% 20%, black, transparent 60%);
  pointer-events: none;
}
.arena-card:hover { transform: translateY(-4px); border-color: rgba(255,255,255,0.2); box-shadow: 0 24px 60px rgba(0,0,0,0.4); }
.arena-card:hover::before { opacity: 1; }
.arena-art {
  position: absolute; right: -6px; top: -4px; width: 190px; height: 190px;
  opacity: 0.9; pointer-events: none; z-index: 1;
}
.arena-art svg { width: 100%; height: 100%; }
.arena-card .ac-copy { position: relative; z-index: 2; max-width: 67%; }
.arena-card .ac-num { font-family: var(--mono); font-size: 8px; letter-spacing: 0.18em; color: var(--muted); }
.arena-card .ac-title { font-family: var(--display); font-size: 28px; font-weight: 800; line-height: 0.98; margin: 7px 0 7px; }
.arena-card .ac-desc { font-size: 11px; color: var(--muted); line-height: 1.45; }
.arena-card .ac-foot { position: relative; z-index: 2; margin-top: auto; display: flex; align-items: center; justify-content: space-between; padding-top: 16px; }
.arena-card .ac-meta { display: flex; gap: 7px; flex-wrap: wrap; }
.arena-card .ac-pill {
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.06em; color: var(--muted);
  border: 1px solid var(--line); border-radius: 99px; padding: 3px 7px;
}
.arena-card .ac-pill.reward { color: var(--amber); border-color: rgba(255,181,69,0.25); }
.arena-card .ac-go {
  width: 38px; height: 38px; border-radius: 50%;
  background: var(--cream); color: #11161d;
  display: grid; place-items: center; font-size: 17px;
  transition: 0.22s;
}
.arena-card:hover .ac-go { transform: rotate(-45deg) scale(1.08); background: var(--amber); }
.arena-card .ac-diff { position: absolute; right: 18px; bottom: 74px; z-index: 2; display: flex; gap: 3px; }
.arena-card .ac-diff i { width: 14px; height: 3px; border-radius: 2px; background: rgba(255,255,255,0.12); }
.arena-card .ac-diff i.on { background: var(--amber); }
.arena-foot {
  display: flex; justify-content: space-between; gap: 20px; align-items: center;
  margin-top: 22px; padding-top: 16px; border-top: 1px solid var(--line);
  font-size: 10.5px; color: var(--muted-2);
}
.arena-foot b { color: var(--muted); font-weight: 500; }

/* ── play screen ──────────────────────────────────────────── */
.play-screen { position: fixed; inset: 0; z-index: 60; height: 100dvh; overflow: hidden; background: #070a0e; }
.app-shell.playing .play-screen { display: block; }
#gameCanvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.arena-vignette {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse 78% 70% at 50% 50%, transparent 55%, rgba(0,0,0,0.62) 100%);
}
.game-top {
  position: absolute; top: max(14px, env(safe-area-inset-top)); left: 18px; right: 18px;
  display: flex; align-items: flex-start; justify-content: space-between; z-index: 5; pointer-events: none;
}
.hud-objective {
  display: flex; flex-direction: column; gap: 3px;
  background: rgba(8,11,16,0.55); border: 1px solid var(--line); border-radius: 12px;
  padding: 8px 12px; backdrop-filter: blur(12px);
}
.hud-mode { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.18em; color: var(--amber); }
.hud-objective b { font-size: 12px; letter-spacing: 0.01em; color: var(--cream); font-weight: 600; }
.hud-center { text-align: center; background: rgba(8,11,16,0.5); border: 1px solid var(--line); border-radius: 12px; padding: 5px 18px 6px; backdrop-filter: blur(12px); }
.hud-center div { font-family: var(--mono); font-size: 22px; font-weight: 700; line-height: 1.05; }
.hud-center small { font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.14em; color: var(--muted); }
.hud-right { pointer-events: auto; display: flex; gap: 8px; }
.hud-sub {
  position: absolute; top: calc(max(14px, env(safe-area-inset-top)) + 62px); left: 50%; transform: translateX(-50%);
  z-index: 5; font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.12em; color: var(--muted);
  background: rgba(8,11,16,0.45); border: 1px solid var(--line); border-radius: 99px; padding: 4px 12px;
  backdrop-filter: blur(10px); white-space: nowrap;
}
.boss-bar-wrap {
  position: absolute; top: calc(max(14px, env(safe-area-inset-top)) + 64px); left: 50%; transform: translateX(-50%);
  width: min(460px, 70vw); z-index: 5;
}
.boss-bar-label { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.13em; color: #ff9b8e; margin-bottom: 4px; }
.boss-bar { height: 8px; border-radius: 99px; background: rgba(0,0,0,0.55); border: 1px solid rgba(255,93,93,0.28); overflow: hidden; }
.boss-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #ff8a4c, #ff5d5d); box-shadow: 0 0 14px rgba(255,93,93,0.55); transition: width 0.25s; }
.hud-notice {
  position: absolute; top: 27%; left: 50%; transform: translate(-50%, -50%);
  z-index: 7; font-family: var(--display); font-size: clamp(28px, 5vw, 56px); font-weight: 800;
  letter-spacing: 0.02em; text-align: center; pointer-events: none;
  text-shadow: 0 8px 40px rgba(0,0,0,0.7);
  opacity: 0; transition: opacity 0.2s, transform 0.3s cubic-bezier(0.22,1,0.36,1);
  white-space: nowrap;
}
.hud-notice.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.hud-notice.pop { animation: noticePop 0.45s cubic-bezier(0.22,1,0.36,1); }
@keyframes noticePop { from { transform: translate(-50%, -50%) scale(0.7); opacity: 0; } to { transform: translate(-50%, -50%) scale(1); opacity: 1; } }

.hud-bottom {
  position: absolute; bottom: max(16px, env(safe-area-inset-bottom)); left: 18px; right: 18px;
  display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; z-index: 5; pointer-events: none;
}
.pilot-card {
  display: flex; align-items: center; gap: 10px;
  background: rgba(8,11,16,0.58); border: 1px solid var(--line); border-radius: 14px;
  padding: 8px 12px 8px 8px; backdrop-filter: blur(12px); min-width: 200px;
}
.pilot-portrait { width: 46px; height: 46px; flex: 0 0 46px; }
.pilot-info { flex: 1; min-width: 110px; }
.pilot-name-row { display: flex; align-items: baseline; gap: 7px; }
.pilot-name-row b { font-family: var(--display); font-size: 16px; font-weight: 800; line-height: 1; }
.pilot-name-row span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; color: var(--amber); }
.pilot-hp { height: 4px; background: rgba(255,255,255,0.09); border-radius: 99px; overflow: hidden; margin: 6px 0 3px; }
.pilot-hp i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, var(--teal), #a7f3e0); border-radius: 99px; transition: width 0.2s; }
.pilot-info small { font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.08em; color: var(--muted-2); }
.ability-row { display: flex; align-items: flex-end; gap: 16px; pointer-events: auto; }
.ability { display: flex; flex-direction: column; align-items: center; gap: 3px; }
.ability-ring { position: relative; width: 46px; height: 46px; display: grid; place-items: center; }
.ability-ring svg { position: absolute; inset: 0; width: 46px; height: 46px; transform: rotate(-90deg); }
.ability-ring circle { fill: none; stroke-width: 3; }
.ability-ring .track { stroke: rgba(255,255,255,0.1); }
.ability-ring .fill { stroke: var(--amber); stroke-linecap: round; stroke-dasharray: 113; stroke-dashoffset: 0; transition: stroke-dashoffset 0.1s linear; }
.ability.core .ability-ring .fill { stroke: var(--violet); }
.ability-ring b { font-size: 17px; color: var(--cream); font-weight: 400; }
.ability > span { font-family: var(--mono); font-size: 7px; font-weight: 700; letter-spacing: 0.12em; color: var(--muted); }
.ability > small { font-family: var(--mono); font-size: 6px; letter-spacing: 0.08em; color: var(--muted-2); }
.ability.ready .ability-ring { filter: drop-shadow(0 0 9px rgba(255,181,69,0.45)); }
.ability.core.ready .ability-ring { filter: drop-shadow(0 0 9px rgba(192,132,252,0.5)); }
.hud-help { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.07em; color: rgba(247,242,232,0.3); text-align: right; align-self: center; }
.hud-help span { color: rgba(247,242,232,0.55); border: 1px solid rgba(255,255,255,0.14); border-radius: 3px; padding: 1px 4px; margin-left: 6px; }
.hud-help span:first-child { margin-left: 0; }

.mobile-controls { display: none; }
.countdown {
  position: absolute; inset: 0; z-index: 8; display: grid; place-items: center; pointer-events: none;
  background: rgba(5, 7, 10, 0.3);
}
.countdown span {
  font-family: var(--display); font-size: clamp(80px, 18vw, 180px); font-weight: 800;
  color: var(--cream); text-shadow: 0 10px 60px rgba(0,0,0,0.6);
  animation: countPop 0.9s cubic-bezier(0.22,1,0.36,1);
}
@keyframes countPop { 0% { transform: scale(1.6); opacity: 0; } 25% { opacity: 1; } 100% { transform: scale(0.9); opacity: 0.28; } }

/* overlays & modals */
.overlay {
  position: fixed; inset: 0; z-index: 100;
  display: flex; align-items: center; justify-content: center;
  padding: 20px;
  background: rgba(4, 6, 9, 0.68);
  backdrop-filter: blur(14px);
  animation: overlayIn 0.25s ease both;
  overflow-y: auto;
}
@keyframes overlayIn { from { opacity: 0; } to { opacity: 1; } }
.modal {
  width: min(560px, 100%);
  border: 1px solid var(--line-strong);
  border-radius: 24px;
  background:
    radial-gradient(ellipse at 50% -10%, rgba(255,181,69,0.12), transparent 50%),
    linear-gradient(160deg, #171d26, #0b0f15 80%);
  box-shadow: var(--shadow);
  padding: 30px;
  position: relative;
  animation: modalIn 0.32s cubic-bezier(0.22,1,0.36,1) both;
  margin: auto;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(16px) scale(0.97); } to { opacity: 1; transform: none; } }
.modal.small { width: min(400px, 100%); }
.modal h2 {
  font-family: var(--display); font-size: clamp(28px, 4vw, 42px); font-weight: 800; line-height: 0.98;
  margin: 7px 0 10px; letter-spacing: -0.01em;
}
.modal .modal-actions { display: flex; gap: 9px; margin-top: 24px; flex-wrap: wrap; }
.modal .modal-actions .btn { flex: 1; }
.modal-close { position: absolute; right: 16px; top: 14px; color: var(--muted); font-size: 13px; padding: 7px; }
.modal-close:hover { color: var(--cream); }

.help-modal { width: min(880px, 100%); padding: 32px; }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; margin-top: 20px; }
.help-col h3 {
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.14em; color: var(--amber);
  display: flex; align-items: center; gap: 7px; margin: 18px 0 5px;
}
.help-col h3:first-child { margin-top: 0; }
.help-col h3 span { font-size: 7px; color: var(--muted-2); border: 1px solid var(--line); border-radius: 3px; padding: 1px 3px; }
.help-col p { font-size: 11.5px; color: var(--muted); line-height: 1.55; }
.help-col b { color: var(--cream); font-weight: 600; }
.key-list { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; margin-bottom: 8px; }
.key-list div { display: flex; align-items: center; gap: 7px; font-size: 9.5px; color: var(--muted); }
kbd {
  font-family: var(--mono); font-size: 7px; letter-spacing: 0.05em; color: var(--cream);
  border: 1px solid var(--line-strong); border-bottom-width: 2px; border-radius: 4px;
  padding: 3px 5px; background: rgba(255,255,255,0.04);
}
.help-list { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 5px; }
.help-list li { font-size: 10.5px; color: var(--muted); padding-left: 12px; position: relative; }
.help-list li::before { content: '→'; position: absolute; left: 0; color: var(--amber); font-size: 9px; }
.help-foot { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 26px; padding-top: 18px; border-top: 1px solid var(--line); flex-wrap: wrap; }
.help-foot .mono { color: var(--muted-2); }

/* result modal */
.result-modal { width: min(680px, 100%); padding: 0; overflow: hidden; }
.result-banner {
  position: relative; padding: 28px 30px 20px;
  background: radial-gradient(ellipse at 30% 0%, rgba(255,181,69,0.18), transparent 60%), rgba(255,255,255,0.02);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
}
.result-banner.lose { background: radial-gradient(ellipse at 30% 0%, rgba(255,93,93,0.16), transparent 60%), rgba(255,255,255,0.02); }
.result-banner .eyebrow { color: var(--amber); }
.result-banner.lose .eyebrow { color: #ff8f86; }
.result-banner h2 { font-size: clamp(44px, 8vw, 72px); margin: 4px 0 6px; line-height: 0.85; }
.result-banner p { color: var(--muted); font-size: 12px; }
.result-banner .rb-ball { position: absolute; right: 12px; bottom: -24px; width: 190px; height: 190px; opacity: 0.95; }
.result-body { padding: 22px 30px 26px; }
.result-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 18px; }
.result-stat { border: 1px solid var(--line); border-radius: 10px; padding: 9px 10px; background: rgba(255,255,255,0.018); }
.result-stat span { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: 0.12em; color: var(--muted-2); }
.result-stat b { display: block; font-family: var(--mono); font-size: 14px; margin-top: 3px; }
.reward-row { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.reward-chip {
  display: flex; align-items: center; gap: 8px; border: 1px solid var(--line);
  border-radius: 10px; padding: 8px 11px; background: rgba(255,255,255,0.025);
  animation: rewardIn 0.45s cubic-bezier(0.22,1,0.36,1) both;
}
@keyframes rewardIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
.reward-chip i { font-style: normal; font-size: 13px; color: var(--amber); }
.reward-chip.core i { color: var(--violet); }
.reward-chip b { font-family: var(--mono); font-size: 13px; }
.reward-chip small { font-family: var(--mono); font-size: 7px; color: var(--muted-2); letter-spacing: 0.08em; }
.unlock-card {
  display: flex; gap: 12px; align-items: center;
  border: 1px solid rgba(192,132,252,0.35); background: rgba(192,132,252,0.07);
  border-radius: 13px; padding: 10px 12px; margin-bottom: 14px;
  animation: rewardIn 0.55s 0.15s cubic-bezier(0.22,1,0.36,1) both;
}
.unlock-card canvas { width: 44px; height: 44px; flex: 0 0 44px; }
.unlock-card .uc-copy { flex: 1; }
.unlock-card .uc-kicker { font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--violet); display: block; }
.unlock-card .uc-name { font-size: 13px; font-weight: 600; }
.unlock-card .uc-sub { font-size: 9px; color: var(--muted); }
.result-note { font-family: var(--mono); font-size: 8px; letter-spacing: 0.05em; color: var(--muted-2); margin-bottom: 16px; line-height: 1.6; }
.result-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.result-actions .btn { flex: 1; min-width: 120px; }
.result-actions .btn.primary { flex: 1.4; }

/* toasts */
.toasts {
  position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%);
  z-index: 200; display: flex; flex-direction: column; gap: 6px; align-items: center;
  pointer-events: none; width: min(440px, calc(100% - 32px));
}
.toast {
  background: rgba(20, 26, 34, 0.96); border: 1px solid var(--line-strong);
  border-radius: 10px; padding: 9px 14px; font-size: 11px; color: var(--cream);
  box-shadow: 0 16px 40px rgba(0,0,0,0.5); backdrop-filter: blur(12px);
  display: flex; align-items: center; gap: 8px;
  animation: toastIn 0.28s cubic-bezier(0.22,1,0.36,1) both;
  text-align: center;
}
.toast.bad { border-color: rgba(255,93,93,0.4); color: #ffb7ad; }
.toast.good { border-color: rgba(167,243,107,0.35); color: #d8ffbc; }
.toast.out { animation: toastOut 0.25s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(12px) scale(0.96); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(6px) scale(0.97); } }

/* ── responsive ───────────────────────────────────────────── */
@media (max-width: 1250px) {
  .workshop-grid { grid-template-columns: 262px minmax(0, 1fr) 348px; }
  .stage-name-block h1 { font-size: clamp(38px, 4.6vw, 62px); }
  .stats-panel { padding: 15px 14px; }
  .name-input { font-size: 29px; }
}
@media (max-width: 1080px) {
  body { overflow-y: auto; }
  .app-shell { height: auto; min-height: 100dvh; }
  main { flex: 1; }
  .workshop-grid { height: auto; grid-template-columns: minmax(0, 1fr) 360px; grid-template-areas: 'stage build' 'stats build'; align-items: start; }
  .stage-panel { grid-area: stage; height: 480px; min-height: 480px; }
  .stats-panel { grid-area: stats; overflow: visible; }
  .build-panel { grid-area: build; height: calc(100dvh - 95px); position: sticky; top: 13px; }
  .tab-scroll { max-height: none; }
  .screen { height: auto; }
  #workshopScreen { min-height: calc(100dvh - 66px); }
  .stats-panel { display: grid; grid-template-columns: 1fr 1fr; gap: 0 22px; align-content: start; }
  .stats-panel .panel-head, .stats-panel .name-line, .stats-panel .build-tags { grid-column: 1 / -1; }
  .stats-panel .budget-stack { grid-column: 1; }
