  .mainnav button span { display: none; }
  .wallet-chip { padding: 0 8px; height: 27px; }
  .workshop-grid { grid-template-columns: 1fr; grid-template-areas: 'stage' 'stats' 'build'; padding: 10px; gap: 10px; }
  .stage-panel { height: 400px; min-height: 400px; }
  .build-panel { position: static; height: auto; min-height: 560px; }
