  .stage-bottom { padding: 50px 16px 16px; flex-direction: column; align-items: stretch; gap: 12px; }
  .stage-name-block h1 { font-size: 54px; }
  .stage-bottom .btn.big { width: 100%; height: 48px; }
  .stage-tip { bottom: 6px; left: 16px; font-size: 6.5px; }
  .stage-rail { display: none; }
  .stage-badge { top: 48px; right: 12px; }
  .stats-panel { display: flex; }
  .stat-list { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 18px; }
  .load-hint { margin-top: 14px; }
  .arenas-head { flex-direction: column; align-items: flex-start; gap: 16px; }
  .build-mini { width: 100%; }
  .arena-grid { grid-template-columns: 1fr; }
  .arena-card { min-height: 210px; }
  .arena-card .ac-copy { max-width: 72%; }
  .arena-foot { flex-direction: column; align-items: flex-start; }
  .help-grid { grid-template-columns: 1fr; gap: 8px; }
  .help-col h3 { margin-top: 16px; }
  .help-modal { padding: 24px; }
  .hud-help { display: none; }
  .pilot-card { min-width: 0; padding: 6px 9px 6px 6px; }
  .pilot-portrait { width: 38px; height: 38px; flex-basis: 38px; }
  .pilot-name-row b { font-size: 14px; }
  .hud-bottom { left: 10px; right: 10px; bottom: max(10px, env(safe-area-inset-bottom)); }
  .game-top { left: 10px; right: 10px; }
  .hud-objective { padding: 6px 9px; }
