  .hud-sub { top: auto; bottom: 130px; }
  .boss-bar-wrap { top: calc(max(14px, env(safe-area-inset-top)) + 58px); width: 62vw; }
}
@media (hover: none), (max-width: 900px) {
  .mobile-controls {
    display: flex; align-items: flex-end; justify-content: space-between;
    position: absolute; left: 20px; right: 20px; bottom: max(92px, calc(env(safe-area-inset-bottom) + 80px));
    z-index: 6; pointer-events: none;
  }
  .joystick {
    width: 104px; height: 104px; border-radius: 50%; pointer-events: auto; touch-action: none;
    border: 1px solid rgba(255,255,255,0.17); background: radial-gradient(circle, rgba(255,255,255,0.06), rgba(8,11,16,0.4));
    display: grid; place-items: center; backdrop-filter: blur(6px);
  }
  .joystick .stick {
    width: 44px; height: 44px; border-radius: 50%; background: rgba(247,242,232,0.22);
    border: 1px solid rgba(255,255,255,0.3); display: grid; place-items: center;
    transition: transform 0.05s linear;
  }
  .joystick .stick i { width: 12px; height: 12px; border-radius: 50%; background: rgba(247,242,232,0.55); }
  .action-buttons { display: flex; gap: 10px; pointer-events: auto; align-items: flex-end; }
  .action {
    width: 62px; height: 62px; border-radius: 50%; touch-action: none;
    border: 1px solid rgba(255,181,69,0.42); background: rgba(255,181,69,0.12);
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
    color: var(--amber); backdrop-filter: blur(6px);
  }
  .action b { font-size: 16px; font-weight: 400; line-height: 1; }
  .action span { font-family: var(--mono); font-size: 6px; letter-spacing: 0.1em; }
  .action.core { border-color: rgba(192,132,252,0.45); background: rgba(192,132,252,0.13); color: var(--violet); margin-bottom: 16px; }
  .action:active { transform: scale(0.94); background: rgba(255,181,69,0.28); }
  .hud-bottom { bottom: max(10px, env(safe-area-inset-bottom)); }
  .pilot-card { min-width: 0; }
  .pilot-info { min-width: 80px; }
  .ability-row { display: none; }
  .hud-help { display: none; }
  .pilot-card { max-width: 52vw; }
}
@media (max-width: 520px) {
  .mainnav { display: none; }
  .topbar { justify-content: space-between; }
  .topbar-right { gap: 5px; }
  .wallet-chip { font-size: 9px; }
  .wallet { margin-right: 0; }
  .workshop-grid { padding: 8px; gap: 8px; }
  .stage-panel { height: 350px; min-height: 350px; }
  .stage-name-block h1 { font-size: 44px; }
  .stage-sub { font-size: 8px; }
  .stage-top { top: 10px; left: 12px; right: 12px; }
  .stats-panel { padding: 14px 12px; }
  .build-panel { min-height: 520px; border-radius: 16px; }
  .stat-list { grid-template-columns: 1fr 1fr; gap: 7px 12px; }
  .stat-row { grid-template-columns: 50px 1fr 28px; }
  .modal { padding: 22px; border-radius: 20px; }
  .help-modal { padding: 20px; }
  .result-body { padding: 18px 20px 22px; }
  .result-banner { padding: 22px 20px 18px; }
  .result-banner .rb-ball { width: 130px; height: 130px; right: -18px; bottom: -10px; }
  .result-stats { grid-template-columns: 1fr 1fr; }
  .ability-row { gap: 6px; }
  .ability-ring, .ability-ring svg { width: 37px; height: 37px; }
  .action { width: 56px; height: 56px; }
  .joystick { width: 92px; height: 92px; }
  .mobile-controls { left: 14px; right: 14px; bottom: max(85px, calc(env(safe-area-inset-bottom) + 72px)); }
  .pilot-card { max-width: 50vw; }
  .pilot-name-row span { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

