/* Shared world constants & helpers for the arena engine. */

export const W = 1200;
export const H = 780;
export const CX = 600;
export const CY = 390;
export const TAU = Math.PI * 2;

export const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
export const distXY = (x1, y1, x2, y2) => Math.hypot(x1 - x2, y1 - y2);
export const norm = (x, y) => {
  const d = Math.hypot(x, y);
  return d > 0.0001 ? { x: x / d, y: y / d, d } : { x: 0, y: 0, d: 0 };
};
export const rand = (a, b) => a + Math.random() * (b - a);
export const choose = (arr) => arr[Math.floor(Math.random() * arr.length)];
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const fmtClock = (sec) => `${Math.floor(sec / 60)}:${String(Math.floor(sec % 60)).padStart(2, '0')}`;

export const RACE = {
  outerA: 512, outerB: 318,
  innerA: 368, innerB: 184,
  midA: 440, midB: 251,
};

export const CROWD = Array.from({ length: 120 }, (_, i) => ({
  angle: (i / 120) * TAU + Math.random() * 0.04,
  r: 0.5 + Math.random() * 1.1,
  size: 1 + Math.random() * 2.8,
  color: choose(['#ffb545', '#67e8f9', '#ff9ed2', '#a7f36b', '#c084fc', '#f7f2e8']),
  phase: Math.random() * TAU,
}));

export const CHAT = [
  ['GLOWPOP', 'that pattern is CRIMINAL. love it.'],
  ['BONK', '10/10 would get shoved by this ball'],
  ['MOTH', 'the hat is carrying the whole build'],
  ['NEEDLE', 'budget wizard. disgusting.'],
  ['TINY', 'core says fire. face says trust issues.'],
  ['RUSTY', 'i have fought worse. not today, though.'],
  ['PIP', 'one more roll. i can fix it.'],
];

export const ellipsePoint = (a, b, theta) => ({
  x: CX + Math.cos(theta) * a,
  y: CY + Math.sin(theta) * b,
});

export const ellipseTheta = (x, y, a = RACE.midA, b = RACE.midB) => Math.atan2((y - CY) / b, (x - CX) / a);

export function circleText(ctx, text, x, y, size, color, align = 'center') {
  ctx.save();
  ctx.font = `700 ${size}px 'JetBrains Mono', monospace`;
  ctx.fillStyle = color;
  ctx.textAlign = align;
  ctx.textBaseline = 'middle';
  ctx.fillText(text, x, y);
  ctx.restore();
}

/* BLOBSMITH — arena engine core: input, physics, effects, HUD. */

import { RIVALS, CORES, MOODS, MATERIALS } from './data.js';
import { computeBuild, buildLayouts } from './build.js';
import { drawBlob, alpha, lighten, darken } from './blob.js';
import { audio } from './audio.js';
import {
  W, H, CX, CY, TAU, dist, norm, rand, choose, clamp, fmtClock, ellipseTheta,
} from './constants.js';
import { modeMethods } from './modes.js';

const DASH_CD = 1.65;
const CORE_CD = 6.8;

function rivalFor(wins) {
  const poolSize = Math.min(RIVALS.length, 2 + Math.floor(wins / 2));
  return choose(RIVALS.slice(0, poolSize));
}

function diffFor(wins, mode) {
  const base = 0.9 + Math.min(0.24, wins * 0.022);
  return base + (mode === 'race' ? 0.04 : 0);
}

export class ArenaGame {
  constructor({ mode, canvas, build, save, onEnd, onQuit }) {
    this.mode = mode;
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.build = build;
    this.save = save;
    this.onEnd = onEnd;
    this.onQuit = onQuit;

    this.dead = false;
    this.paused = false;
    this.started = false;
    this.ending = false;
    this.finished = false;
    this.finishTimer = 0;
    this.payload = null;
    this.countdown = 3.4;
    this.countDisplay = null;
    this.elapsed = 0;
    this.timeLeft = 0;
    this.timeLimit = 0;
    this.shake = 0;
    this.flash = 0;
    this.flashColor = '255,255,255';
    this.noticeTimer = 0;
    this.hudAcc = 0;
    this.sfxCd = 0;
    this.coreFlash = 0;

    this.keys = new Set();
    this.input = { x: 0, y: 0 };
    this.touchInput = { x: 0, y: 0 };
    this.aim = { x: CX, y: CY, active: false, t: -99 };

    this.balls = [];
    this.player = null;
    this.rival = null;
    this.bossBall = null;
    this.projectiles = [];
    this.particles = [];
    this.damageNumbers = [];
    this.shockwaves = [];
    this.zaps = [];
    this.coreBursts = [];
    this.telegraph = null;
    this.ringR = 300;
    this.score = 0;
    this.impact = 0;
    this.progress = 0;
    this.arenaT = 0;

    this.abort = new AbortController();
    this.boundFrame = this.frame.bind(this);

    this.hud = {
      mode: document.getElementById('hudMode'),
      objective: document.getElementById('hudObjective'),
      timer: document.getElementById('hudTimer'),
      sub: document.getElementById('hudSub'),
      notice: document.getElementById('hudNotice'),
      bossWrap: document.getElementById('bossBarWrap'),
      bossBar: document.getElementById('bossHpBar'),
      bossText: document.getElementById('bossHpText'),
      pilotHp: document.getElementById('pilotHp'),
      pilotStatus: document.getElementById('pilotStatus'),
      pilotName: document.getElementById('pilotName'),
      coreGlyph: document.getElementById('coreGlyph'),
      dashRing: document.getElementById('dashRing'),
      coreRing: document.getElementById('coreRing'),
      dashAbility: document.getElementById('dashAbility'),
      coreAbility: document.getElementById('coreAbility'),
      countdown: document.getElementById('countdownOverlay'),
      pauseOverlay: document.getElementById('pauseOverlay'),
      pauseBtn: document.getElementById('pauseBtn'),
      resumeBtn: document.getElementById('resumeBtn'),
      quitBtn: document.getElementById('quitBtn'),
      mobile: document.getElementById('mobileControls'),
      joystick: document.getElementById('joystick'),
      stick: document.getElementById('stick'),
      dashBtn: document.getElementById('dashBtn'),
      coreBtn: document.getElementById('coreBtn'),
    };

    this.hud.bossWrap.classList.add('hidden');
    this.hud.mobile.style.display = mode === 'showcase' ? 'none' : '';
    this.hud.notice.classList.remove('show');
    this.hud.notice.textContent = '';
    this.resize();
    this.bindInput();
    this.initMode();

    this.updateHud(true);
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.boundFrame);
  }

  /* ── lifecycle ─────────────────────────────────────────── */
  start() {
    this.showCountdown('3');
  }

  destroy() {
    this.dead = true;
    cancelAnimationFrame(this.raf);
    this.abort.abort();
    if (this.hud) {
      this.hud.mobile.style.display = '';
      this.hud.countdown.classList.add('hidden');
      this.hud.countdown.innerHTML = '<span></span>';
      this.hud.notice.classList.remove('show');
      this.hud.pauseOverlay.classList.add('hidden');
      this.hud.bossWrap.classList.add('hidden');
    }
    clearTimeout(this.noticeTimer);
  }

  resize() {
    const cw = window.innerWidth;
    const ch = window.innerHeight;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.cw = cw;
    this.ch = ch;
    this.dpr = dpr;
    this.canvas.width = Math.round(cw * dpr);
    this.canvas.height = Math.round(ch * dpr);
    this.canvas.style.width = `${cw}px`;
    this.canvas.style.height = `${ch}px`;
    const viewW = this.viewW || 960;
    const viewH = this.viewH || 780;
    this.scale = Math.min(cw / viewW, ch / viewH);
    this.ox = cw / 2 - CX * this.scale;
    this.oy = ch / 2 - CY * this.scale;
  }

  screenToWorld(clientX, clientY) {
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: (clientX - rect.left - this.ox) / this.scale,
      y: (clientY - rect.top - this.oy) / this.scale,
    };
  }

  /* ── input ─────────────────────────────────────────────── */
  bindInput() {
    const signal = this.abort.signal;

    this.onResize = () => this.resize();
    window.addEventListener('resize', this.onResize, { signal });
    window.addEventListener('orientationchange', this.onResize, { signal });

    window.addEventListener('keydown', (event) => {
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ShiftLeft', 'ShiftRight'].includes(event.code)) {
        event.preventDefault();
      }
      this.keys.add(event.code);
      if (this.paused || !this.started || this.ending) return;
      if (event.repeat) return;
      if (event.code === 'Space') this.tryDash(this.player, this.getDashDir());
      if (event.code === 'ShiftLeft' || event.code === 'ShiftRight') this.useCore(this.player);
    }, { signal });

    window.addEventListener('keyup', (event) => {
      this.keys.delete(event.code);
    }, { signal });

    this.canvas.addEventListener('pointermove', (event) => {
      if (event.pointerType === 'touch') return;
      const p = this.screenToWorld(event.clientX, event.clientY);
      this.aim.x = p.x;
      this.aim.y = p.y;
      this.aim.active = true;
      this.aim.t = this.elapsed;
    }, { signal });

    this.hud.pauseBtn.addEventListener('click', () => this.togglePause(), { signal });
    this.hud.resumeBtn.addEventListener('click', () => this.togglePause(false), { signal });
    this.hud.quitBtn.addEventListener('click', () => { audio.click(); this.onQuit(); }, { signal });

    // touch joystick
    const joy = this.hud.joystick;
    const stick = this.hud.stick;
    let joyId = null;
    const moveJoy = (event) => {
      const rect = joy.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      let dx = event.clientX - cx;
      let dy = event.clientY - cy;
      const max = rect.width * 0.34;
      const d = Math.hypot(dx, dy);
      if (d > max) {
        dx = (dx / d) * max;
        dy = (dy / d) * max;
      }
      this.touchInput.x = dx / max;
      this.touchInput.y = dy / max;
      stick.style.transform = `translate(${dx}px, ${dy}px)`;
    };
    joy.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      joyId = event.pointerId;
      joy.setPointerCapture(event.pointerId);
      moveJoy(event);
    }, { signal });
    joy.addEventListener('pointermove', (event) => {
      if (joyId === event.pointerId) moveJoy(event);
    }, { signal });
    const endJoy = (event) => {
      if (joyId !== event.pointerId) return;
      joyId = null;
      this.touchInput.x = 0;
      this.touchInput.y = 0;
      stick.style.transform = 'translate(0px, 0px)';
    };
    joy.addEventListener('pointerup', endJoy, { signal });
    joy.addEventListener('pointercancel', endJoy, { signal });

    this.hud.dashBtn.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      if (this.started && !this.ending) this.tryDash(this.player, this.getDashDir());
    }, { signal });
    this.hud.coreBtn.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      if (this.started && !this.ending) this.useCore(this.player);
    }, { signal });

    // hide touch controls if mouse is used on a hybrid device
    this.canvas.addEventListener('pointerdown', (event) => {
      if (event.pointerType === 'mouse' && this.hud.mobile) this.hud.mobile.style.opacity = '0.55';
    }, { signal });
  }

  readInput() {
    if (this.ending || this.paused) { this.input.x = 0; this.input.y = 0; return; }
    let x = 0;
    let y = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y -= 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
    if (Math.abs(this.touchInput.x) > 0.08 || Math.abs(this.touchInput.y) > 0.08) {
      x = this.touchInput.x;
      y = this.touchInput.y;
    }
    const n = norm(x, y);
    this.input.x = n.x * Math.min(1, n.d);
    this.input.y = n.y * Math.min(1, n.d);
    this.input.mag = Math.min(1, n.d);
    this.player?.setInput?.(this.input.x, this.input.y);
  }

  getDashDir() {
    const p = this.player;
    if (!p) return { x: 1, y: 0 };
    const mouseRecent = this.aim.active && this.elapsed - this.aim.t < 3.5;
    if (mouseRecent) {
      const n = norm(this.aim.x - p.x, this.aim.y - p.y);
      if (n.d > 12) return { x: n.x, y: n.y };
    }
    if (this.input.mag > 0.15) {
      const n = norm(this.input.x, this.input.y);
      return { x: n.x, y: n.y };
    }
    return { x: Math.cos(p.facing || 0), y: Math.sin(p.facing || 0) };
  }

  /* ── ball factory ──────────────────────────────────────── */
  makeBall(config, build, { x, y, isPlayer = false, name, radius, hp = 100, boss = false } = {}) {
    const stats = build.phys;
    return {
      config,
      build,
      stats,
      layouts: buildLayouts(config),
      x, y,
      vx: 0, vy: 0,
      r: radius || stats.radius,
      mass: boss ? 30 : stats.mass,
      facing: 0,
      isPlayer,
      isBoss: boss,
      name: name || config.name,
      hp,
      maxHp: hp,
      stun: 0,
      slow: 0,
      burn: 0,
      hitFlash: 0,
      invuln: 0,
      dashCd: 0,
      dashTimer: 0,
      dashDir: { x: 1, y: 0 },
      grapple: 0,
      coreCd: 0,
      autoCd: rand(0.5, 1.6),
      trail: [],
      falling: false,
      fallT: 0,
      ai: {},
      inputX: 0,
      inputY: 0,
      hitCd: 0,
      boostCd: 0,
      progressAngle: 0,
      prevTheta: null,
      topSpeed: 0,
      damageDealt: 0,
    };
  }

  makeRivalBuild(config) {
    const b = computeBuild(config, { mass: 2, energy: 2, motor: 2, armor: 1, luck: 0 }, { ignoreBudget: true });
    const d = diffFor(this.save.stats.wins, this.mode);
    const stats = { ...b.phys };
    stats.maxSpeed *= d;
    stats.accel *= d;
    stats.damage *= 0.9 + d * 0.18;
    stats.defense *= 1.02;
    return { ...b, phys: stats };
  }

  spawnRival() {
    const rival = rivalFor(this.save.stats.wins);
    const build = this.makeRivalBuild(rival.config);
    const ball = this.makeBall(rival.config, build, { x: CX + 150, y: CY, name: rival.name });
    ball.title = rival.title;
    return ball;
  }

  /* ── physics ───────────────────────────────────────────── */
  applyInput(ball, ix, iy, dt) {
    if (ball.falling) return;
    const stats = ball.stats;
    const controlled = ball.stun <= 0;
    const slowMul = ball.slow > 0 ? 0.52 : 1;
    if (controlled && (Math.abs(ix) > 0.01 || Math.abs(iy) > 0.01)) {
      const n = norm(ix, iy);
      const gripFactor = 0.82 + stats.control * 0.18;
      ball.vx += n.x * stats.accel * gripFactor * slowMul * dt;
      ball.vy += n.y * stats.accel * gripFactor * slowMul * dt;
      if (Math.hypot(ball.vx, ball.vy) > 10) ball.facing = Math.atan2(ball.vy, ball.vx);
    }
    if (ball.grapple > 0 && ball.dashDir) {
      ball.vx += ball.dashDir.x * stats.accel * 1.45 * dt;
      ball.vy += ball.dashDir.y * stats.accel * 1.45 * dt;
    }
    let drag = 1.9 - Math.min(0.7, stats.grip * 0.024);
    if (stats.gadgetTags?.has('hover')) drag *= 0.74;
    if (!controlled) drag = 0.35;
    const damp = Math.exp(-drag * dt);
    ball.vx *= damp;
    ball.vy *= damp;

    const maxS = stats.maxSpeed * slowMul * (ball.dashTimer > 0 ? 1.75 : 1) * (ball.stun > 0 ? 0.4 : 1);
    const speed = Math.hypot(ball.vx, ball.vy);
    if (speed > maxS) {
      ball.vx = (ball.vx / speed) * maxS;
      ball.vy = (ball.vy / speed) * maxS;
    }
    ball.x += ball.vx * dt;
    ball.y += ball.vy * dt;
    ball.topSpeed = Math.max(ball.topSpeed || 0, speed);

    if (speed > 30) {
      ball.trail.push({ x: ball.x, y: ball.y, life: 0.24, size: ball.r * 0.5 });
      if (ball.trail.length > 16) ball.trail.shift();
    }
  }

  stepBallTimers(ball, dt) {
    ball.stun = Math.max(0, ball.stun - dt);
    ball.slow = Math.max(0, ball.slow - dt);
    ball.burn = Math.max(0, ball.burn - dt);
    ball.hitFlash = Math.max(0, ball.hitFlash - dt);
    ball.invuln = Math.max(0, ball.invuln - dt);
    ball.dashCd = Math.max(0, ball.dashCd - dt);
    ball.dashTimer = Math.max(0, ball.dashTimer - dt);
    ball.grapple = Math.max(0, ball.grapple - dt);
    ball.coreCd = Math.max(0, ball.coreCd - dt);
    ball.autoCd = Math.max(0, ball.autoCd - dt);
    ball.hitCd = Math.max(0, ball.hitCd - dt);
    ball.boostCd = Math.max(0, ball.boostCd - dt);
    ball.trail.forEach((p) => { p.life -= dt; });
    ball.trail = ball.trail.filter((p) => p.life > 0);
  }

  stepBalls(dt) {
    for (const ball of this.balls) {
      if (ball.falling) {
        ball.fallT += dt;
        continue;
      }
      const ix = ball.isPlayer ? this.input.x : ball.inputX || 0;
      const iy = ball.isPlayer ? this.input.y : ball.inputY || 0;
      this.applyInput(ball, ix, iy, dt);
      this.constrainBall(ball, dt);
      this.stepBallTimers(ball, dt);
    }
  }

  /* ── actions ───────────────────────────────────────────── */
  tryDash(ball, dir) {
    if (!ball || ball.dashCd > 0 || ball.stun > 0 || ball.falling || this.ending || !this.started) return false;
    const n = norm(dir?.x || 0, dir?.y || 0);
    if (n.d === 0) return false;
    ball.dashDir = { x: n.x, y: n.y };
    ball.vx += n.x * ball.stats.dash * 1.28;
    ball.vy += n.y * ball.stats.dash * 1.28;
    ball.dashCd = DASH_CD;
    ball.dashTimer = 0.34;
    ball.invuln = Math.max(ball.invuln, 0.14);
    ball.facing = Math.atan2(n.y, n.x);
    if (ball.stats.gadgetTags?.has('grapple')) ball.grapple = 0.32;
    this.spawnBurst(ball.x - n.x * ball.r * 0.6, ball.y - n.y * ball.r * 0.6, ball.config.accent, 11, 160);
    this.spawnBurst(ball.x, ball.y, ball.config.color, 5, 90);
    if (ball.isPlayer) audio.dash();
    return true;
  }

  useCore(ball) {
    if (!ball || ball.coreCd > 0 || ball.stun > 0 || ball.falling || this.ending || !this.started) return;
    ball.coreCd = CORE_CD;
    const core = ball.config.core;
    const color = CORES[core]?.color || '#ffb545';
    audio.core(core);
    this.coreFlash = 0.45;
    this.coreBursts.push({ x: ball.x, y: ball.y, r: 20, max: 260, color, life: 0.6, maxLife: 0.6 });
    this.spawnBurst(ball.x, ball.y, color, 30, 260);
    this.shake = Math.max(this.shake, 7);

    const targets = this.coreTargets(ball);
    for (const target of targets) {
      const d = dist(ball, target);
      if (core === 'fire') {
        if (d < 250) {
          this.knockback(target, ball.x, ball.y, 310 / target.stats.defense);
          target.burn = 2.4;
          this.damageTarget(target, 10, ball, color);
          this.spawnBurst(target.x, target.y, '#ff8a4c', 18, 200);
        }
      } else if (core === 'ice') {
        if (d < 280) {
          target.slow = 3.2;
          target.stun = Math.max(target.stun, 0.12);
          this.damageTarget(target, 4, ball, color);
          this.spawnBurst(target.x, target.y, '#9be7ff', 22, 130);
        }
      } else if (core === 'zap') {
        if (d < 480) {
          this.zaps.push({ x1: ball.x, y1: ball.y, x2: target.x, y2: target.y, life: 0.35, color });
          target.stun = Math.max(target.stun, 0.55);
          this.knockback(target, ball.x, ball.y, 180 / target.stats.defense);
          this.damageTarget(target, 13, ball, color);
          this.addDamage(target.x, target.y - target.r, 'ZAP', color, 13);
        }
      } else if (core === 'gravity') {
        if (d < 460) {
          this.pullTowards(target, ball.x, ball.y, 420);
          this.damageTarget(target, 6, ball, color);
          this.spawnBurst(target.x, target.y, '#8b5cf6', 15, 80);
        }
      }
    }

    if (core === 'gravity') {
      this.coreBursts.push({ x: ball.x, y: ball.y, r: 30, max: 430, color, life: 0.8, maxLife: 0.8, reverse: true });
      this.shockwaves.push({ x: ball.x, y: ball.y, r: 20, max: 420, speed: 620, hit: true, color, thin: true });
    }
    if (ball.isPlayer) this.showNotice(CORES[core].abilityName.toUpperCase(), color, 750);
    else if (this.mode === 'sumo') this.showNotice(`${ball.name} USED ${CORES[core].abilityName.toUpperCase()}`, color, 750);
  }

  coreTargets(source) {
    const list = [];
    for (const b of this.balls) {
      if (b !== source && !b.falling) list.push(b);
    }
    if (this.bossBall && !this.bossBall.dead && source !== this.bossBall) list.push(this.bossBall);
    return list;
  }

  damageTarget(target, amount, source, color = '#ffb545') {
    if (!target) return;
    if (target.isBoss) {
      const dealt = amount;
      target.hp = Math.max(0, target.hp - dealt);
      target.hitFlash = 0.18;
      this.addDamage(target.x + rand(-20, 20), target.y - target.r * 0.4, Math.round(dealt), color, 14);
      if (this.player) this.player.damageDealt = (this.player.damageDealt || 0) + dealt;
      return;
    }
    if (target.invuln > 0) return;
    if (this.mode === 'race') {
      target.slow = Math.max(target.slow, 0.4);
      return;
    }
    target.hp = Math.max(0, target.hp - amount / Math.max(0.6, target.stats.defense));
    target.hitFlash = 0.18;
    this.addDamage(target.x, target.y - target.r, `-${Math.round(amount)}`, color, 12);
  }

  knockback(ball, fromX, fromY, force) {
    const n = norm(ball.x - fromX, ball.y - fromY);
    ball.vx += n.x * force;
    ball.vy += n.y * force;
  }

  pullTowards(ball, x, y, force) {
    const n = norm(x - ball.x, y - ball.y);
    ball.vx += n.x * force;
    ball.vy += n.y * force;
  }

  /* ── collisions ────────────────────────────────────────── */
  collideBalls(a, b) {
    if (!a || !b || a.falling || b.falling) return;
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const d = Math.hypot(dx, dy);
    const minD = a.r + b.r;
    if (d >= minD || d < 0.001) return;
    const nx = dx / d;
    const ny = dy / d;
    const overlap = minD - d;
    const total = a.mass + b.mass;
    a.x -= nx * overlap * (b.mass / total);
    a.y -= ny * overlap * (b.mass / total);
    b.x += nx * overlap * (a.mass / total);
    b.y += ny * overlap * (a.mass / total);

    const rvx = b.vx - a.vx;
    const rvy = b.vy - a.vy;
    const velN = rvx * nx + rvy * ny;
    if (velN < 0) {
      const e = clamp((a.stats.bounce + b.stats.bounce) * 0.6, 0.12, 0.95);
      const j = (-(1 + e) * velN) / (1 / a.mass + 1 / b.mass);
      a.vx -= (j * nx) / a.mass;
      a.vy -= (j * ny) / a.mass;
      b.vx += (j * nx) / b.mass;
      b.vy += (j * ny) / b.mass;
    }
    const impact = -velN;
    if (impact > 55) {
      const scale = this.mode === 'race' ? 0.3 : 1;
      const pushB = ((a.stats.damage * (0.45 + impact / 290) * (a.dashTimer > 0 ? 1.7 : 1)) / b.stats.defense) * 4.4 * scale;
      const pushA = ((b.stats.damage * (0.45 + impact / 290) * (b.dashTimer > 0 ? 1.7 : 1)) / a.stats.defense) * 4.4 * scale;
      b.vx += nx * pushB;
      b.vy += ny * pushB;
      a.vx -= nx * pushA;
      a.vy -= ny * pushA;
      if (a.stats.gadgetTags?.has('thorns')) this.knockback(b, a.x, a.y, pushB * 0.22);
      if (b.stats.gadgetTags?.has('thorns')) this.knockback(a, b.x, b.y, pushA * 0.22);
      a.stun = Math.max(a.stun, 0.08);
      b.stun = Math.max(b.stun, 0.08);
      a.hitFlash = 0.13;
      b.hitFlash = 0.13;
      const mx = (a.x + b.x) / 2;
      const my = (a.y + b.y) / 2;
      this.spawnBurst(mx, my, '#fff0cf', 10 + Math.min(14, impact / 40), 140 + impact * 0.4);
      this.shake = Math.max(this.shake, Math.min(12, impact / 35));
      if (this.mode === 'sumo') {
        this.impact += impact;
        this.score += impact / 10;
        if (impact > 160) this.addDamage(mx, my - 20, impact > 320 ? 'KRAK!' : 'WHAM', '#ffd38a', 15);
      }
      if (this.sfxCd <= 0) {
        audio.bump(clamp(impact / 220, 0.4, 1.8));
        this.sfxCd = 0.09;
      }
    }
  }

  /* ── projectiles ───────────────────────────────────────── */
  fireProjectile(owner, target, { damage, color, speed = 420, radius = 7, boss = false } = {}) {
    if (!target) return;
    const n = norm(target.x - owner.x, target.y - owner.y);
    if (n.d === 0) return;
    this.projectiles.push({
      x: owner.x + n.x * owner.r,
      y: owner.y + n.y * owner.r,
      vx: n.x * speed,
      vy: n.y * speed,
      r: radius,
      life: 2.6,
      color: color || owner.config.accent,
      owner,
      damage: damage ?? owner.stats.damage * 0.55,
      boss,
      trail: [],
    });
    this.spawnBurst(owner.x + n.x * owner.r, owner.y + n.y * owner.r, color || owner.config.accent, 6, 70);
    if (owner.isPlayer) audio.tone({ freq: 680, dur: 0.08, type: 'square', gain: 0.03, slide: -220 });
  }

  autoFire(ball, target) {
    if (!ball || !target || target.dead || ball.falling) return;
    if (!ball.stats.gadgetTags?.has('projectile')) return;
    if (ball.autoCd > 0) return;
    ball.autoCd = 1.82 - Math.min(0.4, ball.stats.control * 0.08);
    this.fireProjectile(ball, target, { damage: ball.stats.damage * 0.7 });
  }

  updateProjectiles(dt) {
    const alive = [];
    for (const p of this.projectiles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.trail.push({ x: p.x, y: p.y, life: 0.18 });
      if (p.trail.length > 8) p.trail.shift();
      p.trail.forEach((t) => { t.life -= dt; });

      let hit = false;
      if (p.boss) {
        if (this.player && !this.player.falling && dist(p, this.player) < p.r + this.player.r) {
          if (this.player.invuln <= 0) {
            this.player.hp = Math.max(0, this.player.hp - p.damage / Math.max(0.7, this.player.stats.defense));
            this.player.hitFlash = 0.2;
            this.player.invuln = 0.3;
            this.addDamage(this.player.x, this.player.y - this.player.r, `-${Math.round(p.damage)}`, '#ff8f86', 13);
            this.spawnBurst(p.x, p.y, p.color, 16, 200);
            this.shake = Math.max(this.shake, 5);
            audio.hit(1);
          }
          hit = true;
        }
      } else {
        for (const b of this.balls) {
          if (!b || b === p.owner || b.falling) continue;
          if (dist(p, b) < p.r + b.r) {
            this.applyProjectileHit(p, b);
            hit = true;
            break;
          }
        }
        if (!hit && this.bossBall && !this.bossBall.dead && dist(p, this.bossBall) < p.r + this.bossBall.r) {
          this.applyProjectileHit(p, this.bossBall);
          hit = true;
        }
      }
      if (!hit && (p.x < -100 || p.x > W + 100 || p.y < -100 || p.y > H + 100)) hit = true;
      if (p.life > 0 && !hit) alive.push(p);
    }
    this.projectiles = alive;
  }

  applyProjectileHit(p, target) {
    if (target.isBoss) {
      this.damageTarget(target, p.damage, p.owner, p.color);
      this.spawnBurst(p.x, p.y, p.color, 12, 160);
      this.addDamage(p.x, p.y - 14, `${Math.round(p.damage)}`, p.color, 12);
      audio.hit(0.6);
      return;
    }
    if (this.mode === 'sumo') {
      const n = norm(p.vx, p.vy);
      target.vx += n.x * (110 + p.owner.stats.damage * 4);
      target.vy += n.y * (110 + p.owner.stats.damage * 4);
      this.impact += 50;
      this.score += 5;
      if (this.mode === 'race') target.slow = 0.6;
    } else {
      target.slow = Math.max(target.slow, 0.6);
      this.knockback(target, p.x, p.y, 90 / target.stats.defense);
    }
    target.hitFlash = 0.16;
    this.spawnBurst(p.x, p.y, p.color, 14, 170);
    this.addDamage(p.x, p.y - 12, 'PLINK', p.color, 10);
    audio.hit(0.45);
  }

  /* ── effects ───────────────────────────────────────────── */
  spawnBurst(x, y, color, count = 12, power = 180) {
    for (let i = 0; i < count; i += 1) {
      const a = Math.random() * TAU;
      const s = rand(0.25, 1) * power;
      this.particles.push({
        x, y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        life: rand(0.28, 0.8),
        maxLife: 0.8,
        size: rand(1.6, 4.8),
        color,
        drag: 2.4,
        kind: Math.random() > 0.7 ? 'spark' : 'dot',
      });
    }
    if (this.particles.length > 700) this.particles.splice(0, this.particles.length - 700);
  }

  addDamage(x, y, text, color = '#f7f2e8', size = 12) {
    this.damageNumbers.push({ x, y, text, color, size, life: 0.85, maxLife: 0.85, vy: -55 });
    if (this.damageNumbers.length > 20) this.damageNumbers.shift();
  }

  updateEffects(dt) {
    this.coreFlash = Math.max(0, this.coreFlash - dt);
    this.flash = Math.max(0, this.flash - dt * 2.2);
    this.shake *= 0.9;
    this.sfxCd = Math.max(0, this.sfxCd - dt);

    for (const p of this.particles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= Math.exp(-p.drag * dt);
      p.vy *= Math.exp(-p.drag * dt);
      if (p.kind === 'spark') p.size *= 0.98;
    }
    this.particles = this.particles.filter((p) => p.life > 0);

    for (const d of this.damageNumbers) {
      d.life -= dt;
      d.y += d.vy * dt;
      d.vy *= 0.96;
    }
    this.damageNumbers = this.damageNumbers.filter((d) => d.life > 0);

    for (const w of this.shockwaves) {
      w.r += w.speed * dt;
      w.life -= dt;
    }
    this.shockwaves = this.shockwaves.filter((w) => w.r < w.max && w.life > 0);

    for (const z of this.zaps) z.life -= dt;
    this.zaps = this.zaps.filter((z) => z.life > 0);

    for (const b of this.coreBursts) {
      b.life -= dt;
      b.r += ((b.reverse ? b.max - b.r : b.r) * 3 + 160) * dt;
    }
    this.coreBursts = this.coreBursts.filter((b) => b.life > 0);
  }

  /* ── outcome ───────────────────────────────────────────── */
  queueFinish(payload, delay = 0) {
    if (this.ending) return;
    this.ending = true;
    this.payload = payload;
    this.finishTimer = delay;
    if (delay <= 0) {
      this.finished = true;
      this.ending = false;
      this.onEnd?.(payload);
    }
  }

  showNotice(text, color = '#f7f2e8', duration = 1200) {
    const el = this.hud.notice;
    if (!el) return;
    clearTimeout(this.noticeTimer);
    el.textContent = text;
    el.style.color = color;
    el.classList.remove('show', 'pop');
    void el.offsetWidth;
    el.classList.add('show', 'pop');
    this.noticeTimer = setTimeout(() => el.classList.remove('show'), duration);
  }

  showCountdown(text) {
    const overlay = this.hud.countdown;
    overlay.innerHTML = `<span>${text}</span>`;
    overlay.classList.remove('hidden');
  }

  togglePause(force) {
    if (this.ending || this.finished || !this.started) return;
    const next = force === undefined ? !this.paused : force;
    if (next === this.paused) return;
    this.paused = next;
    this.hud.pauseOverlay.classList.toggle('hidden', !this.paused);
    audio.click();
    if (this.paused) audio.tone({ freq: 300, dur: 0.15, type: 'sine', gain: 0.06, slide: -100 });
  }

  /* ── HUD ───────────────────────────────────────────────── */
  updateHud(force = false) {
    this.hudAcc += 0.016;
    if (!force && this.hudAcc < 0.07) return;
    this.hudAcc = 0;

    const h = this.hud;
    if (this.mode === 'showcase') {
      h.timer.textContent = '★';
    } else {
      h.timer.textContent = String(Math.ceil(this.timeLeft));
    }

    if (this.player) {
      const dashPct = this.player.dashCd <= 0 ? 0 : this.player.dashCd / DASH_CD;
      const corePct = this.player.coreCd <= 0 ? 0 : this.player.coreCd / CORE_CD;
      if (h.dashRing) h.dashRing.style.strokeDashoffset = String(113 * dashPct);
      if (h.coreRing) h.coreRing.style.strokeDashoffset = String(113 * corePct);
      h.dashAbility.classList.toggle('ready', this.player.dashCd <= 0);
      h.coreAbility.classList.toggle('ready', this.player.coreCd <= 0);
      const hpRatio = this.player.maxHp ? this.player.hp / this.player.maxHp : 1;
      h.pilotHp.style.width = `${clamp(hpRatio * 100, 0, 100)}%`;
      h.pilotHp.style.background = hpRatio < 0.35
        ? 'linear-gradient(90deg,#ff5d5d,#ff9d7a)'
        : 'linear-gradient(90deg,var(--teal),#a7f3e0)';
      if (this.player.hp <= 0 || (this.mode === 'sumo' && this.player.falling)) h.pilotStatus.textContent = 'BALL LOST';
      else if (this.player.hp < this.player.maxHp * 0.35 && this.mode === 'boss') h.pilotStatus.textContent = 'CRITICAL · KEEP MOVING';
      else if (this.player.coreCd <= 0) h.pilotStatus.textContent = `${CORES[this.player.config.core].abilityName.toUpperCase()} READY`;
      else if (this.player.dashCd <= 0) h.pilotStatus.textContent = 'DASH READY';
      else h.pilotStatus.textContent = 'RECOVERING';
      h.coreGlyph.textContent = CORES[this.player.config.core].icon;
    }

    if (this.mode === 'boss' && this.bossBall) {
      const ratio = this.bossBall.hp / this.bossBall.maxHp;
      h.bossWrap.classList.remove('hidden');
      h.bossBar.style.width = `${ratio * 100}%`;
      h.bossText.textContent = `${Math.ceil(ratio * 100)}%`;
    } else {
      h.bossWrap.classList.add('hidden');
    }

    if (this.mode === 'sumo') {
      h.sub.textContent = `RING ${Math.round(this.ringR)} · IMPACT ${Math.round(this.score)} · LUCK ×${this.player.stats.luck.toFixed(1)}`;
    } else if (this.mode === 'race') {
      const lap = Math.min(2, Math.floor(this.player.progressAngle / TAU) + 1);
      const pos = this.player.progressAngle >= (this.rival?.progressAngle || 0) ? '1ST' : '2ND';
      h.sub.textContent = `LAP ${lap}/2 · ${pos} · ${fmtClock(this.elapsed)}`;
    } else if (this.mode === 'boss') {
      h.sub.textContent = `PHASE ${this.bossBall && this.bossBall.hp < this.bossBall.maxHp * 0.5 ? '2' : '1'} · WARDEN CORE EXPOSED`;
    } else {
      h.sub.textContent = `LIVE LOBBY · 5 SMITHS · CROWD VOTE IN PROGRESS`;
    }
  }

  /* ── main loop ─────────────────────────────────────────── */
  frame(now) {
    if (this.dead) return;
    const dt = Math.min(0.034, Math.max(0, (now - this.last) / 1000));
    this.last = now;
    this.arenaT += dt;
    if (!this.paused) this.update(dt);
    else this.updateEffects(dt * 0.15);
    this.render(now / 1000);
    this.raf = requestAnimationFrame(this.boundFrame);
  }

  update(dt) {
    // countdown
    if (!this.started) {
      this.countdown -= dt;
      if (this.countdown > 0) {
        const n = Math.ceil(this.countdown);
        if (n !== this.countDisplay) {
          this.countDisplay = n;
          this.showCountdown(String(n));
        }
        this.updateEffects(dt);
        return;
      }
      this.started = true;
      this.hud.countdown.classList.add('hidden');
      this.showNotice('ROLL!', '#ffb545', 700);
      audio.tone({ freq: 520, dur: 0.18, type: 'triangle', gain: 0.1, slide: 220 });
      this.updateHud(true);
    }

    if (this.finished) {
      this.updateEffects(dt);
      return;
    }

    if (this.ending) {
      this.finishTimer -= dt;
      this.updateEffects(dt);
      if (this.finishTimer <= 0 && !this.finished) {
        this.finished = true;
        this.ending = false;
        this.onEnd?.(this.payload);
      }
      return;
    }

    this.elapsed += dt;
    if (this.timeLimit > 0) this.timeLeft = Math.max(0, this.timeLeft - dt);
    this.readInput();

    if (this.mode === 'sumo') this.updateSumo(dt);
    else if (this.mode === 'race') this.updateRace(dt);
    else if (this.mode === 'boss') this.updateBoss(dt);
    else if (this.mode === 'showcase') this.updateShowcase(dt);

    this.updateProjectiles(dt);
    this.updateEffects(dt);
    this.updateHud();
  }

  /* ── rendering ─────────────────────────────────────────── */
  render(t) {
    const ctx = this.ctx;
    const { cw, ch, dpr } = this;
    if (!cw) return;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cw, ch);

    // screen backdrop
    const bg = ctx.createRadialGradient(cw / 2, ch * 0.44, 20, cw / 2, ch * 0.5, Math.max(cw, ch) * 0.8);
    bg.addColorStop(0, '#121821');
    bg.addColorStop(0.6, '#080b10');
    bg.addColorStop(1, '#05070a');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cw, ch);

    const sx = this.shake > 0.1 ? rand(-this.shake, this.shake) : 0;
    const sy = this.shake > 0.1 ? rand(-this.shake, this.shake) : 0;
    ctx.save();
    ctx.translate(this.ox + sx, this.oy + sy);
    ctx.scale(this.scale, this.scale);

    this.drawArena(t);
    if (this.drawUnder) this.drawUnder(t);

    const entities = [...this.balls];
    if (this.bossBall && !this.bossBall.dead) entities.push(this.bossBall);
    entities.sort((a, b) => a.y - b.y);
    for (const ball of entities) this.drawBallEntity(ball, t);

    this.drawProjectiles(t);
    this.drawShockwaves(t);
    this.drawZaps(t);
    this.drawParticles();
    this.drawDamageNumbers();
    if (this.drawOver) this.drawOver(t);

    ctx.restore();

    if (this.flash > 0.01) {
      ctx.fillStyle = `rgba(${this.flashColor},${Math.min(0.5, this.flash * 0.4)})`;
      ctx.fillRect(0, 0, cw, ch);
    }
  }

  drawBallEntity(ball, t) {
    if (!ball) return;
    const ctx = this.ctx;
    const fall = ball.falling ? Math.min(1, ball.fallT / 0.75) : 0;
    const opacity = ball.isBoss ? 1 : 1 - fall * 0.85;
    const speed = Math.hypot(ball.vx, ball.vy);
    const look = norm(ball.vx || Math.cos(ball.facing), ball.vy || Math.sin(ball.facing));
    const face = speed > 20 ? { x: look.x, y: look.y } : { x: Math.cos(ball.facing || 0) * 0.35, y: Math.sin(ball.facing || 0) * 0.35 };
    const dashes = ball.dashTimer > 0;

    // trail
    for (const p of ball.trail) {
      ctx.fillStyle = alpha(ball.config.color, (p.life / 0.24) * 0.12);
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (p.life / 0.24), 0, TAU);
      ctx.fill();
    }

    if (ball.slow > 0) {
      ctx.strokeStyle = 'rgba(155,231,255,0.45)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r * 1.17, t * 2, t * 2 + 4.2);
      ctx.stroke();
    }
    if (ball.burn > 0) {
      ctx.strokeStyle = 'rgba(255,138,76,0.4)';
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r * 1.13, -t * 2.5, -t * 2.5 + 3.4);
      ctx.stroke();
    }
    if (ball.stats.gadgetTags?.has('shield')) {
      ctx.strokeStyle = 'rgba(103,232,249,0.28)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r * 1.28, 0, TAU);
      ctx.stroke();
    }

    ctx.save();
    if (fall > 0) {
      ctx.translate(0, fall * 30);
      const sc = 1 - fall * 0.55;
      ctx.translate(ball.x, ball.y);
      ctx.scale(sc, sc);
      ctx.translate(-ball.x, -ball.y);
    }

    drawBlob(ctx, {
      x: ball.x,
      y: ball.y,
      r: ball.r,
      config: ball.config,
      t,
      face,
      layouts: ball.layouts,
      expression: ball.hitFlash > 0.03 ? 'hit' : null,
      glow: dashes ? 0.55 : 0,
      squashDir: speed > 40 ? Math.atan2(ball.vy, ball.vx) : null,
      speedRatio: clamp(speed / Math.max(60, ball.stats.maxSpeed), 0, 1),
      alpha: ball.isBoss ? 1 : Math.max(0, opacity),
    });

    if (ball.hitFlash > 0.03) {
      ctx.globalAlpha = ball.hitFlash * 3;
      ctx.fillStyle = '#fff6e4';
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();

    // labels
    if (!ball.falling) {
      const label = ball.isBoss ? 'WARDEN MK-IV' : ball.isPlayer ? 'YOU' : ball.name;
      const col = ball.isBoss ? '#ff8f86' : ball.isPlayer ? '#ffb545' : 'rgba(247,242,232,0.66)';
      ctx.save();
      ctx.font = `700 ${ball.isBoss ? 11 : 9}px 'JetBrains Mono', monospace`;
      ctx.textAlign = 'center';
      ctx.fillStyle = col;
      ctx.fillText(label, ball.x, ball.y - ball.r - 14);
      if (ball.isPlayer) {
        const bob = Math.sin(t * 4) * 2;
        ctx.fillStyle = '#ffb545';
        ctx.beginPath();
        ctx.moveTo(ball.x, ball.y - ball.r - 30 + bob);
        ctx.lineTo(ball.x - 5, ball.y - ball.r - 38 + bob);
        ctx.lineTo(ball.x + 5, ball.y - ball.r - 38 + bob);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }

    if (fall > 0.05) {
      ctx.strokeStyle = `rgba(255,93,93,${fall * 0.4})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r * (1 + fall), 0, TAU);
      ctx.stroke();
    }
  }

  drawProjectiles(t) {
    const ctx = this.ctx;
    for (const p of this.projectiles) {
      for (const tr of p.trail) {
        ctx.fillStyle = alpha(p.color.startsWith('#') ? p.color : '#f7f2e8', (tr.life / 0.18) * 0.22);
        ctx.beginPath();
        ctx.arc(tr.x, tr.y, p.r * 0.8, 0, TAU);
        ctx.fill();
      }
      ctx.save();
      ctx.shadowColor = p.color;
      ctx.shadowBlur = 14;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.8)';
      ctx.beginPath();
      ctx.arc(p.x - p.r * 0.25, p.y - p.r * 0.25, p.r * 0.35, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  drawShockwaves(t) {
    const ctx = this.ctx;
    for (const w of this.shockwaves) {
      const k = 1 - w.r / w.max;
      ctx.strokeStyle = alpha(w.color || '#ff8a4c', Math.max(0, k) * 0.6);
      ctx.lineWidth = w.thin ? 2 : 6 * k + 1;
      ctx.beginPath();
      ctx.arc(w.x, w.y, w.r, 0, TAU);
      ctx.stroke();
    }
    for (const b of this.coreBursts) {
      const k = b.life / b.maxLife;
      ctx.strokeStyle = alpha(b.color, k * 0.55);
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, TAU);
      ctx.stroke();
    }
  }

  drawZaps(t) {
    const ctx = this.ctx;
    for (const z of this.zaps) {
      ctx.strokeStyle = alpha(z.color, (z.life / 0.35) * 0.9);
      ctx.lineWidth = 2.5;
      ctx.shadowColor = z.color;
      ctx.shadowBlur = 12;
      ctx.beginPath();
      const steps = 7;
      for (let i = 0; i <= steps; i += 1) {
        const p = i / steps;
        const jitter = i === 0 || i === steps ? 0 : rand(-16, 16);
        const x = z.x1 + (z.x2 - z.x1) * p + jitter;
        const y = z.y1 + (z.y2 - z.y1) * p + rand(-16, 16);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
      ctx.shadowBlur = 0;
    }
  }

  drawParticles() {
    const ctx = this.ctx;
    for (const p of this.particles) {
      const k = Math.max(0, p.life / p.maxLife);
      ctx.fillStyle = alpha(p.color.startsWith('#') ? p.color : '#f7f2e8', k);
      if (p.kind === 'spark') {
        ctx.fillRect(p.x - p.size * 0.5, p.y - p.size * 0.5, p.size * 2, p.size * 0.8);
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * k, 0, TAU);
        ctx.fill();
      }
    }
  }

  drawDamageNumbers() {
    const ctx = this.ctx;
    for (const d of this.damageNumbers) {
      const k = d.life / d.maxLife;
      ctx.save();
      ctx.globalAlpha = Math.min(1, k * 1.5);
      ctx.font = `800 ${d.size}px 'Bricolage Grotesque', sans-serif`;
      ctx.textAlign = 'center';
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(8,11,16,0.75)';
      ctx.strokeText(d.text, d.x, d.y);
      ctx.fillStyle = d.color;
      ctx.fillText(d.text, d.x, d.y);
      ctx.restore();
    }
  }
}

Object.assign(ArenaGame.prototype, modeMethods);

/* Arena modes: setup, AI, rules, and mode-specific physics. */

import { RIVALS, GADGET_MAP, MOODS } from './data.js';
import { computeBuild, buildLayouts } from './build.js';
import { alpha, drawBlob } from './blob.js';
import { audio } from './audio.js';
import {
  CX, CY, TAU, dist, norm, rand, choose, clamp, fmtClock,
  RACE, ellipseTheta, ellipsePoint, CHAT,
} from './constants.js';
import { drawSumoArena, drawRaceArena, drawBossArena, drawShowcaseArena } from './arena-art.js';

const T_PI = Math.PI;
const TWO_LAPS = TAU * 2 * 2;

export const modeMethods = {
  initMode() {
    this.balls = [];
    this.projectiles = [];
    this.particles = [];
    this.damageNumbers = [];
    this.shockwaves = [];
    this.zaps = [];
    this.coreBursts = [];
    this.ringR = 300;
    this.arenaT = 0;

    if (this.mode === 'sumo') this.initSumo();
    else if (this.mode === 'race') this.initRace();
    else if (this.mode === 'boss') this.initBoss();
    else this.initShowcase();
  },

  /* ══ SUMO ══════════════════════════════════════════════════ */
  initSumo() {
    this.viewW = 840;
    this.viewH = 790;
    this.resize();
    this.timeLimit = 75;
    this.timeLeft = 75;
    this.ringR = 300;
    this.hud.mode.textContent = 'SUMO RING · ARENA 01';

    this.player = this.makeBall(this.save.config, this.build, {
      x: CX - 155, y: CY, isPlayer: true, name: this.save.config.name,
    });
    this.player.hp = this.player.maxHp = 100;
    this.rival = this.spawnRival();
    this.rival.x = CX + 155;
    this.rival.y = CY;
    this.rival.facing = Math.PI;
    this.rival.stats = { ...this.rival.stats };
    this.rival.mass *= 1;
    this.bossBall = null;
    this.balls = [this.player, this.rival];
    this.aim.x = CX + 400;
    this.aim.y = CY;
    this.hud.objective.textContent = `SHOVE ${this.rival.name} OUT`;
  },

  updateSumo(dt) {
    // ring slowly tightens after 30 seconds
    this.ringR = 300 - Math.max(0, this.elapsed - 30) * 0.7;
    this.ringR = Math.max(255, this.ringR);

    this.aiSumo(dt);
    this.stepBalls(dt);
    this.collideBalls(this.player, this.rival);
    this.autoFire(this.player, this.rival);
    this.autoFire(this.rival, this.player);
    if (this.rival.coreCd <= 0 && dist(this.player, this.rival) < 210 && Math.random() < dt * 0.55) {
      this.useCore(this.rival);
    }
    if (this.player.coreCd <= 0 && this.input.mag > 0.9 && Math.random() < dt * 0.001) this.useCore(this.player);

    if (this.ending) return;

    const pd = Math.hypot(this.player.x - CX, this.player.y - CY);
    const rd = Math.hypot(this.rival.x - CX, this.rival.y - CY);
    const pOut = pd > this.ringR + this.player.r * 0.35;
    const rOut = rd > this.ringR + this.rival.r * 0.35;

    if (pOut || rOut) {
      const win = !pOut && rOut ? true : pOut && !rOut ? false : rd < pd;
      const fallen = [];
      if (pOut) { this.player.falling = true; fallen.push(this.player); }
      if (rOut) { this.rival.falling = true; fallen.push(this.rival); }
      this.launchFall(fallen);
      audio.ringout();
      this.shake = 16;
      this.showNotice(win ? 'RING OUT!' : 'YOU FELL', win ? '#ffb545' : '#ff8f86', 1400);
      this.queueFinish({
        mode: 'sumo',
        win,
        score: Math.round(this.impact),
        time: this.elapsed,
        playerHp: 100,
        bestScore: Math.round(this.impact),
      }, 1.15);
      return;
    }

    if (this.timeLeft <= 0) {
      const win = pd < rd;
      this.showNotice(win ? 'TIME! CLOSER TO CENTRE' : 'TIME! PUSHED OUT', win ? '#ffb545' : '#ff8f86', 1500);
      this.queueFinish({
        mode: 'sumo', win, score: Math.round(this.impact), time: this.elapsed, playerHp: 100,
        bestScore: Math.round(this.impact),
      }, 1.0);
    }
  },

  launchFall(balls) {
    for (const ball of balls) {
      this.spawnBurst(ball.x, ball.y, ball.config.color, 34, 320);
      this.spawnBurst(ball.x, ball.y, '#ffb545', 12, 380);
    }
  },

  aiSumo(dt) {
    const r = this.rival;
    const p = this.player;
    if (!r || !p || r.falling) {
      if (r) { r.inputX = 0; r.inputY = 0; }
      return;
    }
    if (r.stun > 0) { r.inputX = 0; r.inputY = 0; return; }

    const d = dist(r, p);
    const rd = Math.hypot(r.x - CX, r.y - CY);
    const outward = norm(p.x - CX, p.y - CY);
    const flank = {
      x: p.x - outward.x * (p.r + r.r + 46),
      y: p.y - outward.y * (p.r + r.r + 46),
    };
    let targetX = flank.x;
    let targetY = flank.y;

    if (rd > this.ringR - 72) { targetX = CX; targetY = CY; }
    else if (d < r.r + p.r + 34) { targetX = p.x; targetY = p.y; }

    // dodge an incoming dash
    if (p.dashTimer > 0.05 && d < 240) {
      const perp = { x: -(p.y - r.y), y: p.x - r.x };
      const n = norm(perp.x, perp.y);
      const side = (r.x - CX) * n.x + (r.y - CY) * n.y > 0 ? -1 : 1;
      targetX = r.x + n.x * side * 180;
      targetY = r.y + n.y * side * 180;
    }

    // a little crowd-pleasing jitter
    r.ai.wander = (r.ai.wander || 0) - dt;
    if (r.ai.wander <= 0) {
      r.ai.wander = rand(0.7, 1.6);
      r.ai.offX = rand(-30, 30);
      r.ai.offY = rand(-30, 30);
    }
    targetX += r.ai.offX || 0;
    targetY += r.ai.offY || 0;

    const dx = targetX - r.x;
    const dy = targetY - r.y;
    const n = norm(dx, dy);
    // steer away from rim
    let edgeX = 0;
    let edgeY = 0;
    if (rd > this.ringR - 100) {
      const e = norm(CX - r.x, CY - r.y);
      edgeX = e.x * 1.4;
      edgeY = e.y * 1.4;
    }
    const steer = norm(n.x + edgeX, n.y + edgeY);
    r.inputX = steer.x;
    r.inputY = steer.y;

    const aligned = norm(p.x - r.x, p.y - r.y);
    const rimward = (p.x - CX) * aligned.x + (p.y - CY) * aligned.y;
    if (r.dashCd <= 0 && d < 235 && rimward > -20 && Math.random() < dt * (1.5 + this.save.stats.wins * 0.05)) {
      this.tryDash(r, aligned);
    }
    if (r.coreCd <= 0 && d < 200 && Math.random() < dt * 0.8) this.useCore(r);
  },

  /* ══ RACE ══════════════════════════════════════════════════ */
  initRace() {
    this.viewW = 1130;
    this.viewH = 790;
    this.resize();
    this.timeLimit = 100;
    this.timeLeft = 100;
    this.hud.mode.textContent = 'OBSTACLE RACE · ARENA 02';

    this.player = this.makeBall(this.save.config, this.build, {
      x: CX - 46, y: CY - RACE.midB + 10, isPlayer: true, name: this.save.config.name,
    });
    this.player.hp = this.player.maxHp = 100;
    this.rival = this.spawnRival();
    this.rival.x = CX + 46;
    this.rival.y = CY - RACE.midB + 10;
    this.rival.stats.maxSpeed *= 1.02;
    this.bossBall = null;
    this.balls = [this.player, this.rival];

    this.obstacles = [45, 135, 225, 315].map((deg, i) => {
      const p = ellipsePoint(RACE.midA, RACE.midB, (deg * Math.PI) / 180);
      return { x: p.x, y: p.y, r: 23, angle: (i * 1.7) };
    });
    this.boostPads = [22, 112, 202, 292].map((deg) => ({
      ...ellipsePoint(RACE.midA, RACE.midB, (deg * Math.PI) / 180),
      angle: (deg * Math.PI) / 180,
    }));
    for (const ball of this.balls) {
      ball.prevTheta = ellipseTheta(ball.x, ball.y);
      ball.progressAngle = 0;
    }
    this.aim.x = CX + 300;
    this.aim.y = CY - RACE.midB;
    this.hud.objective.textContent = 'FINISH TWO LAPS FIRST';
    this.racePlace = 1;
  },

  updateRace(dt) {
    this.aiRace(dt);
    this.stepBalls(dt);
    this.collideBalls(this.player, this.rival);
    if (this.rival.coreCd <= 0 && dist(this.player, this.rival) < 200 && Math.random() < dt * 0.3) {
      this.useCore(this.rival);
    }
    for (const ball of this.balls) this.trackRaceProgress(ball);
    this.progress = Math.min(2, this.player.progressAngle / TAU);
    this.score = Math.max(this.score, Math.round(this.player.topSpeed || 0));

    if (this.ending) return;

    const playerDone = this.player.progressAngle >= TWO_LAPS;
    const rivalDone = this.rival.progressAngle >= TWO_LAPS;
    if (playerDone || rivalDone) {
      const win = playerDone && (!rivalDone || this.player.progressAngle >= this.rival.progressAngle);
      this.showNotice(win ? 'FINISH! FIRST PLACE' : 'FINISH! SECOND PLACE', win ? '#ffe08a' : '#ffb0a0', 1600);
      if (win && this.player) this.spawnBurst(this.player.x, this.player.y, '#ffe08a', 46, 340);
      this.queueFinish({
        mode: 'race',
        win,
        score: Math.round(this.player.topSpeed),
        time: this.elapsed,
        progress: 2,
        playerHp: 100,
        bestScore: Math.round(this.player.topSpeed),
      }, 1.15);
      return;
    }
    if (this.timeLeft <= 0) {
      const win = this.player.progressAngle >= this.rival.progressAngle;
      this.showNotice('TIME UP', win ? '#ffe08a' : '#ffb0a0', 1400);
      this.queueFinish({
        mode: 'race', win, score: Math.round(this.player.topSpeed), time: this.elapsed,
        progress: Math.min(2, this.player.progressAngle / TAU), playerHp: 100,
        bestScore: Math.round(this.player.topSpeed),
      }, 1.0);
    }
  },

  trackRaceProgress(ball) {
    const theta = ellipseTheta(ball.x, ball.y);
    if (ball.prevTheta == null) ball.prevTheta = theta;
    let d = theta - ball.prevTheta;
    while (d > T_PI) d -= TAU;
    while (d < -T_PI) d += TAU;
    ball.progressAngle = Math.max(0, ball.progressAngle + d);
    ball.prevTheta = theta;
  },

  aiRace(dt) {
    const r = this.rival;
    if (!r || r.falling) return;
    if (r.stun > 0) { r.inputX = 0; r.inputY = 0; return; }

    const theta = ellipseTheta(r.x, r.y);
    const look = 0.44 + clamp(r.stats.control * 0.03, 0, 0.12);
    let tx = CX + Math.cos(theta + look) * RACE.midA;
    let ty = CY + Math.sin(theta + look) * RACE.midB;

    // obstacle avoidance
    for (const ob of this.obstacles) {
      const d = Math.hypot(tx - ob.x, ty - ob.y);
      if (d < 115) {
        const away = norm(tx - ob.x, ty - ob.y);
        tx += away.x * (115 - d) * 1.4;
        ty += away.y * (115 - d) * 1.4;
      }
    }
    // edge avoidance
    const innerF = ((r.x - CX) / RACE.innerA) ** 2 + ((r.y - CY) / RACE.innerB) ** 2;
    const outerF = ((r.x - CX) / RACE.outerA) ** 2 + ((r.y - CY) / RACE.outerB) ** 2;
    if (innerF < 1.22) {
      const out = norm(r.x - CX, r.y - CY);
      tx += out.x * 90;
      ty += out.y * 90;
    }
    if (outerF > 0.9) {
      const inn = norm(CX - r.x, CY - r.y);
      tx += inn.x * 90;
      ty += inn.y * 90;
    }

    const n = norm(tx - r.x, ty - r.y);
    r.inputX = n.x;
    r.inputY = n.y;

    const tangent = norm(-Math.sin(theta) * RACE.midA, Math.cos(theta) * RACE.midB);
    if (r.dashCd <= 0 && r.boostCd < 0.2 && Math.random() < dt * 0.7) {
      this.tryDash(r, tangent);
    }
  },

  constrainBall(ball, dt) {
    if (this.mode === 'race') return this.constrainRace(ball, dt);
    if (this.mode === 'boss') return this.constrainBoss(ball);
    return undefined;
  },

  constrainRace(ball, dt) {
    const e = ball.stats.bounce;

    // obstacles
    for (const ob of this.obstacles) {
      const dx = ball.x - ob.x;
      const dy = ball.y - ob.y;
      const d = Math.hypot(dx, dy);
      const min = ob.r + ball.r;
      if (d < min && d > 0.001) {
        const nx = dx / d;
        const ny = dy / d;
        ball.x = ob.x + nx * min;
        ball.y = ob.y + ny * min;
        const vn = ball.vx * nx + ball.vy * ny;
        if (vn < 0) {
          ball.vx -= (1 + e) * vn * nx;
          ball.vy -= (1 + e) * vn * ny;
        }
        if (Math.hypot(ball.vx, ball.vy) > 120) {
          this.spawnBurst(ob.x + nx * ob.r, ob.y + ny * ob.r, '#ffb545', 7, 110);
        }
      }
    }

    // boost pads
    if (ball.boostCd <= 0) {
      for (const pad of this.boostPads) {
        if (Math.hypot(ball.x - pad.x, ball.y - pad.y) < 46) {
          const tangent = norm(-Math.sin(pad.angle) * RACE.midA, Math.cos(pad.angle) * RACE.midB);
          ball.vx += tangent.x * 250;
          ball.vy += tangent.y * 250;
          ball.boostCd = 1.5;
          this.spawnBurst(pad.x, pad.y, '#5ce1c6', 14, 190);
          if (ball.isPlayer) {
            audio.tone({ freq: 420, dur: 0.14, type: 'triangle', gain: 0.05, slide: 220 });
            this.addDamage(ball.x, ball.y - ball.r, 'BOOST', '#5ce1c6', 11);
          }
          break;
        }
      }
    }

    // outer wall
    const aO = RACE.outerA - ball.r * 0.92;
    const bO = RACE.outerB - ball.r * 0.92;
    let nx = (ball.x - CX) / aO;
    let ny = (ball.y - CY) / bO;
    let f = nx * nx + ny * ny;
    if (f > 1) {
      const k = 1 / Math.sqrt(f);
      ball.x = CX + (ball.x - CX) * k;
      ball.y = CY + (ball.y - CY) * k;
      const gn = norm((ball.x - CX) / (aO * aO), (ball.y - CY) / (bO * bO));
      const vn = ball.vx * gn.x + ball.vy * gn.y;
      if (vn > 0) {
        ball.vx -= (1 + e) * vn * gn.x;
        ball.vy -= (1 + e) * vn * gn.y;
      }
    }

    // inner wall
    const aI = RACE.innerA + ball.r * 0.92;
    const bI = RACE.innerB + ball.r * 0.92;
    nx = (ball.x - CX) / aI;
    ny = (ball.y - CY) / bI;
    f = nx * nx + ny * ny;
    if (f < 1) {
      if (f < 0.0001) {
        ball.x = CX + aI;
        ball.y = CY;
      } else {
        const k = 1 / Math.sqrt(f);
        ball.x = CX + (ball.x - CX) * k;
        ball.y = CY + (ball.y - CY) * k;
      }
      const gn = norm((ball.x - CX) / (aI * aI), (ball.y - CY) / (bI * bI));
      const vn = ball.vx * gn.x + ball.vy * gn.y;
      if (vn < 0) {
        ball.vx -= (1 + e) * vn * gn.x;
        ball.vy -= (1 + e) * vn * gn.y;
      }
    }
  },

  /* ══ BOSS ══════════════════════════════════════════════════ */
  initBoss() {
    this.viewW = 870;
    this.viewH = 790;
    this.resize();
    this.timeLimit = 120;
    this.timeLeft = 120;
    this.hud.mode.textContent = 'BOSS BATTLE · ARENA 03';

    this.player = this.makeBall(this.save.config, this.build, {
      x: CX, y: CY + 240, isPlayer: true, name: this.save.config.name,
    });
    const maxHp = Math.round(100 + this.build.phys.defense * 5);
    this.player.hp = this.player.maxHp = maxHp;

    const bossConfig = {
      ...RIVALS[4].config,
      name: 'WARDEN',
      color: '#4a1d22',
      accent: '#ff5d5d',
      pattern: 'hazard',
      glow: 0.85,
      eyes: 'grumpy',
      mouth: 'fangs',
      mood: 'angry',
      core: 'gravity',
      material: 'stone',
      gadgets: ['weapons_spike_ring', 'weapons_doom_drill', 'weapons_morning_star', 'weird_event_horizon'],
      rotation: 18,
      mirror: true,
    };
    const bossBuild = computeBuild(bossConfig, { mass: 3, energy: 3, motor: 1, armor: 2 }, { ignoreBudget: true });
    const bossHp = 560 + Math.min(280, this.save.stats.wins * 26);
    this.bossBall = this.makeBall(bossConfig, bossBuild, {
      x: CX, y: CY - 60, boss: true, radius: 92, hp: bossHp, name: 'WARDEN',
    });
    this.bossBall.stats = { ...bossBuild.phys, maxSpeed: 48, damage: 26, defense: 1.2, mass: 40 };
    this.bossBall.attack = null;
    this.bossBall.attackTimer = 2.6;
    this.bossBall.hitCd = 0;
    this.balls = [this.player];
    this.ringR = 340;
    this.aim.x = CX;
    this.aim.y = CY - 250;
    this.hud.objective.textContent = 'BREAK THE WARDEN';
  },

  updateBoss(dt) {
    const boss = this.bossBall;
    const player = this.player;
    if (!boss || boss.dead) return;

    this.stepBalls(dt);
    this.updateBossMovement(dt);
    this.autoFire(player, boss);
    this.updateBossContact(dt);
    this.checkBossShockwaves();
    this.playerBurnAura(dt);

    if (this.ending) return;

    if (boss.hp <= 0) {
      boss.dead = true;
      this.spawnBurst(boss.x, boss.y, '#ffb545', 70, 440);
      this.spawnBurst(boss.x, boss.y, '#ff5d5d', 50, 310);
      this.shake = 24;
      this.flash = 0.8;
      this.flashColor = '255,160,90';
      audio.ringout();
      this.showNotice('WARDEN DOWN', '#ffd38a', 1700);
      this.queueFinish({
        mode: 'boss', win: true, score: Math.round(player.damageDealt || 0),
        time: this.elapsed, playerHp: Math.max(0, player.hp),
        bestScore: Math.round(player.damageDealt || 0), bossHp: 0,
      }, 1.5);
      return;
    }
    if (player.hp <= 0) {
      player.falling = true;
      this.spawnBurst(player.x, player.y, '#ff8f86', 34, 280);
      audio.lose();
      this.showNotice('BALL LOST', '#ff8f86', 1600);
      this.queueFinish({
        mode: 'boss', win: false, score: Math.round(player.damageDealt || 0),
        time: this.elapsed, playerHp: 0, bestScore: Math.round(player.damageDealt || 0),
      }, 1.1);
      return;
    }
    if (this.timeLeft <= 0) {
      this.showNotice('TIME UP', '#ffb0a0', 1400);
      this.queueFinish({
        mode: 'boss', win: false, score: Math.round(player.damageDealt || 0),
        time: this.elapsed, playerHp: Math.max(0, player.hp),
        bestScore: Math.round(player.damageDealt || 0),
      }, 1.0);
    }
  },

  constrainBoss(ball) {
    const R = this.ringR - ball.r * 0.92;
    const dx = ball.x - CX;
    const dy = ball.y - CY;
    const d = Math.hypot(dx, dy);
    if (d > R) {
      const nx = dx / d;
      const ny = dy / d;
      ball.x = CX + nx * R;
      ball.y = CY + ny * R;
      const vn = ball.vx * nx + ball.vy * ny;
      if (vn > 0) {
        ball.vx -= (1 + ball.stats.bounce) * vn * nx;
        ball.vy -= (1 + ball.stats.bounce) * vn * ny;
      }
    }
  },

  updateBossMovement(dt) {
    const boss = this.bossBall;
    const player = this.player;
    const phase2 = boss.hp < boss.maxHp * 0.5;
    boss.hitFlash = Math.max(0, (boss.hitFlash || 0) - dt);
    boss.hitCd = Math.max(0, (boss.hitCd || 0) - dt);
    if (!boss.attack) {
      boss.attackTimer -= dt * (phase2 ? 1.35 : 1);
      const d = dist(boss, player);
      if (d > 230 && this.elapsed > 1) {
        const n = norm(player.x - boss.x, player.y - boss.y);
        boss.vx += n.x * 22;
        boss.vy += n.y * 22;
      }
      boss.vx *= Math.exp(-2.6 * dt);
      boss.vy *= Math.exp(-2.6 * dt);
      boss.x += boss.vx * dt;
      boss.y += boss.vy * dt;
      if (boss.attackTimer <= 0) this.beginBossAttack(phase2);
    } else {
      const atk = boss.attack;
      atk.t -= dt;
      if (atk.type === 'slam') {
        boss.vx *= Math.exp(-4 * dt);
        boss.vy *= Math.exp(-4 * dt);
        boss.x += boss.vx * dt;
        boss.y += boss.vy * dt;
        if (atk.t <= 0) this.executeSlam(atk, phase2);
      } else if (atk.type === 'volley') {
        boss.vx *= Math.exp(-4 * dt);
        boss.vy *= Math.exp(-4 * dt);
        if (atk.t <= 0) this.executeVolley(phase2);
      } else if (atk.type === 'chargeWind') {
        if (atk.t <= 0) {
          const n = norm(player.x - boss.x, player.y - boss.y);
          boss.vx = n.x * (phase2 ? 640 : 540);
          boss.vy = n.y * (phase2 ? 640 : 540);
          boss.attack = { type: 'charge', t: 0.62 };
          audio.dash();
          this.shake = 6;
        }
      } else if (atk.type === 'charge') {
        boss.x += boss.vx * dt;
        boss.y += boss.vy * dt;
        boss.vx *= Math.exp(-2.4 * dt);
        boss.vy *= Math.exp(-2.4 * dt);
        if (Math.random() < 0.5) this.particles.push({
          x: boss.x - rand(-40, 40), y: boss.y - rand(-40, 40),
          vx: rand(-40, 40), vy: rand(-40, 40), life: 0.4, maxLife: 0.5,
          size: rand(5, 12), color: '#ff6b3d', drag: 2, kind: 'dot',
        });
        if (atk.t <= 0) {
          boss.attack = null;
          boss.attackTimer = phase2 ? 1.1 : 1.8;
        }
      }
    }
    this.constrainBoss(boss);
  },

  beginBossAttack(phase2) {
    const boss = this.bossBall;
    const player = this.player;
    const roll = Math.random();
    if (roll < 0.4) {
      boss.attack = { type: 'slam', t: phase2 ? 0.76 : 0.96 };
      this.telegraph = { x: player.x, y: player.y, r: 172, t: phase2 ? 0.76 : 0.96, max: phase2 ? 0.76 : 0.96, type: 'slam' };
      audio.tone({ freq: 120, dur: 0.4, type: 'sawtooth', gain: 0.05, slide: 40 });
    } else if (roll < 0.74) {
      boss.attack = { type: 'volley', t: phase2 ? 0.5 : 0.7 };
      audio.tone({ freq: 300, dur: 0.3, type: 'square', gain: 0.04, slide: 200 });
    } else {
      boss.attack = { type: 'chargeWind', t: phase2 ? 0.46 : 0.66 };
      this.telegraph = { x: player.x, y: player.y, r: 70, t: phase2 ? 0.46 : 0.66, max: phase2 ? 0.46 : 0.66, type: 'charge' };
    }
  },

  executeSlam(atk, phase2) {
    const boss = this.bossBall;
    this.telegraph = null;
    boss.attack = null;
    boss.attackTimer = phase2 ? 1.25 : 1.9;
    this.shockwaves.push({
      x: atk.x, y: atk.y, r: 24, max: 285, speed: 620, hit: false, color: '#ff8a4c', life: 0.8,
    });
    this.spawnBurst(atk.x, atk.y, '#ff8a4c', 30, 300);
    this.shake = 12;
    audio.bump(1.4);
    if (dist(this.player, atk) < 165) this.damagePlayer(18, '#ff8a4c');
  },

  executeVolley(phase2) {
    const boss = this.bossBall;
    boss.attack = null;
    boss.attackTimer = phase2 ? 1.3 : 2.0;
    const count = phase2 ? 14 : 10;
    for (let i = 0; i < count; i += 1) {
      const a = (i / count) * TAU + this.elapsed * 0.6;
      this.projectiles.push({
        x: boss.x + Math.cos(a) * (boss.r + 10),
        y: boss.y + Math.sin(a) * (boss.r + 10),
        vx: Math.cos(a) * 250,
        vy: Math.sin(a) * 250,
        r: 8,
        life: 3.4,
        color: '#ff6b4f',
        owner: boss,
        damage: 10,
        boss: true,
        trail: [],
      });
    }
    this.spawnBurst(boss.x, boss.y, '#ff8a4c', 24, 220);
    audio.tone({ freq: 220, dur: 0.3, type: 'square', gain: 0.05, slide: 120 });
  },

  checkBossShockwaves() {
    const player = this.player;
    for (const w of this.shockwaves) {
      if (w.hit) continue;
      if (w.thin) continue;
      const d = Math.hypot(player.x - w.x, player.y - w.y);
      if (Math.abs(d - w.r) < player.r + 12) {
        w.hit = true;
        this.damagePlayer(15, '#ff8a4c');
        this.knockback(player, w.x, w.y, 230);
      }
    }
  },

  updateBossContact(dt) {
    const boss = this.bossBall;
    const player = this.player;
    if (!boss || boss.dead || player.falling) return;
    const d = dist(player, boss);
    const min = player.r + boss.r;
    if (d >= min || d < 0.001) return;
    const nx = (player.x - boss.x) / d;
    const ny = (player.y - boss.y) / d;
    player.x = boss.x + nx * min;
    player.y = boss.y + ny * min;

    if (player.dashTimer > 0 && boss.hitCd <= 0) {
      const dmg = (player.stats.damage * 2.5 + Math.hypot(player.vx, player.vy) * 0.07) * (boss.dead ? 0 : 1);
      this.damageTarget(boss, dmg, player, '#ffd38a');
      boss.hitCd = 0.34;
      boss.hitFlash = 0.25;
      this.spawnBurst(player.x - nx * 20, player.y - ny * 20, '#ffd38a', 18, 250);
      this.shake = 9;
      audio.hit(1.2);
      this.knockback(player, boss.x, boss.y, 140);
    } else if (player.hitCd <= 0) {
      this.damagePlayer(5, '#ff8f86');
      this.knockback(player, boss.x, boss.y, 260);
      player.hitCd = 0.75;
    }
  },

  damagePlayer(amount, color = '#ff8f86') {
    const player = this.player;
    if (!player || player.falling || player.invuln > 0) return;
    const dmg = amount / Math.max(0.7, player.stats.defense);
    player.hp = Math.max(0, player.hp - dmg);
    player.hitFlash = 0.2;
    player.invuln = 0.32;
    this.addDamage(player.x, player.y - player.r, `-${Math.round(dmg)}`, color, 14);
    this.spawnBurst(player.x, player.y, color, 12, 170);
    this.shake = Math.max(this.shake, 6);
    this.flash = Math.max(this.flash, 0.22);
    this.flashColor = '255,80,80';
    audio.hit(1);
  },

  playerBurnAura(dt) {
    const p = this.player;
    if (p.burn > 0 && this.bossBall && dist(p, this.bossBall) < p.r + this.bossBall.r + 40) {
      p.auraCd = (p.auraCd || 0) - dt;
      if (p.auraCd <= 0) {
        p.auraCd = 0.8;
        this.damageTarget(this.bossBall, 4, p, '#ff8a4c');
        this.spawnBurst(this.bossBall.x, this.bossBall.y, '#ff8a4c', 8, 100);
      }
    }
  },

  /* ══ SHOWCASE ══════════════════════════════════════════════ */
  initShowcase() {
    this.viewW = 920;
    this.viewH = 790;
    this.resize();
    this.countdown = 2.1;
    this.timeLimit = 0;
    this.hud.mode.textContent = 'SHOWCASE · LIVE LOBBY';
    this.hud.objective.textContent = 'WIN OVER THE CROWD';

    this.player = this.makeBall(this.save.config, this.build, {
      x: CX, y: CY + 150, isPlayer: true, name: this.save.config.name, radius: 58,
    });
    this.player.hp = this.player.maxHp = 100;
    this.balls = [this.player];
    this.bossBall = null;

    const picks = [RIVALS[1], RIVALS[3], RIVALS[0], RIVALS[2]];
    this.showcaseRivals = picks.map((rival, i) => {
      const angle = -Math.PI * 0.88 + (i / (picks.length - 1)) * Math.PI * 0.76;
      return {
        config: rival.config,
        name: rival.name,
        x: CX + Math.cos(angle) * 275,
        y: CY - 120 + Math.sin(angle) * 175,
        r: 30 + (i % 3) * 5,
        layouts: buildLayouts(rival.config),
        score: Math.round(rand(62, 92) + Math.min(14, this.save.stats.wins * 1.2)),
        phase: rand(0, TAU),
      };
    });

    this.showcase = this.scoreShowcase();
    const all = [...this.showcaseRivals.map((r) => ({ name: r.name, score: r.score })), { name: this.player.name, score: this.showcase.score }];
    all.sort((a, b) => b.score - a.score);
    this.showcase.rank = all.findIndex((x) => x.name === this.player.name) + 1;
    this.showcase.rivalScores = this.showcaseRivals.map((r) => r.score);
    this.showcase.rankList = all;
    this.showcase.t = 0;
    this.showcase.chat = 0;
    this.showcase.chatTimer = 0;
    this.aim.x = CX;
    this.aim.y = CY - 200;
  },

  scoreShowcase() {
    const c = this.save.config;
    const phys = this.build.phys;
    const packs = new Set(c.gadgets.map((id) => GADGET_MAP[id]?.pack).filter(Boolean));
    const tags = phys.gadgetTags || new Set();
    const glow = c.glow || 0;
    const creativity = clamp(
      27 + (c.pattern !== 'solid' ? 12 : 0) + (c.texture !== 'matte' ? 8 : 0) + glow * 18
      + c.gadgets.length * 3.1 + packs.size * 5 + (c.mirror ? 6 : 0) + (c.rotation ? 4 : 0)
      + (c.accent !== c.color ? 4 : 0),
      10, 100,
    );
    const menace = clamp(
      8 + phys.damage * 2.1 + (tags.has('contact') ? 13 : 0) + (tags.has('projectile') ? 9 : 0)
      + (c.mood === 'angry' ? 10 : 0) + (phys.maxMass ? 0 : 0),
      5, 100,
    );
    const charm = clamp(
      30 + glow * 22 + (['star', 'wide', 'sleepy'].includes(c.eyes) ? 7 : 0)
      + (['grin', 'smile', 'ooo'].includes(c.mouth) ? 8 : 0)
      + (['giddy', 'calm'].includes(c.mood) ? 12 : 0)
      + (c.gadgets.includes('weird_party_hat') ? 15 : 0)
      + (c.name.length <= 5 ? 4 : 0),
      5, 100,
    );
    const leftover = 1 - (phys.massCost / phys.maxMass) * 0.7;
    const synergy = clamp(
      22 + leftover * 42 + packs.size * 6 + (tags.has('luck') ? 6 : 0)
      + (['fire', 'electric'].includes(c.core) ? 6 : 0) + (c.mirror ? 5 : 0),
      5, 100,
    );
    const base = creativity * 0.28 + menace * 0.24 + charm * 0.24 + synergy * 0.24;
    const score = Math.round(clamp(base + rand(-2, 4) + (phys.luck - 1) * 6, 15, 99));
    return {
      breakdown: {
        creativity: Math.round(creativity),
        menace: Math.round(menace),
        charm: Math.round(charm),
        synergy: Math.round(synergy),
      },
      score,
      t: 0,
      chat: 0,
      chatTimer: 0,
    };
  },

  updateShowcase(dt) {
    const sc = this.showcase;
    sc.t += dt;
    sc.chatTimer -= dt;
    if (sc.chatTimer <= 0) {
      sc.chatTimer = 1.55;
      sc.chat = (sc.chat + 1) % CHAT.length;
    }
    this.player.x = CX;
    this.player.y = CY + 150 + Math.sin(sc.t * 2.2) * 9;
    this.player.facing = Math.sin(sc.t * 0.8) * 0.3;
    for (const r of this.showcaseRivals) {
      r.y += Math.sin(sc.t * 1.7 + r.phase) * 0.22;
      r.x += Math.cos(sc.t * 1.2 + r.phase) * 0.12;
    }
    if (sc.t > 1.6 && !this.showcaseCategoryShown) {
      this.showcaseCategoryShown = true;
      this.showNotice('CREATIVITY · MENACE · CHARM · SYNERGY', '#ffb545', 1400);
    }
    if (sc.t > 4.9 && !this.ending) {
      const rank = sc.rank;
      this.showNotice(rank === 1 ? 'CROWD FAVOURITE!' : `RANK #${rank} OF 5`, rank === 1 ? '#ffe08a' : '#ff9ed2', 1300);
      this.queueFinish({
        mode: 'showcase',
        win: rank <= 2,
        rank,
        score: sc.score,
        breakdown: sc.breakdown,
        rivalScores: sc.rivalScores,
        progress: 0,
        playerHp: 100,
        bestScore: sc.score,
      }, 1.2);
    }
  },

  /* ══ drawing dispatch ══════════════════════════════════════ */
  drawArena(t) {
    if (this.mode === 'sumo') drawSumoArena(this, t);
    else if (this.mode === 'race') drawRaceArena(this, t);
    else if (this.mode === 'boss') drawBossArena(this, t);
    else drawShowcaseArena(this, t);
  },

  drawUnder(t) {
    const ctx = this.ctx;
    if (this.mode === 'boss') {
      if (this.telegraph) {
        const k = 1 - this.telegraph.t / this.telegraph.max;
        ctx.save();
        ctx.translate(this.telegraph.x, this.telegraph.y);
        ctx.fillStyle = 'rgba(255,80,60,0.12)';
        ctx.strokeStyle = 'rgba(255,93,93,0.8)';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, this.telegraph.r, 0, TAU);
        ctx.fill();
        ctx.stroke();
        ctx.strokeStyle = 'rgba(255,200,150,0.9)';
        ctx.lineWidth = 5;
        ctx.beginPath();
        ctx.arc(0, 0, this.telegraph.r * 0.92, -Math.PI / 2, -Math.PI / 2 + TAU * k);
        ctx.stroke();
        ctx.setLineDash([9, 12]);
        ctx.strokeStyle = 'rgba(255,93,93,0.35)';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, this.telegraph.r * 1.16, 0, TAU);
        ctx.stroke();
        ctx.restore();
      }
      if (this.bossBall && !this.bossBall.dead && this.bossBall.attack?.type === 'chargeWind') {
        const b = this.bossBall;
        const n = norm(this.player.x - b.x, this.player.y - b.y);
        ctx.strokeStyle = 'rgba(255,93,93,0.4)';
        ctx.lineWidth = 4;
        ctx.setLineDash([12, 14]);
        ctx.beginPath();
        ctx.moveTo(b.x, b.y);
        ctx.lineTo(b.x + n.x * 560, b.y + n.y * 560);
        ctx.stroke();
        ctx.setLineDash([]);
      }
    }
    if (this.mode === 'race') {
      // next-gate arrow above the player
      const p = this.player;
      const theta = ellipseTheta(p.x, p.y);
      const ahead = ellipsePoint(RACE.midA, RACE.midB, theta + 0.7);
      const n = norm(ahead.x - p.x, ahead.y - p.y);
      ctx.save();
      ctx.globalAlpha = 0.25;
      ctx.strokeStyle = '#5ce1c6';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 7]);
      ctx.beginPath();
      ctx.moveTo(p.x + n.x * p.r, p.y + n.y * p.r);
      ctx.lineTo(p.x + n.x * (p.r + 38), p.y + n.y * (p.r + 38));
      ctx.stroke();
      ctx.restore();
    }
  },

  drawOver(t) {
    if (this.mode === 'showcase') this.drawShowcaseUI(t);
    if (this.mode === 'showcase') return;

    const ctx = this.ctx;
    const p = this.player;
    if (!p || p.falling) return;

    // dash target reticle
    if (this.aim.active && this.elapsed - this.aim.t < 4) {
      const n = norm(this.aim.x - p.x, this.aim.y - p.y);
      if (n.d > 30) {
        ctx.save();
        ctx.globalAlpha = 0.22;
        ctx.strokeStyle = p.config.accent;
        ctx.lineWidth = 2;
        ctx.setLineDash([7, 11]);
        ctx.beginPath();
        ctx.moveTo(p.x + n.x * (p.r + 14), p.y + n.y * (p.r + 14));
        ctx.lineTo(p.x + n.x * 120, p.y + n.y * 120);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.beginPath();
        ctx.arc(p.x + n.x * 126, p.y + n.y * 126, 5, 0, TAU);
        ctx.stroke();
        ctx.restore();
      }
    }

    // sumo danger ring
    if (this.mode === 'sumo') {
      const d = Math.hypot(p.x - CX, p.y - CY);
      if (d > this.ringR - 70) {
        const n = norm(CX - p.x, CY - p.y);
        ctx.save();
        ctx.globalAlpha = 0.5 + Math.sin(t * 8) * 0.3;
        ctx.fillStyle = '#ff5d5d';
        ctx.beginPath();
        ctx.arc(p.x + n.x * (p.r + 30), p.y + n.y * (p.r + 30), 6, 0, TAU);
        ctx.fill();
        ctx.restore();
      }
    }
  },

  drawShowcaseUI(t) {
    const ctx = this.ctx;
    const sc = this.showcase;
    if (!sc) return;
    const labels = [
      ['CREATIVITY', sc.breakdown.creativity, '#ffb545'],
      ['MENACE', sc.breakdown.menace, '#ff6b5b'],
      ['CHARM', sc.breakdown.charm, '#ff9ed2'],
      ['SYNERGY', sc.breakdown.synergy, '#67e8f9'],
    ];
    const reveal = clamp((sc.t - 1.4) / 2.4, 0, 1);

    // category bars top-left
    ctx.save();
    ctx.translate(24, 84);
    ctx.fillStyle = 'rgba(8,11,16,0.55)';
    ctx.strokeStyle = 'rgba(247,242,232,0.1)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(0, 0, 256, 148, 12);
    ctx.fill();
    ctx.stroke();
    ctx.font = "700 8px 'JetBrains Mono', monospace";
    ctx.fillStyle = 'rgba(247,242,232,0.45)';
    ctx.fillText('CROWD JUDGEMENT', 14, 20);
    labels.forEach(([label, value, color], i) => {
      const y = 42 + i * 25;
      ctx.fillStyle = 'rgba(247,242,232,0.55)';
      ctx.font = "700 8px 'JetBrains Mono', monospace";
      ctx.fillText(label, 14, y + 3);
      ctx.fillStyle = 'rgba(255,255,255,0.08)';
      ctx.fillRect(94, y - 3, 112, 5);
      ctx.fillStyle = color;
      ctx.fillRect(94, y - 3, 112 * (value / 100) * reveal, 5);
      ctx.textAlign = 'right';
      ctx.fillStyle = '#f7f2e8';
      ctx.fillText(String(Math.round(value * reveal)), 242, y + 3);
      ctx.textAlign = 'left';
    });
    ctx.restore();

    // big score top-right
    ctx.save();
    ctx.textAlign = 'right';
    ctx.font = "800 54px 'Bricolage Grotesque', sans-serif";
    ctx.fillStyle = `rgba(255,181,69,${0.25 + reveal * 0.75})`;
    ctx.fillText(String(Math.round(sc.score * reveal)), this.cw / this.scale - 30, 128);
    ctx.font = "700 8px 'JetBrains Mono', monospace";
    ctx.fillStyle = 'rgba(247,242,232,0.45)';
    ctx.fillText('CROWD SCORE', this.cw / this.scale - 30, 146);
    ctx.restore();

    // chat bubbles
    if (sc.t > 0.6) {
      const [name, text] = CHAT[sc.chat];
      ctx.save();
      ctx.globalAlpha = clamp((sc.t - 0.6) * 3, 0, 1);
      const x = 24;
      const y = this.ch / this.scale - 118;
      ctx.font = "500 11px 'Space Grotesk', sans-serif";
      const w = Math.min(360, ctx.measureText(text).width + 40);
      ctx.fillStyle = 'rgba(8,11,16,0.7)';
      ctx.strokeStyle = 'rgba(247,242,232,0.11)';
      ctx.beginPath();
      ctx.roundRect(x, y, w, 48, 12);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = '#ffb545';
      ctx.font = "700 8px 'JetBrains Mono', monospace";
      ctx.fillText(name, x + 14, y + 18);
      ctx.fillStyle = 'rgba(247,242,232,0.8)';
      ctx.font = "500 11px 'Space Grotesk', sans-serif";
      ctx.fillText(text, x + 14, y + 34);
      ctx.restore();
    }
  },
};

/* Arena floor / scenery painting — all procedural canvas. */

import { alpha, lighten, darken, drawBlob } from './blob.js';
import { CX, CY, TAU, CROWD, RACE, ellipsePoint, ellipseTheta } from './constants.js';

function crowd(ctx, cx, cy, rx, ry, t, opacity = 0.6, scale = 1) {
  for (let i = 0; i < CROWD.length; i += 1) {
    const c = CROWD[i];
    const bob = Math.sin(t * 1.4 + c.phase) * 2.5;
    const x = cx + Math.cos(c.angle) * (rx + c.r * 150 * scale);
    const y = cy + Math.sin(c.angle) * (ry + c.r * 110 * scale) + bob;
    ctx.globalAlpha = opacity * (0.35 + c.r * 0.4);
    ctx.fillStyle = c.color;
    ctx.beginPath();
    ctx.arc(x, y, c.size * scale, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function lamp(ctx, x, y, color, t, size = 1) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, 52 * size);
  g.addColorStop(0, alpha(color, 0.34));
  g.addColorStop(0.4, alpha(color, 0.1));
  g.addColorStop(1, alpha(color, 0));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, 52 * size, 0, TAU);
  ctx.fill();
  ctx.fillStyle = alpha(color, 0.9);
  ctx.beginPath();
  ctx.arc(x, y, 3.3 * size + Math.sin(t * 4 + x) * 0.6, 0, TAU);
  ctx.fill();
}

function dashEllipse(ctx, a, b, color, width = 1, dash = [6, 9]) {
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.ellipse(CX, CY, a, b, 0, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

/* ══ SUMO ═══════════════════════════════════════════════════ */
export function drawSumoArena(game, t) {
  const ctx = game.ctx;
  const R = game.ringR;

  // abyss light
  const halo = ctx.createRadialGradient(CX, CY, R * 0.6, CX, CY, R * 2.2);
  halo.addColorStop(0, 'rgba(255,181,69,0.07)');
  halo.addColorStop(0.5, 'rgba(40,30,20,0.16)');
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(CX - 650, CY - 650, 1300, 1300);

  crowd(ctx, CX, CY, R + 66, R + 40, t, 0.42, 0.9);

  // supports and lanterns
  for (let i = 0; i < 8; i += 1) {
    const a = (i / 8) * TAU + 0.24;
    const x = CX + Math.cos(a) * (R + 105);
    const y = CY + Math.sin(a) * (R + 105);
    lamp(ctx, x, y, i % 2 ? '#ff8a4c' : '#ffd071', t, 0.85 + (i % 3) * 0.12);
  }

  // outer platform edge shadow
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.7)';
  ctx.shadowBlur = 45;
  ctx.fillStyle = '#0c1015';
  ctx.beginPath();
  ctx.arc(CX, CY + 9, R + 15, 0, TAU);
  ctx.fill();
  ctx.restore();

  // rim rings
  ctx.strokeStyle = 'rgba(255,181,69,0.16)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(CX, CY, R + 10, 0, TAU);
  ctx.stroke();

  // floor
  ctx.save();
  ctx.beginPath();
  ctx.arc(CX, CY, R, 0, TAU);
  ctx.clip();
  const floor = ctx.createRadialGradient(CX - R * 0.2, CY - R * 0.25, R * 0.06, CX, CY, R * 1.08);
  floor.addColorStop(0, '#343c47');
  floor.addColorStop(0.42, '#252c35');
  floor.addColorStop(0.8, '#171d25');
  floor.addColorStop(1, '#0e1319');
  ctx.fillStyle = floor;
  ctx.fillRect(CX - R, CY - R, R * 2, R * 2);

  // grid
  ctx.strokeStyle = 'rgba(255,255,255,0.032)';
  ctx.lineWidth = 1;
  const grid = 42;
  for (let x = CX - R; x < CX + R; x += grid) {
    ctx.beginPath();
    ctx.moveTo(x, CY - R);
    ctx.lineTo(x, CY + R);
    ctx.stroke();
  }
  for (let y = CY - R; y < CY + R; y += grid) {
    ctx.beginPath();
    ctx.moveTo(CX - R, y);
    ctx.lineTo(CX + R, y);
    ctx.stroke();
  }

  // painted rings
  const rings = [0.32, 0.56, 0.8, 0.93];
  rings.forEach((k, i) => {
    ctx.strokeStyle = i === 3 ? 'rgba(255,181,69,0.25)' : `rgba(247,242,232,${0.06 - i * 0.008})`;
    ctx.lineWidth = i === 3 ? 3 : 1.4;
    ctx.setLineDash(i === 1 ? [10, 14] : []);
    ctx.beginPath();
    ctx.arc(CX, CY, R * k, 0, TAU);
    ctx.stroke();
  });
  ctx.setLineDash([]);

  // swept arc
  ctx.strokeStyle = 'rgba(255,181,69,0.14)';
  ctx.lineWidth = 14;
  ctx.beginPath();
  ctx.arc(CX, CY, R * 0.705, t * 0.28, t * 0.28 + 0.5);
  ctx.stroke();

  // centre emblem
  ctx.save();
  ctx.globalAlpha = 0.5;
  ctx.strokeStyle = 'rgba(255,181,69,0.5)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(CX, CY, 36, 0, TAU);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(CX, CY, 27, 0, TAU);
  ctx.stroke();
  ctx.fillStyle = 'rgba(255,181,69,0.85)';
  ctx.font = "800 20px 'Bricolage Grotesque', sans-serif";
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('07', CX, CY + 1);
  ctx.font = "700 5px 'JetBrains Mono', monospace";
  ctx.fillStyle = 'rgba(247,242,232,0.4)';
  ctx.fillText('RING', CX, CY + 17);
  ctx.restore();

  // scuffs
  ctx.strokeStyle = 'rgba(0,0,0,0.24)';
  for (let i = 0; i < 7; i += 1) {
    const a = i * 1.7 + 0.4;
    const r1 = R * (0.3 + (i % 4) * 0.14);
    ctx.beginPath();
    ctx.arc(CX + Math.cos(a) * 20, CY + Math.sin(a) * 20, r1, a, a + 0.5);
    ctx.stroke();
  }
  ctx.restore();

  // hazard rim
  const segments = 44;
  for (let i = 0; i < segments; i += 1) {
    const a0 = (i / segments) * TAU;
    const a1 = ((i + 1) / segments) * TAU;
    ctx.strokeStyle = i % 2 === 0 ? '#ffb545' : '#2b3038';
    ctx.lineWidth = 12;
    ctx.beginPath();
    ctx.arc(CX, CY, R + 3, a0 + 0.008, a1 - 0.008);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(255,181,69,0.25)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(CX, CY, R + 10.5, 0, TAU);
  ctx.stroke();

  // energy pulses on rim when tight
  if (R < 290) {
    ctx.strokeStyle = `rgba(255,93,93,${0.25 + Math.sin(t * 6) * 0.12})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(CX, CY, R - 6, 0, TAU);
    ctx.stroke();
  }

  // ring-out pit glow outside
  const pit = ctx.createRadialGradient(CX, CY, R + 12, CX, CY, R + 90);
  pit.addColorStop(0, 'rgba(255,93,93,0.07)');
  pit.addColorStop(1, 'rgba(255,93,93,0)');
  ctx.fillStyle = pit;
  ctx.beginPath();
  ctx.arc(CX, CY, R + 90, 0, TAU);
  ctx.fill();

  // corner labels
  ctx.save();
  ctx.font = "700 8px 'JetBrains Mono', monospace";
  ctx.fillStyle = 'rgba(247,242,232,0.22)';
  ctx.textAlign = 'left';
  ctx.fillText('SUMO // RING 07', CX - R + 6, CY + R + 34);
  ctx.textAlign = 'right';
  ctx.fillText('NO WALLS · NO MERCY', CX + R - 6, CY + R + 34);
  ctx.restore();
}

/* ══ RACE ═══════════════════════════════════════════════════ */
function ellipticalArc(ctx, a, b, from, to) {
  ctx.beginPath();
  const steps = Math.max(5, Math.ceil(Math.abs(to - from) * 40));
  for (let i = 0; i <= steps; i += 1) {
    const th = from + ((to - from) * i) / steps;
    const x = CX + Math.cos(th) * a;
    const y = CY + Math.sin(th) * b;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
}

export function drawRaceArena(game, t) {
  const ctx = game.ctx;
  crowd(ctx, CX, CY, RACE.outerA + 58, RACE.outerB + 45, t, 0.34, 0.8);

  // floodlights
  lamp(ctx, CX - RACE.outerA - 60, CY - 180, '#ffb545', t, 1.1);
  lamp(ctx, CX + RACE.outerA + 60, CY - 180, '#67e8f9', t, 1.1);
  lamp(ctx, CX - RACE.outerA - 60, CY + 190, '#ff9ed2', t, 1.1);
  lamp(ctx, CX + RACE.outerA + 60, CY + 190, '#a7f36b', t, 1.1);

  // track base
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 50;
  ctx.fillStyle = '#12161d';
  ctx.beginPath();
  ctx.ellipse(CX, CY, RACE.outerA + 16, RACE.outerB + 16, 0, 0, TAU);
  ctx.fill();
  ctx.restore();

  const outer = ctx.createRadialGradient(CX, CY, RACE.innerB * 0.5, CX, CY, RACE.outerA);
  outer.addColorStop(0, '#262d37');
  outer.addColorStop(0.55, '#1d242d');
  outer.addColorStop(1, '#151b22');
  ctx.fillStyle = outer;
  ctx.beginPath();
  ctx.ellipse(CX, CY, RACE.outerA, RACE.outerB, 0, 0, TAU);
  ctx.fill();

  // asphalt grain
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(CX, CY, RACE.outerA, RACE.outerB, 0, 0, TAU);
  ctx.ellipse(CX, CY, RACE.innerA, RACE.innerB, 0, 0, TAU);
  ctx.clip('evenodd');
  ctx.fillStyle = 'rgba(255,255,255,0.02)';
  for (let i = 0; i < 90; i += 1) {
    const a = (i * 2.399) % TAU;
    const rr = 0.3 + ((i * 37) % 70) / 100;
    const x = CX + Math.cos(a) * RACE.outerA * rr;
    const y = CY + Math.sin(a) * RACE.outerB * rr;
    ctx.fillRect(x, y, 2.4, 1.2);
  }
  ctx.restore();

  // outer & inner tunnel walls
  ctx.strokeStyle = '#39424d';
  ctx.lineWidth = 9;
  ctx.beginPath();
  ctx.ellipse(CX, CY, RACE.outerA + 4, RACE.outerB + 4, 0, 0, TAU);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.ellipse(CX, CY, RACE.outerA + 9, RACE.outerB + 9, 0, 0, TAU);
  ctx.stroke();

  ctx.strokeStyle = '#2b323c';
  ctx.lineWidth = 8;
  ctx.beginPath();
  ctx.ellipse(CX, CY, RACE.innerA - 3, RACE.innerB - 3, 0, 0, TAU);
  ctx.stroke();

  // kerbs
  const kerbCount = 64;
  for (let i = 0; i < kerbCount; i += 1) {
    const color = i % 2 === 0 ? '#f7f2e8' : '#ff5d5d';
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.5;
    ctx.lineWidth = 5;
    const a0 = (i / kerbCount) * TAU + 0.006;
    const a1 = ((i + 1) / kerbCount) * TAU - 0.006;
    ellipticalArc(ctx, RACE.outerA - 3, RACE.outerB - 3, a0, a1);
    ctx.stroke();
    ctx.strokeStyle = i % 2 === 0 ? '#ffb545' : '#242a32';
    ellipticalArc(ctx, RACE.innerA + 4, RACE.innerB + 4, a0, a1);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // lane markings
  dashEllipse(ctx, RACE.midA, RACE.midB, 'rgba(247,242,232,0.18)', 1.5, [14, 18]);
  dashEllipse(ctx, RACE.midA - 44, RACE.midB - 25, 'rgba(247,242,232,0.035)', 1, [8, 12]);
  dashEllipse(ctx, RACE.midA + 44, RACE.midB + 25, 'rgba(247,242,232,0.035)', 1, [8, 12]);

  // direction chevrons
  for (let i = 0; i < 8; i += 1) {
    const th = (i / 8) * TAU + 0.16;
    const p = ellipsePoint(RACE.midA, RACE.midB, th);
    const tangent = Math.atan2(Math.cos(th) * RACE.midB, -Math.sin(th) * RACE.midA);
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(tangent);
    ctx.strokeStyle = 'rgba(255,181,69,0.22)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-7, -6);
    ctx.lineTo(0, 0);
    ctx.lineTo(-7, 6);
    ctx.stroke();
    ctx.restore();
  }

  // gates
  const gates = [0, Math.PI / 2, Math.PI, (Math.PI * 3) / 2];
  gates.slice(0, 3).forEach((th, i) => {
    const inner = ellipsePoint(RACE.innerA, RACE.innerB, th);
    const outerP = ellipsePoint(RACE.outerA, RACE.outerB, th);
    const color = ['#5ce1c6', '#67e8f9', '#c084fc'][i];
    ctx.save();
    ctx.strokeStyle = alpha(color, 0.35);
    ctx.shadowColor = color;
    ctx.shadowBlur = 18;
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(inner.x, inner.y);
    ctx.lineTo(outerP.x, outerP.y);
    ctx.stroke();
    ctx.restore();
  });

  // start/finish line at the top
  ctx.save();
  const yTop = CY - RACE.outerB;
  const yBot = CY - RACE.innerB;
  const cols = 2;
  const rows = 10;
  const w = 26;
  for (let r = 0; r < rows; r += 1) {
    for (let c = 0; c < cols; c += 1) {
      ctx.fillStyle = (r + c) % 2 === 0 ? '#f7f2e8' : '#1a1f26';
      ctx.fillRect(CX - w / 2 + (c * w) / cols, yTop + (r * (yBot - yTop)) / rows, w / cols, (yBot - yTop) / rows);
    }
  }
  ctx.restore();

  // inner island
  const island = ctx.createRadialGradient(CX, CY, 20, CX, CY, RACE.innerA);
  island.addColorStop(0, '#1b222b');
  island.addColorStop(1, '#0b0f14');
  ctx.fillStyle = island;
  ctx.beginPath();
  ctx.ellipse(CX, CY, RACE.innerA - 14, RACE.innerB - 14, 0, 0, TAU);
  ctx.fill();
  ctx.save();
  ctx.globalAlpha = 0.5;
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(247,242,232,0.2)';
  ctx.font = "800 34px 'Bricolage Grotesque', sans-serif";
  ctx.fillText('OVAL', CX, CY - 2);
  ctx.font = "700 8px 'JetBrains Mono', monospace";
  ctx.fillStyle = 'rgba(255,181,69,0.4)';
  ctx.fillText('TWO LAPS · NO BRAKES', CX, CY + 18);
  ctx.restore();

  // obstacles
  for (const ob of game.obstacles || []) {
    ctx.save();
    ctx.translate(ob.x, ob.y);
    ctx.rotate(ob.angle + t * 0.05);
    ctx.fillStyle = 'rgba(0,0,0,0.45)';
    ctx.beginPath();
    ctx.ellipse(4, 7, ob.r * 1.1, ob.r * 0.55, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#c98a5b';
    ctx.strokeStyle = '#6d452b';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.roundRect(-ob.r, -ob.r, ob.r * 2, ob.r * 2, 4);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = 'rgba(20,24,28,0.7)';
    ctx.fillRect(-ob.r, -ob.r * 0.34, ob.r * 2, ob.r * 0.68);
    ctx.strokeStyle = '#ffb545';
    ctx.lineWidth = 3;
    ctx.setLineDash([5, 5]);
    ctx.strokeRect(-ob.r + 4, -ob.r + 4, ob.r * 2 - 8, ob.r * 2 - 8);
    ctx.restore();
  }

  // boost pads
  for (const pad of game.boostPads || []) {
    ctx.save();
    ctx.translate(pad.x, pad.y);
    ctx.rotate(Math.atan2(Math.cos(pad.angle) * RACE.midB, -Math.sin(pad.angle) * RACE.midA));
    ctx.globalAlpha = 0.55 + Math.sin(t * 4 + pad.angle) * 0.15;
    ctx.fillStyle = 'rgba(92,225,198,0.15)';
    ctx.strokeStyle = '#5ce1c6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.roundRect(-24, -17, 48, 34, 6);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#5ce1c6';
    for (let i = -1; i <= 1; i += 1) {
      ctx.beginPath();
      ctx.moveTo(i * 12 - 5, -10);
      ctx.lineTo(i * 12 + 4, 0);
      ctx.lineTo(i * 12 - 5, 10);
      ctx.stroke();
    }
    ctx.restore();
  }

  // ambient dust
  ctx.fillStyle = 'rgba(255,240,210,0.2)';
  for (let i = 0; i < 18; i += 1) {
    const a = i * 1.7 + t * 0.04;
    const p = ellipsePoint(RACE.midA + Math.sin(i) * 30, RACE.midB + Math.cos(i) * 30, a);
    ctx.globalAlpha = 0.08 + (i % 5) * 0.03;
    ctx.beginPath();
    ctx.arc(p.x, p.y, 1.5 + (i % 3), 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

/* ══ BOSS ═══════════════════════════════════════════════════ */
export function drawBossArena(game, t) {
  const ctx = game.ctx;
  const R = game.ringR;

  // heat glow
  const halo = ctx.createRadialGradient(CX, CY, R * 0.5, CX, CY, R * 1.9);
  halo.addColorStop(0, 'rgba(255,93,93,0.06)');
  halo.addColorStop(0.55, 'rgba(90,25,20,0.14)');
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(CX - 650, CY - 650, 1300, 1300);

  crowd(ctx, CX, CY, R + 54, R + 36, t, 0.22, 0.85);

  // lava fissures outside
  ctx.save();
  for (let i = 0; i < 7; i += 1) {
    const a = i * 0.93 + 0.2;
    ctx.strokeStyle = `rgba(255,90,45,${0.12 + Math.sin(t * 2 + i) * 0.05})`;
    ctx.lineWidth = 3 + (i % 3);
    ctx.beginPath();
    ctx.moveTo(CX + Math.cos(a) * (R + 24), CY + Math.sin(a) * (R + 24));
    for (let k = 0; k < 4; k += 1) {
      const r = R + 24 + k * 32;
      const aa = a + Math.sin(k * 1.7 + i) * 0.16;
      ctx.lineTo(CX + Math.cos(aa) * r, CY + Math.sin(aa) * r);
    }
    ctx.stroke();
  }
  ctx.restore();

  // platform shadow
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 60;
  ctx.fillStyle = '#0a0c10';
  ctx.beginPath();
  ctx.arc(CX, CY + 10, R + 18, 0, TAU);
  ctx.fill();
  ctx.restore();

  // platform
  ctx.save();
  ctx.beginPath();
  ctx.arc(CX, CY, R, 0, TAU);
  ctx.clip();
  const floor = ctx.createRadialGradient(CX - 80, CY - 90, 20, CX, CY, R * 1.1);
  floor.addColorStop(0, '#332528');
  floor.addColorStop(0.4, '#241a1d');
  floor.addColorStop(0.8, '#151013');
  floor.addColorStop(1, '#0b080a');
  ctx.fillStyle = floor;
  ctx.fillRect(CX - R, CY - R, R * 2, R * 2);

  // hex / tile pattern
  ctx.strokeStyle = 'rgba(255,120,90,0.07)';
  ctx.lineWidth = 1.2;
  const sz = 58;
  for (let x = CX - R; x < CX + R; x += sz) {
    for (let y = CY - R; y < CY + R; y += sz) {
      ctx.beginPath();
      ctx.moveTo(x + sz / 2, y);
      ctx.lineTo(x + sz, y + sz / 4);
      ctx.lineTo(x + sz, y + (sz * 3) / 4);
      ctx.lineTo(x + sz / 2, y + sz);
      ctx.lineTo(x, y + (sz * 3) / 4);
      ctx.lineTo(x, y + sz / 4);
      ctx.closePath();
      ctx.stroke();
    }
  }

  // cracks
  if (!game._bossCracks) {
    game._bossCracks = Array.from({ length: 9 }, (_, i) => {
      const a = i * 1.4 + Math.random();
      const pts = [{ x: CX + Math.cos(a) * 20, y: CY + Math.sin(a) * 20 }];
      for (let k = 1; k < 5; k += 1) {
        const r = (k / 5) * R * 0.95;
        const aa = a + (Math.random() - 0.5) * 0.3;
        pts.push({ x: CX + Math.cos(aa) * r, y: CY + Math.sin(aa) * r });
      }
      return pts;
    });
  }
  ctx.strokeStyle = `rgba(255,110,60,${0.12 + Math.sin(t * 3) * 0.04})`;
  ctx.lineWidth = 2;
  for (const pts of game._bossCracks) {
    ctx.beginPath();
    pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
    ctx.stroke();
  }

  // centre warning circle
  ctx.strokeStyle = 'rgba(255,93,93,0.14)';
  ctx.lineWidth = 2;
  ctx.setLineDash([16, 20]);
  ctx.beginPath();
  ctx.arc(CX, CY, 170, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);

  // emblem
  ctx.globalAlpha = 0.35;
  ctx.strokeStyle = '#ff6b3d';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(CX, CY, 62, 0, TAU);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(CX - 44, CY);
  ctx.lineTo(CX + 44, CY);
  ctx.moveTo(CX, CY - 44);
  ctx.lineTo(CX, CY + 44);
  ctx.stroke();
  ctx.font = "800 13px 'Bricolage Grotesque', sans-serif";
  ctx.fillStyle = 'rgba(255,120,90,0.7)';
  ctx.textAlign = 'center';
  ctx.fillText('CORE', CX, CY + 4);
  ctx.globalAlpha = 1;
  ctx.restore();

  // rim
  for (let i = 0; i < 36; i += 1) {
    const a0 = (i / 36) * TAU;
    const a1 = ((i + 1) / 36) * TAU;
    ctx.strokeStyle = i % 3 === 0 ? '#ff6b3d' : '#2a1a1c';
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.arc(CX, CY, R + 4, a0 + 0.006, a1 - 0.006);
    ctx.stroke();
  }
  ctx.strokeStyle = `rgba(255,93,93,${0.2 + Math.sin(t * 4) * 0.08})`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(CX, CY, R + 11, 0, TAU);
  ctx.stroke();

  // corner labels
  ctx.save();
  ctx.font = "700 8px 'JetBrains Mono', monospace";
  ctx.fillStyle = 'rgba(255,140,120,0.3)';
  ctx.fillText('WARDEN CONTAINMENT // BAY 03', CX - R + 6, CY + R + 36);
  ctx.textAlign = 'right';
  ctx.fillText('DO NOT FEED', CX + R - 6, CY + R + 36);
  ctx.restore();
}

/* ══ SHOWCASE ═══════════════════════════════════════════════ */
export function drawShowcaseArena(game, t) {
  const ctx = game.ctx;

  // ballroom darkness
  ctx.fillStyle = '#07090d';
  ctx.fillRect(CX - 900, CY - 700, 1800, 1400);

  // audience
  crowd(ctx, CX, CY + 20, 330, 270, t, 0.34, 0.9);

  // spotlights
  const beams = [
    { x: CX - 330, color: 'rgba(255,181,69,0.07)' },
    { x: CX + 330, color: 'rgba(103,232,249,0.055)' },
    { x: CX, color: 'rgba(255,158,210,0.05)' },
  ];
  for (const b of beams) {
    const g = ctx.createLinearGradient(b.x, -260, CX, CY + 120);
    g.addColorStop(0, b.color);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(b.x - 26, -260);
    ctx.lineTo(b.x + 26, -260);
    ctx.lineTo(CX + 130, CY + 110);
    ctx.lineTo(CX - 130, CY + 110);
    ctx.closePath();
    ctx.fill();
  }

  // stage shadow
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 60;
  ctx.fillStyle = '#0b0e13';
  ctx.beginPath();
  ctx.ellipse(CX, CY + 60, 380, 300, 0, 0, TAU);
  ctx.fill();
  ctx.restore();

  // stage disc
  const stage = ctx.createRadialGradient(CX, CY + 20, 30, CX, CY + 40, 430);
  stage.addColorStop(0, '#242c36');
  stage.addColorStop(0.55, '#161c24');
  stage.addColorStop(1, '#0a0d12');
  ctx.fillStyle = stage;
  ctx.beginPath();
  ctx.ellipse(CX, CY + 50, 375, 295, 0, 0, TAU);
  ctx.fill();

  ctx.strokeStyle = 'rgba(255,181,69,0.14)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.ellipse(CX, CY + 50, 375, 295, 0, 0, TAU);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(247,242,232,0.05)';
  ctx.setLineDash([10, 16]);
  ctx.beginPath();
  ctx.ellipse(CX, CY + 50, 330, 250, 0, 0, TAU);
  ctx.stroke();
  ctx.setLineDash([]);

  // stage grid
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(CX, CY + 50, 375, 295, 0, 0, TAU);
  ctx.clip();
  ctx.strokeStyle = 'rgba(255,255,255,0.022)';
  for (let x = CX - 380; x < CX + 380; x += 46) {
    ctx.beginPath();
    ctx.moveTo(x, CY - 250);
    ctx.lineTo(x, CY + 350);
    ctx.stroke();
  }
  for (let y = CY - 250; y < CY + 350; y += 46) {
    ctx.beginPath();
    ctx.moveTo(CX - 380, y);
    ctx.lineTo(CX + 380, y);
    ctx.stroke();
  }
  ctx.restore();

  // banner
  ctx.save();
  ctx.textAlign = 'center';
  ctx.globalAlpha = 0.65;
  ctx.font = "800 46px 'Bricolage Grotesque', sans-serif";
  ctx.fillStyle = 'rgba(255,181,69,0.12)';
  ctx.fillText('LIVE', CX, CY - 250);
  ctx.font = "700 9px 'JetBrains Mono', monospace";
  ctx.fillStyle = 'rgba(255,181,69,0.45)';
  ctx.fillText('SMITH SHOWCASE · LOWER FOUNDRY', CX, CY - 225);
  ctx.restore();

  // pedestals for rivals
  for (const r of game.showcaseRivals || []) {
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(r.x, r.y + 44, 46, 14, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#1b222b';
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.beginPath();
    ctx.ellipse(r.x, r.y + 40, 40, 12, 0, 0, TAU);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = 'rgba(255,181,69,0.35)';
    ctx.fillRect(r.x - 30, r.y + 38, 60, 2);
    ctx.restore();
  }

  // player pedestal
  ctx.save();
  const pg = ctx.createRadialGradient(CX, CY + 210, 10, CX, CY + 210, 170);
  pg.addColorStop(0, 'rgba(255,181,69,0.13)');
  pg.addColorStop(1, 'rgba(255,181,69,0)');
  ctx.fillStyle = pg;
  ctx.beginPath();
  ctx.ellipse(CX, CY + 210, 170, 58, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,181,69,0.22)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.ellipse(CX, CY + 208, 102, 34, 0, 0, TAU);
  ctx.stroke();
  ctx.fillStyle = 'rgba(255,181,69,0.55)';
  ctx.font = "700 7px 'JetBrains Mono', monospace";
  ctx.textAlign = 'center';
  ctx.fillText('YOUR BALL · LIVE', CX, CY + 254);
  ctx.restore();

  // confetti / stars
  for (let i = 0; i < 26; i += 1) {
    const a = i * 2.1 + t * 0.12;
    const rad = 300 + Math.sin(i * 3.7) * 120;
    const x = CX + Math.cos(a) * rad;
    const y = CY - 120 + Math.sin(a * 0.7) * 220;
    ctx.globalAlpha = 0.12 + Math.sin(t * 2 + i) * 0.08;
    ctx.fillStyle = CROWD[i % CROWD.length].color;
