149:     list.forEach((gadget, i) => {
150:       let deg;
151:       let dist;
152:       let size;
153:       if (pack === 'weapons') {
154:         deg = -90 + (360 / Math.max(list.length, 1)) * i;
155:         dist = 0.9;
