181:       layouts.push(entry);
182:       if (config.mirror) {
183:         layouts.push({
184:           ...entry,
185:           angle: baseRot + Math.PI - (deg * Math.PI) / 180,
186:           mirror: true,
187:           flip: true,
188:         });
189:       }
190:     });
191:   }
192:   return layouts;
