216: function inputRow({ label, value, min, max, step, format, onInput, hintLeft, hintRight }) {
217:   const pct = ((value - min) / (max - min)) * 100;
218:   return `
219:     <div class="slider-row">
220:       <div class="slider-top"><label>${label}</label><output>${format(value)}</output></div>
221:       <input type="range" min="${min}" max="${max}" step="${step}" value="${value}" style="--fill:${pct}%"
222:         data-slider-label="${label}" />
223:       ${hintLeft || hintRight ? `<div class="slider-hint"><span>${hintLeft || ''}</span><span>${hintRight || ''}</span></div>` : ''}
224:     </div>`;
225: }
