227: function bindSliders(root, handlers) {
228:   $$('input[type=range]', root).forEach((input) => {
229:     const key = input.dataset.sliderLabel;
230:     const handler = handlers[key];
231:     if (!handler) return;
232:     const paint = () => {
233:       const min = +input.min;
234:       const max = +input.max;
235:       input.style.setProperty('--fill', `${((+input.value - min) / (max - min)) * 100}%`);
236:     };
237:     paint();
238:     input.addEventListener('input', () => {
239:       paint();
240:       handler(+input.value);
241:     });
242:   });
243: }
