971: function handleArenaEnd(result) {
972:   if (!result) return;
973:   const mode = result.mode;
974:   const luck = build.phys.luck;
975:   const meta = MODE_META[mode];
976:   const won = result.win;
977:   const showcaseRank = result.rank || 3;
978:   const showcaseWin = mode === 'showcase' && showcaseRank <= 2;
979: 
980:   let scrap = 0;
981:   let cores = 0;
982:   if (mode === 'showcase') {
983:     scrap = Math.round((55 + result.score * 1.25) * (0.8 + luck * 0.25));
984:     cores = showcaseRank === 1 ? 2 : showcaseRank === 2 ? 1 : 0;
985:   } else if (won) {
986:     const base = { sumo: 95, race: 115, boss: 180 }[mode] || 90;
987:     const perf = result.time ? Math.max(0, 40 - Math.floor(result.time)) : 0;
988:     scrap = Math.round((base + perf) * (0.85 + Math.random() * 0.3) * (0.75 + luck * 0.3));
989:     cores = { sumo: 1, race: 1, boss: 3 }[mode] || 1;
990:   } else {
991:     const base = { sumo: 32, race: 38, boss: 60 }[mode] || 30;
992:     scrap = Math.round(base * (0.7 + luck * 0.3) + result.progressBonus || 0);
993:     cores = 0;
994:   }
995: 
996:   save.scrap += scrap;
997:   save.cores += cores;
998:   if (won) save.stats.wins += 1;
999:   save.stats.best[mode] = Math.max(save.stats.best[mode] || 0, result.bestScore || result.score || 0);
1000: 
1001:   // unlock drop
1002:   let unlockedGadget = null;
1003:   const locked = GADGETS.filter((g) => !save.unlocked.includes(g.id));
1004:   const dropChance = (won || showcaseWin ? 0.55 : 0.18) * Math.min(1.7, luck);
1005:   if (locked.length && Math.random() < dropChance) {
1006:     const pool = locked.filter((g) => g.rarity <= (won ? 3 : 2));
1007:     const source = pool.length ? pool : locked;
1008:     const totalWeight = source.reduce((sum, g) => sum + (4 - g.rarity), 0);
1009:     let roll = Math.random() * totalWeight;
1010:     let picked = source[source.length - 1];
1011:     for (const g of source) {
1012:       roll -= 4 - g.rarity;
1013:       if (roll <= 0) { picked = g; break; }
1014:     }
1015:     save.unlocked.push(picked.id);
1016:     unlockedGadget = picked;
1017:   } else if (won && locked.length === 0) {
1018:     save.scrap += 60;
1019:   }
1020: 
1021:   persist(true);
