26:   constructor({ mode, canvas, build, save, onEnd, onQuit }) {
27:     this.mode = mode;
28:     this.canvas = canvas;
29:     this.ctx = canvas.getContext('2d');
30:     this.build = build;
31:     this.save = save;
32:     this.onEnd = onEnd;
33:     this.onQuit = onQuit;
34: 
35:     this.dead = false;
36:     this.paused = false;
37:     this.started = false;
38:     this.ending = false;
39:     this.finished = false;
40:     this.finishTimer = 0;
41:     this.payload = null;
42:     this.countdown = 3.4;
43:     this.countDisplay = null;
44:     this.elapsed = 0;
45:     this.timeLeft = 0;
46:     this.timeLimit = 0;
47:     this.shake = 0;
48:     this.flash = 0;
49:     this.flashColor = '255,255,255';
50:     this.noticeTimer = 0;
51:     this.hudAcc = 0;
52:     this.sfxCd = 0;
53:     this.coreFlash = 0;
54: 
55:     this.keys = new Set();
56:     this.input = { x: 0, y: 0 };
57:     this.touchInput = { x: 0, y: 0 };
58:     this.aim = { x: CX, y: CY, active: false, t: -99 };
59: 
60:     this.balls = [];
61:     this.player = null;
62:     this.rival = null;
63:     this.bossBall = null;
64:     this.projectiles = [];
65:     this.particles = [];
66:     this.damageNumbers = [];
67:     this.shockwaves = [];
68:     this.zaps = [];
69:     this.coreBursts = [];
70:     this.telegraph = null;
71:     this.ringR = 300;
72:     this.score = 0;
73:     this.impact = 0;
74:     this.progress = 0;
75:     this.arenaT = 0;
76: 
77:     this.abort = new AbortController();
78:     this.boundFrame = this.frame.bind(this);
79: 
80:     this.hud = {
81:       mode: document.getElementById('hudMode'),
82:       objective: document.getElementById('hudObjective'),
83:       timer: document.getElementById('hudTimer'),
84:       sub: document.getElementById('hudSub'),
85:       notice: document.getElementById('hudNotice'),
86:       bossWrap: document.getElementById('bossBarWrap'),
87:       bossBar: document.getElementById('bossHpBar'),
88:       bossText: document.getElementById('bossHpText'),
89:       pilotHp: document.getElementById('pilotHp'),
90:       pilotStatus: document.getElementById('pilotStatus'),
91:       pilotName: document.getElementById('pilotName'),
92:       coreGlyph: document.getElementById('coreGlyph'),
93:       dashRing: document.getElementById('dashRing'),
94:       coreRing: document.getElementById('coreRing'),
95:       dashAbility: document.getElementById('dashAbility'),
96:       coreAbility: document.getElementById('coreAbility'),
97:       countdown: document.getElementById('countdownOverlay'),
98:       pauseOverlay: document.getElementById('pauseOverlay'),
99:       pauseBtn: document.getElementById('pauseBtn'),
100:       resumeBtn: document.getElementById('resumeBtn'),
101:       quitBtn: document.getElementById('quitBtn'),
102:       mobile: document.getElementById('mobileControls'),
103:       joystick: document.getElementById('joystick'),
104:       stick: document.getElementById('stick'),
105:       dashBtn: document.getElementById('dashBtn'),
106:       coreBtn: document.getElementById('coreBtn'),
107:     };
108: 
109:     this.hud.bossWrap.classList.add('hidden');
110:     this.hud.mobile.style.display = mode === 'showcase' ? 'none' : '';
111:     this.hud.notice.classList.remove('show');
112:     this.hud.notice.textContent = '';
113:     this.resize();
114:     this.bindInput();
115:     this.initMode();
116: 
117:     this.updateHud(true);
118:     this.last = performance.now();
119:     this.raf = requestAnimationFrame(this.boundFrame);
120:   }
121: 
122:   /* ── lifecycle ─────────────────────────────────────────── */
123:   start() {
124:     this.showCountdown('3');
125:   }
126: 
127:   destroy() {
128:     this.dead = true;
129:     cancelAnimationFrame(this.raf);
130:     this.abort.abort();
131:     if (this.hud) {
132:       this.hud.mobile.style.display = '';
133:       this.hud.countdown.classList.add('hidden');
134:       this.hud.countdown.innerHTML = '<span></span>';
135:       this.hud.notice.classList.remove('show');
136:       this.hud.pauseOverlay.classList.add('hidden');
137:       this.hud.bossWrap.classList.add('hidden');
138:     }
139:     clearTimeout(this.noticeTimer);
140:   }
141: 
142:   resize() {
143:     const cw = window.innerWidth;
144:     const ch = window.innerHeight;
145:     const dpr = Math.min(window.devicePixelRatio || 1, 2);
146:     this.cw = cw;
147:     this.ch = ch;
148:     this.dpr = dpr;
149:     this.canvas.width = Math.round(cw * dpr);
150:     this.canvas.height = Math.round(ch * dpr);
151:     this.canvas.style.width = `${cw}px`;
152:     this.canvas.style.height = `${ch}px`;
153:     const viewW = this.viewW || 960;
154:     const viewH = this.viewH || 780;
155:     this.scale = Math.min(cw / viewW, ch / viewH);
156:     this.ox = cw / 2 - CX * this.scale;
157:     this.oy = ch / 2 - CY * this.scale;
158:   }
159: 
160:   screenToWorld(clientX, clientY) {
161:     const rect = this.canvas.getBoundingClientRect();
162:     return {
163:       x: (clientX - rect.left - this.ox) / this.scale,
164:       y: (clientY - rect.top - this.oy) / this.scale,
165:     };
166:   }
167: 
168:   /* ── input ─────────────────────────────────────────────── */
169:   bindInput() {
170:     const signal = this.abort.signal;
171: 
172:     this.onResize = () => this.resize();
173:     window.addEventListener('resize', this.onResize, { signal });
174:     window.addEventListener('orientationchange', this.onResize, { signal });
175: 
176:     window.addEventListener('keydown', (event) => {
177:       if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ShiftLeft', 'ShiftRight'].includes(event.code)) {
178:         event.preventDefault();
179:       }
180:       this.keys.add(event.code);
181:       if (this.paused || !this.started || this.ending) return;
182:       if (event.repeat) return;
183:       if (event.code === 'Space') this.tryDash(this.player, this.getDashDir());
184:       if (event.code === 'ShiftLeft' || event.code === 'ShiftRight') this.useCore(this.player);
185:     }, { signal });
186: 
187:     window.addEventListener('keyup', (event) => {
188:       this.keys.delete(event.code);
189:     }, { signal });
190: 
191:     this.canvas.addEventListener('pointermove', (event) => {
192:       if (event.pointerType === 'touch') return;
193:       const p = this.screenToWorld(event.clientX, event.clientY);
194:       this.aim.x = p.x;
195:       this.aim.y = p.y;
196:       this.aim.active = true;
197:       this.aim.t = this.elapsed;
198:     }, { signal });
199: 
200:     this.hud.pauseBtn.addEventListener('click', () => this.togglePause(), { signal });
201:     this.hud.resumeBtn.addEventListener('click', () => this.togglePause(false), { signal });
202:     this.hud.quitBtn.addEventListener('click', () => { audio.click(); this.onQuit(); }, { signal });
203: 
204:     // touch joystick
205:     const joy = this.hud.joystick;
206:     const stick = this.hud.stick;
207:     let joyId = null;
208:     const moveJoy = (event) => {
209:       const rect = joy.getBoundingClientRect();
210:       const cx = rect.left + rect.width / 2;
211:       const cy = rect.top + rect.height / 2;
212:       let dx = event.clientX - cx;
213:       let dy = event.clientY - cy;
214:       const max = rect.width * 0.34;
215:       const d = Math.hypot(dx, dy);
216:       if (d > max) {
217:         dx = (dx / d) * max;
218:         dy = (dy / d) * max;
219:       }
220:       this.touchInput.x = dx / max;
221:       this.touchInput.y = dy / max;
222:       stick.style.transform = `translate(${dx}px, ${dy}px)`;
223:     };
224:     joy.addEventListener('pointerdown', (event) => {
225:       event.preventDefault();
226:       joyId = event.pointerId;
227:       joy.setPointerCapture(event.pointerId);
228:       moveJoy(event);
229:     }, { signal });
230:     joy.addEventListener('pointermove', (event) => {
231:       if (joyId === event.pointerId) moveJoy(event);
232:     }, { signal });
233:     const endJoy = (event) => {
234:       if (joyId !== event.pointerId) return;
235:       joyId = null;
236:       this.touchInput.x = 0;
237:       this.touchInput.y = 0;
238:       stick.style.transform = 'translate(0px, 0px)';
239:     };
240:     joy.addEventListener('pointerup', endJoy, { signal });
241:     joy.addEventListener('pointercancel', endJoy, { signal });
242: 
243:     this.hud.dashBtn.addEventListener('pointerdown', (event) => {
244:       event.preventDefault();
245:       if (this.started && !this.ending) this.tryDash(this.player, this.getDashDir());
246:     }, { signal });
247:     this.hud.coreBtn.addEventListener('pointerdown', (event) => {
248:       event.preventDefault();
249:       if (this.started && !this.ending) this.useCore(this.player);
250:     }, { signal });
251: 
252:     // hide touch controls if mouse is used on a hybrid device
253:     this.canvas.addEventListener('pointerdown', (event) => {
254:       if (event.pointerType === 'mouse' && this.hud.mobile) this.hud.mobile.style.opacity = '0.55';
255:     }, { signal });
256:   }
257: 
258:   readInput() {
259:     if (this.ending || this.paused) { this.input.x = 0; this.input.y = 0; return; }
260:     let x = 0;
261:     let y = 0;
262:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y -= 1;
263:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y += 1;
264:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
265:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
266:     if (Math.abs(this.touchInput.x) > 0.08 || Math.abs(this.touchInput.y) > 0.08) {
267:       x = this.touchInput.x;
268:       y = this.touchInput.y;
269:     }
270:     const n = norm(x, y);
271:     this.input.x = n.x * Math.min(1, n.d);
272:     this.input.y = n.y * Math.min(1, n.d);
273:     this.input.mag = Math.min(1, n.d);
274:     this.player?.setInput?.(this.input.x, this.input.y);
275:   }
276: 
277:   getDashDir() {
278:     const p = this.player;
279:     if (!p) return { x: 1, y: 0 };
280:     const mouseRecent = this.aim.active && this.elapsed - this.aim.t < 3.5;
281:     if (mouseRecent) {
282:       const n = norm(this.aim.x - p.x, this.aim.y - p.y);
283:       if (n.d > 12) return { x: n.x, y: n.y };
284:     }
285:     if (this.input.mag > 0.15) {
286:       const n = norm(this.input.x, this.input.y);
287:       return { x: n.x, y: n.y };
288:     }
289:     return { x: Math.cos(p.facing || 0), y: Math.sin(p.facing || 0) };
290:   }
291: 
292:   /* ── ball factory ──────────────────────────────────────── */
293:   makeBall(config, build, { x, y, isPlayer = false, name, radius, hp = 100, boss = false } = {}) {
294:     const stats = build.phys;
295:     return {
296:       config,
297:       build,
298:       stats,
299:       layouts: buildLayouts(config),
300:       x, y,
301:       vx: 0, vy: 0,
302:       r: radius || stats.radius,
303:       mass: boss ? 30 : stats.mass,
304:       facing: 0,
305:       isPlayer,
306:       isBoss: boss,
307:       name: name || config.name,
308:       hp,
309:       maxHp: hp,
310:       stun: 0,
311:       slow: 0,
312:       burn: 0,
313:       hitFlash: 0,
314:       invuln: 0,
315:       dashCd: 0,
316:       dashTimer: 0,
317:       dashDir: { x: 1, y: 0 },
318:       grapple: 0,
319:       coreCd: 0,
320:       autoCd: rand(0.5, 1.6),
321:       trail: [],
322:       falling: false,
323:       fallT: 0,
324:       ai: {},
325:       inputX: 0,
326:       inputY: 0,
327:       hitCd: 0,
328:       boostCd: 0,
329:       progressAngle: 0,
330:       prevTheta: null,
331:       topSpeed: 0,
332:       damageDealt: 0,
333:     };
334:   }
335: 
336:   makeRivalBuild(config) {
337:     const b = computeBuild(config, { mass: 2, energy: 2, motor: 2, armor: 1, luck: 0 }, { ignoreBudget: true });
338:     const d = diffFor(this.save.stats.wins, this.mode);
339:     const stats = { ...b.phys };
340:     stats.maxSpeed *= d;
341:     stats.accel *= d;
342:     stats.damage *= 0.9 + d * 0.18;
343:     stats.defense *= 1.02;
344:     return { ...b, phys: stats };
345:   }
346: 
347:   spawnRival() {
348:     const rival = rivalFor(this.save.stats.wins);
349:     const build = this.makeRivalBuild(rival.config);
350:     const ball = this.makeBall(rival.config, build, { x: CX + 150, y: CY, name: rival.name });
351:     ball.title = rival.title;
352:     return ball;
353:   }
354: 
355:   /* ── physics ───────────────────────────────────────────── */
356:   applyInput(ball, ix, iy, dt) {
357:     if (ball.falling) return;
358:     const stats = ball.stats;
359:     const controlled = ball.stun <= 0;
360:     const slowMul = ball.slow > 0 ? 0.52 : 1;
361:     if (controlled && (Math.abs(ix) > 0.01 || Math.abs(iy) > 0.01)) {
362:       const n = norm(ix, iy);
363:       const gripFactor = 0.82 + stats.control * 0.18;
364:       ball.vx += n.x * stats.accel * gripFactor * slowMul * dt;
365:       ball.vy += n.y * stats.accel * gripFactor * slowMul * dt;
366:       if (Math.hypot(ball.vx, ball.vy) > 10) ball.facing = Math.atan2(ball.vy, ball.vx);
367:     }
368:     if (ball.grapple > 0 && ball.dashDir) {
369:       ball.vx += ball.dashDir.x * stats.accel * 1.45 * dt;
370:       ball.vy += ball.dashDir.y * stats.accel * 1.45 * dt;
371:     }
372:     let drag = 1.9 - Math.min(0.7, stats.grip * 0.024);
373:     if (stats.gadgetTags?.has('hover')) drag *= 0.74;
374:     if (!controlled) drag = 0.35;
375:     const damp = Math.exp(-drag * dt);
376:     ball.vx *= damp;
377:     ball.vy *= damp;
378: 
379:     const maxS = stats.maxSpeed * slowMul * (ball.dashTimer > 0 ? 1.75 : 1) * (ball.stun > 0 ? 0.4 : 1);
380:     const speed = Math.hypot(ball.vx, ball.vy);
381:     if (speed > maxS) {
382:       ball.vx = (ball.vx / speed) * maxS;
383:       ball.vy = (ball.vy / speed) * maxS;
384:     }
385:     ball.x += ball.vx * dt;
386:     ball.y += ball.vy * dt;
387:     ball.topSpeed = Math.max(ball.topSpeed || 0, speed);
388: 
389:     if (speed > 30) {
390:       ball.trail.push({ x: ball.x, y: ball.y, life: 0.24, size: ball.r * 0.5 });
391:       if (ball.trail.length > 16) ball.trail.shift();
392:     }
393:   }
394: 
395:   stepBallTimers(ball, dt) {
396:     ball.stun = Math.max(0, ball.stun - dt);
397:     ball.slow = Math.max(0, ball.slow - dt);
398:     ball.burn = Math.max(0, ball.burn - dt);
399:     ball.hitFlash = Math.max(0, ball.hitFlash - dt);
400:     ball.invuln = Math.max(0, ball.invuln - dt);
401:     ball.dashCd = Math.max(0, ball.dashCd - dt);
402:     ball.dashTimer = Math.max(0, ball.dashTimer - dt);
403:     ball.grapple = Math.max(0, ball.grapple - dt);
404:     ball.coreCd = Math.max(0, ball.coreCd - dt);
405:     ball.autoCd = Math.max(0, ball.autoCd - dt);
406:     ball.hitCd = Math.max(0, ball.hitCd - dt);
407:     ball.boostCd = Math.max(0, ball.boostCd - dt);
408:     ball.trail.forEach((p) => { p.life -= dt; });
409:     ball.trail = ball.trail.filter((p) => p.life > 0);
410:   }
411: 
412:   stepBalls(dt) {
413:     for (const ball of this.balls) {
414:       if (ball.falling) {
415:         ball.fallT += dt;
416:         continue;
417:       }
418:       const ix = ball.isPlayer ? this.input.x : ball.inputX || 0;
419:       const iy = ball.isPlayer ? this.input.y : ball.inputY || 0;
420:       this.applyInput(ball, ix, iy, dt);
421:       this.constrainBall(ball, dt);
422:       this.stepBallTimers(ball, dt);
423:     }
424:   }
425: 
426:   /* ── actions ───────────────────────────────────────────── */
427:   tryDash(ball, dir) {
428:     if (!ball || ball.dashCd > 0 || ball.stun > 0 || ball.falling || this.ending || !this.started) return false;
429:     const n = norm(dir?.x || 0, dir?.y || 0);
430:     if (n.d === 0) return false;
431:     ball.dashDir = { x: n.x, y: n.y };
432:     ball.vx += n.x * ball.stats.dash * 1.28;
433:     ball.vy += n.y * ball.stats.dash * 1.28;
434:     ball.dashCd = DASH_CD;
435:     ball.dashTimer = 0.34;
436:     ball.invuln = Math.max(ball.invuln, 0.14);
437:     ball.facing = Math.atan2(n.y, n.x);
438:     if (ball.stats.gadgetTags?.has('grapple')) ball.grapple = 0.32;
439:     this.spawnBurst(ball.x - n.x * ball.r * 0.6, ball.y - n.y * ball.r * 0.6, ball.config.accent, 11, 160);
440:     this.spawnBurst(ball.x, ball.y, ball.config.color, 5, 90);
441:     if (ball.isPlayer) audio.dash();
442:     return true;
443:   }
444: 
445:   useCore(ball) {
446:     if (!ball || ball.coreCd > 0 || ball.stun > 0 || ball.falling || this.ending || !this.started) return;
447:     ball.coreCd = CORE_CD;
448:     const core = ball.config.core;
449:     const color = CORES[core]?.color || '#ffb545';
450:     audio.core(core);
451:     this.coreFlash = 0.45;
452:     this.coreBursts.push({ x: ball.x, y: ball.y, r: 20, max: 260, color, life: 0.6, maxLife: 0.6 });
453:     this.spawnBurst(ball.x, ball.y, color, 30, 260);
454:     this.shake = Math.max(this.shake, 7);
455: 
456:     const targets = this.coreTargets(ball);
457:     for (const target of targets) {
458:       const d = dist(ball, target);
459:       if (core === 'fire') {
460:         if (d < 250) {
461:           this.knockback(target, ball.x, ball.y, 310 / target.stats.defense);
462:           target.burn = 2.4;
463:           this.damageTarget(target, 10, ball, color);
464:           this.spawnBurst(target.x, target.y, '#ff8a4c', 18, 200);
465:         }
466:       } else if (core === 'ice') {
467:         if (d < 280) {
468:           target.slow = 3.2;
469:           target.stun = Math.max(target.stun, 0.12);
470:           this.damageTarget(target, 4, ball, color);
471:           this.spawnBurst(target.x, target.y, '#9be7ff', 22, 130);
472:         }
473:       } else if (core === 'zap') {
474:         if (d < 480) {
475:           this.zaps.push({ x1: ball.x, y1: ball.y, x2: target.x, y2: target.y, life: 0.35, color });
476:           target.stun = Math.max(target.stun, 0.55);
477:           this.knockback(target, ball.x, ball.y, 180 / target.stats.defense);
478:           this.damageTarget(target, 13, ball, color);
479:           this.addDamage(target.x, target.y - target.r, 'ZAP', color, 13);
480:         }
481:       } else if (core === 'gravity') {
482:         if (d < 460) {
483:           this.pullTowards(target, ball.x, ball.y, 420);
484:           this.damageTarget(target, 6, ball, color);
485:           this.spawnBurst(target.x, target.y, '#8b5cf6', 15, 80);
486:         }
487:       }
488:     }
489: 
490:     if (core === 'gravity') {
491:       this.coreBursts.push({ x: ball.x, y: ball.y, r: 30, max: 430, color, life: 0.8, maxLife: 0.8, reverse: true });
492:       this.shockwaves.push({ x: ball.x, y: ball.y, r: 20, max: 420, speed: 620, hit: true, color, thin: true });
493:     }
494:     if (ball.isPlayer) this.showNotice(CORES[core].abilityName.toUpperCase(), color, 750);
495:     else if (this.mode === 'sumo') this.showNotice(`${ball.name} USED ${CORES[core].abilityName.toUpperCase()}`, color, 750);
496:   }
497: 
498:   coreTargets(source) {
499:     const list = [];
500:     for (const b of this.balls) {
501:       if (b !== source && !b.falling) list.push(b);
502:     }
503:     if (this.bossBall && !this.bossBall.dead && source !== this.bossBall) list.push(this.bossBall);
504:     return list;
505:   }
506: 
507:   damageTarget(target, amount, source, color = '#ffb545') {
508:     if (!target) return;
509:     if (target.isBoss) {
510:       const dealt = amount;
511:       target.hp = Math.max(0, target.hp - dealt);
512:       target.hitFlash = 0.18;
513:       this.addDamage(target.x + rand(-20, 20), target.y - target.r * 0.4, Math.round(dealt), color, 14);
514:       if (this.player) this.player.damageDealt = (this.player.damageDealt || 0) + dealt;
515:       return;
516:     }
517:     if (target.invuln > 0) return;
518:     if (this.mode === 'race') {
519:       target.slow = Math.max(target.slow, 0.4);
520:       return;
521:     }
522:     target.hp = Math.max(0, target.hp - amount / Math.max(0.6, target.stats.defense));
523:     target.hitFlash = 0.18;
524:     this.addDamage(target.x, target.y - target.r, `-${Math.round(amount)}`, color, 12);
525:   }
526: 
527:   knockback(ball, fromX, fromY, force) {
528:     const n = norm(ball.x - fromX, ball.y - fromY);
529:     ball.vx += n.x * force;
530:     ball.vy += n.y * force;
531:   }
532: 
533:   pullTowards(ball, x, y, force) {
534:     const n = norm(x - ball.x, y - ball.y);
535:     ball.vx += n.x * force;
536:     ball.vy += n.y * force;
537:   }
538: 
539:   /* ── collisions ────────────────────────────────────────── */
540:   collideBalls(a, b) {
541:     if (!a || !b || a.falling || b.falling) return;
542:     const dx = b.x - a.x;
543:     const dy = b.y - a.y;
544:     const d = Math.hypot(dx, dy);
545:     const minD = a.r + b.r;
546:     if (d >= minD || d < 0.001) return;
547:     const nx = dx / d;
548:     const ny = dy / d;
549:     const overlap = minD - d;
550:     const total = a.mass + b.mass;
551:     a.x -= nx * overlap * (b.mass / total);
552:     a.y -= ny * overlap * (b.mass / total);
553:     b.x += nx * overlap * (a.mass / total);
554:     b.y += ny * overlap * (a.mass / total);
555: 
556:     const rvx = b.vx - a.vx;
557:     const rvy = b.vy - a.vy;
558:     const velN = rvx * nx + rvy * ny;
559:     if (velN < 0) {
560:       const e = clamp((a.stats.bounce + b.stats.bounce) * 0.6, 0.12, 0.95);
561:       const j = (-(1 + e) * velN) / (1 / a.mass + 1 / b.mass);
562:       a.vx -= (j * nx) / a.mass;
563:       a.vy -= (j * ny) / a.mass;
564:       b.vx += (j * nx) / b.mass;
565:       b.vy += (j * ny) / b.mass;
566:     }
567:     const impact = -velN;
568:     if (impact > 55) {
569:       const scale = this.mode === 'race' ? 0.3 : 1;
570:       const pushB = ((a.stats.damage * (0.45 + impact / 290) * (a.dashTimer > 0 ? 1.7 : 1)) / b.stats.defense) * 4.4 * scale;
571:       const pushA = ((b.stats.damage * (0.45 + impact / 290) * (b.dashTimer > 0 ? 1.7 : 1)) / a.stats.defense) * 4.4 * scale;
572:       b.vx += nx * pushB;
573:       b.vy += ny * pushB;
574:       a.vx -= nx * pushA;
575:       a.vy -= ny * pushA;
576:       if (a.stats.gadgetTags?.has('thorns')) this.knockback(b, a.x, a.y, pushB * 0.22);
577:       if (b.stats.gadgetTags?.has('thorns')) this.knockback(a, b.x, b.y, pushA * 0.22);
578:       a.stun = Math.max(a.stun, 0.08);
579:       b.stun = Math.max(b.stun, 0.08);
580:       a.hitFlash = 0.13;
581:       b.hitFlash = 0.13;
582:       const mx = (a.x + b.x) / 2;
583:       const my = (a.y + b.y) / 2;
584:       this.spawnBurst(mx, my, '#fff0cf', 10 + Math.min(14, impact / 40), 140 + impact * 0.4);
585:       this.shake = Math.max(this.shake, Math.min(12, impact / 35));
586:       if (this.mode === 'sumo') {
587:         this.impact += impact;
588:         this.score += impact / 10;
589:         if (impact > 160) this.addDamage(mx, my - 20, impact > 320 ? 'KRAK!' : 'WHAM', '#ffd38a', 15);
590:       }
591:       if (this.sfxCd <= 0) {
592:         audio.bump(clamp(impact / 220, 0.4, 1.8));
593:         this.sfxCd = 0.09;
594:       }
595:     }
596:   }
