598:   /* ── projectiles ───────────────────────────────────────── */
599:   fireProjectile(owner, target, { damage, color, speed = 420, radius = 7, boss = false } = {}) {
600:     if (!target) return;
601:     const n = norm(target.x - owner.x, target.y - owner.y);
602:     if (n.d === 0) return;
603:     this.projectiles.push({
604:       x: owner.x + n.x * owner.r,
605:       y: owner.y + n.y * owner.r,
606:       vx: n.x * speed,
607:       vy: n.y * speed,
608:       r: radius,
609:       life: 2.6,
610:       color: color || owner.config.accent,
611:       owner,
612:       damage: damage ?? owner.stats.damage * 0.55,
613:       boss,
614:       trail: [],
615:     });
616:     this.spawnBurst(owner.x + n.x * owner.r, owner.y + n.y * owner.r, color || owner.config.accent, 6, 70);
617:     if (owner.isPlayer) audio.tone({ freq: 680, dur: 0.08, type: 'square', gain: 0.03, slide: -220 });
618:   }
619: 
620:   autoFire(ball, target) {
621:     if (!ball || !target || target.dead || ball.falling) return;
622:     if (!ball.stats.gadgetTags?.has('projectile')) return;
623:     if (ball.autoCd > 0) return;
624:     ball.autoCd = 1.82 - Math.min(0.4, ball.stats.control * 0.08);
625:     this.fireProjectile(ball, target, { damage: ball.stats.damage * 0.7 });
626:   }
627: 
628:   updateProjectiles(dt) {
629:     const alive = [];
630:     for (const p of this.projectiles) {
631:       p.life -= dt;
632:       p.x += p.vx * dt;
633:       p.y += p.vy * dt;
634:       p.trail.push({ x: p.x, y: p.y, life: 0.18 });
635:       if (p.trail.length > 8) p.trail.shift();
636:       p.trail.forEach((t) => { t.life -= dt; });
637: 
638:       let hit = false;
639:       if (p.boss) {
640:         if (this.player && !this.player.falling && dist(p, this.player) < p.r + this.player.r) {
641:           if (this.player.invuln <= 0) {
642:             this.player.hp = Math.max(0, this.player.hp - p.damage / Math.max(0.7, this.player.stats.defense));
643:             this.player.hitFlash = 0.2;
644:             this.player.invuln = 0.3;
645:             this.addDamage(this.player.x, this.player.y - this.player.r, `-${Math.round(p.damage)}`, '#ff8f86', 13);
646:             this.spawnBurst(p.x, p.y, p.color, 16, 200);
647:             this.shake = Math.max(this.shake, 5);
648:             audio.hit(1);
649:           }
650:           hit = true;
651:         }
652:       } else {
653:         for (const b of this.balls) {
654:           if (!b || b === p.owner || b.falling) continue;
655:           if (dist(p, b) < p.r + b.r) {
656:             this.applyProjectileHit(p, b);
657:             hit = true;
658:             break;
659:           }
660:         }
661:         if (!hit && this.bossBall && !this.bossBall.dead && dist(p, this.bossBall) < p.r + this.bossBall.r) {
662:           this.applyProjectileHit(p, this.bossBall);
663:           hit = true;
664:         }
665:       }
666:       if (!hit && (p.x < -100 || p.x > W + 100 || p.y < -100 || p.y > H + 100)) hit = true;
667:       if (p.life > 0 && !hit) alive.push(p);
668:     }
669:     this.projectiles = alive;
670:   }
671: 
672:   applyProjectileHit(p, target) {
673:     if (target.isBoss) {
674:       this.damageTarget(target, p.damage, p.owner, p.color);
675:       this.spawnBurst(p.x, p.y, p.color, 12, 160);
676:       this.addDamage(p.x, p.y - 14, `${Math.round(p.damage)}`, p.color, 12);
677:       audio.hit(0.6);
678:       return;
679:     }
680:     if (this.mode === 'sumo') {
681:       const n = norm(p.vx, p.vy);
682:       target.vx += n.x * (110 + p.owner.stats.damage * 4);
683:       target.vy += n.y * (110 + p.owner.stats.damage * 4);
684:       this.impact += 50;
685:       this.score += 5;
686:       if (this.mode === 'race') target.slow = 0.6;
687:     } else {
688:       target.slow = Math.max(target.slow, 0.6);
689:       this.knockback(target, p.x, p.y, 90 / target.stats.defense);
690:     }
691:     target.hitFlash = 0.16;
692:     this.spawnBurst(p.x, p.y, p.color, 14, 170);
693:     this.addDamage(p.x, p.y - 12, 'PLINK', p.color, 10);
694:     audio.hit(0.45);
695:   }
