697:   /* ── effects ───────────────────────────────────────────── */
698:   spawnBurst(x, y, color, count = 12, power = 180) {
699:     for (let i = 0; i < count; i += 1) {
700:       const a = Math.random() * TAU;
701:       const s = rand(0.25, 1) * power;
702:       this.particles.push({
703:         x, y,
704:         vx: Math.cos(a) * s,
705:         vy: Math.sin(a) * s,
706:         life: rand(0.28, 0.8),
707:         maxLife: 0.8,
708:         size: rand(1.6, 4.8),
709:         color,
710:         drag: 2.4,
711:         kind: Math.random() > 0.7 ? 'spark' : 'dot',
712:       });
713:     }
714:     if (this.particles.length > 700) this.particles.splice(0, this.particles.length - 700);
715:   }
716: 
717:   addDamage(x, y, text, color = '#f7f2e8', size = 12) {
718:     this.damageNumbers.push({ x, y, text, color, size, life: 0.85, maxLife: 0.85, vy: -55 });
719:     if (this.damageNumbers.length > 20) this.damageNumbers.shift();
720:   }
721: 
722:   updateEffects(dt) {
723:     this.coreFlash = Math.max(0, this.coreFlash - dt);
724:     this.flash = Math.max(0, this.flash - dt * 2.2);
725:     this.shake *= 0.9;
726:     this.sfxCd = Math.max(0, this.sfxCd - dt);
727: 
728:     for (const p of this.particles) {
729:       p.life -= dt;
730:       p.x += p.vx * dt;
731:       p.y += p.vy * dt;
732:       p.vx *= Math.exp(-p.drag * dt);
733:       p.vy *= Math.exp(-p.drag * dt);
734:       if (p.kind === 'spark') p.size *= 0.98;
735:     }
736:     this.particles = this.particles.filter((p) => p.life > 0);
737: 
738:     for (const d of this.damageNumbers) {
739:       d.life -= dt;
740:       d.y += d.vy * dt;
741:       d.vy *= 0.96;
742:     }
743:     this.damageNumbers = this.damageNumbers.filter((d) => d.life > 0);
744: 
745:     for (const w of this.shockwaves) {
746:       w.r += w.speed * dt;
747:       w.life -= dt;
748:     }
749:     this.shockwaves = this.shockwaves.filter((w) => w.r < w.max && w.life > 0);
750: 
751:     for (const z of this.zaps) z.life -= dt;
752:     this.zaps = this.zaps.filter((z) => z.life > 0);
753: 
754:     for (const b of this.coreBursts) {
755:       b.life -= dt;
756:       b.r += ((b.reverse ? b.max - b.r : b.r) * 3 + 160) * dt;
757:     }
758:     this.coreBursts = this.coreBursts.filter((b) => b.life > 0);
759:   }
