802:   /* ── HUD ───────────────────────────────────────────────── */
803:   updateHud(force = false) {
804:     this.hudAcc += 0.016;
805:     if (!force && this.hudAcc < 0.07) return;
806:     this.hudAcc = 0;
807: 
808:     const h = this.hud;
809:     if (this.mode === 'showcase') {
810:       h.timer.textContent = '★';
811:     } else {
812:       h.timer.textContent = String(Math.ceil(this.timeLeft));
813:     }
814: 
815:     if (this.player) {
816:       const dashPct = this.player.dashCd <= 0 ? 0 : this.player.dashCd / DASH_CD;
817:       const corePct = this.player.coreCd <= 0 ? 0 : this.player.coreCd / CORE_CD;
818:       if (h.dashRing) h.dashRing.style.strokeDashoffset = String(113 * dashPct);
819:       if (h.coreRing) h.coreRing.style.strokeDashoffset = String(113 * corePct);
820:       h.dashAbility.classList.toggle('ready', this.player.dashCd <= 0);
821:       h.coreAbility.classList.toggle('ready', this.player.coreCd <= 0);
822:       const hpRatio = this.player.maxHp ? this.player.hp / this.player.maxHp : 1;
823:       h.pilotHp.style.width = `${clamp(hpRatio * 100, 0, 100)}%`;
824:       h.pilotHp.style.background = hpRatio < 0.35
825:         ? 'linear-gradient(90deg,#ff5d5d,#ff9d7a)'
826:         : 'linear-gradient(90deg,var(--teal),#a7f3e0)';
827:       if (this.player.hp <= 0 || (this.mode === 'sumo' && this.player.falling)) h.pilotStatus.textContent = 'BALL LOST';
828:       else if (this.player.hp < this.player.maxHp * 0.35 && this.mode === 'boss') h.pilotStatus.textContent = 'CRITICAL · KEEP MOVING';
829:       else if (this.player.coreCd <= 0) h.pilotStatus.textContent = `${CORES[this.player.config.core].abilityName.toUpperCase()} READY`;
830:       else if (this.player.dashCd <= 0) h.pilotStatus.textContent = 'DASH READY';
831:       else h.pilotStatus.textContent = 'RECOVERING';
832:       h.coreGlyph.textContent = CORES[this.player.config.core].icon;
833:     }
834: 
835:     if (this.mode === 'boss' && this.bossBall) {
836:       const ratio = this.bossBall.hp / this.bossBall.maxHp;
837:       h.bossWrap.classList.remove('hidden');
838:       h.bossBar.style.width = `${ratio * 100}%`;
839:       h.bossText.textContent = `${Math.ceil(ratio * 100)}%`;
840:     } else {
841:       h.bossWrap.classList.add('hidden');
842:     }
843: 
844:     if (this.mode === 'sumo') {
845:       h.sub.textContent = `RING ${Math.round(this.ringR)} · IMPACT ${Math.round(this.score)} · LUCK ×${this.player.stats.luck.toFixed(1)}`;
846:     } else if (this.mode === 'race') {
847:       const lap = Math.min(2, Math.floor(this.player.progressAngle / TAU) + 1);
848:       const pos = this.player.progressAngle >= (this.rival?.progressAngle || 0) ? '1ST' : '2ND';
849:       h.sub.textContent = `LAP ${lap}/2 · ${pos} · ${fmtClock(this.elapsed)}`;
850:     } else if (this.mode === 'boss') {
851:       h.sub.textContent = `PHASE ${this.bossBall && this.bossBall.hp < this.bossBall.maxHp * 0.5 ? '2' : '1'} · WARDEN CORE EXPOSED`;
852:     } else {
853:       h.sub.textContent = `LIVE LOBBY · 5 SMITHS · CROWD VOTE IN PROGRESS`;
854:     }
855:   }
