857:   /* ── main loop ─────────────────────────────────────────── */
858:   frame(now) {
859:     if (this.dead) return;
860:     const dt = Math.min(0.034, Math.max(0, (now - this.last) / 1000));
861:     this.last = now;
862:     this.arenaT += dt;
863:     if (!this.paused) this.update(dt);
864:     else this.updateEffects(dt * 0.15);
865:     this.render(now / 1000);
866:     this.raf = requestAnimationFrame(this.boundFrame);
867:   }
868: 
869:   update(dt) {
870:     // countdown
871:     if (!this.started) {
872:       this.countdown -= dt;
873:       if (this.countdown > 0) {
874:         const n = Math.ceil(this.countdown);
875:         if (n !== this.countDisplay) {
876:           this.countDisplay = n;
877:           this.showCountdown(String(n));
878:         }
879:         this.updateEffects(dt);
880:         return;
881:       }
882:       this.started = true;
883:       this.hud.countdown.classList.add('hidden');
884:       this.showNotice('ROLL!', '#ffb545', 700);
885:       audio.tone({ freq: 520, dur: 0.18, type: 'triangle', gain: 0.1, slide: 220 });
886:       this.updateHud(true);
887:     }
888: 
889:     if (this.finished) {
890:       this.updateEffects(dt);
891:       return;
892:     }
893: 
894:     if (this.ending) {
895:       this.finishTimer -= dt;
896:       this.updateEffects(dt);
897:       if (this.finishTimer <= 0 && !this.finished) {
898:         this.finished = true;
899:         this.ending = false;
900:         this.onEnd?.(this.payload);
901:       }
902:       return;
903:     }
904: 
905:     this.elapsed += dt;
906:     if (this.timeLimit > 0) this.timeLeft = Math.max(0, this.timeLeft - dt);
907:     this.readInput();
908: 
909:     if (this.mode === 'sumo') this.updateSumo(dt);
910:     else if (this.mode === 'race') this.updateRace(dt);
911:     else if (this.mode === 'boss') this.updateBoss(dt);
912:     else if (this.mode === 'showcase') this.updateShowcase(dt);
913: 
914:     this.updateProjectiles(dt);
915:     this.updateEffects(dt);
916:     this.updateHud();
917:   }
