919:   /* ── rendering ─────────────────────────────────────────── */
920:   render(t) {
921:     const ctx = this.ctx;
922:     const { cw, ch, dpr } = this;
923:     if (!cw) return;
924:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
925:     ctx.clearRect(0, 0, cw, ch);
926: 
927:     // screen backdrop
928:     const bg = ctx.createRadialGradient(cw / 2, ch * 0.44, 20, cw / 2, ch * 0.5, Math.max(cw, ch) * 0.8);
929:     bg.addColorStop(0, '#121821');
930:     bg.addColorStop(0.6, '#080b10');
931:     bg.addColorStop(1, '#05070a');
932:     ctx.fillStyle = bg;
933:     ctx.fillRect(0, 0, cw, ch);
934: 
935:     const sx = this.shake > 0.1 ? rand(-this.shake, this.shake) : 0;
936:     const sy = this.shake > 0.1 ? rand(-this.shake, this.shake) : 0;
937:     ctx.save();
938:     ctx.translate(this.ox + sx, this.oy + sy);
939:     ctx.scale(this.scale, this.scale);
940: 
941:     this.drawArena(t);
942:     if (this.drawUnder) this.drawUnder(t);
943: 
944:     const entities = [...this.balls];
945:     if (this.bossBall && !this.bossBall.dead) entities.push(this.bossBall);
946:     entities.sort((a, b) => a.y - b.y);
947:     for (const ball of entities) this.drawBallEntity(ball, t);
948: 
949:     this.drawProjectiles(t);
950:     this.drawShockwaves(t);
951:     this.drawZaps(t);
952:     this.drawParticles();
953:     this.drawDamageNumbers();
954:     if (this.drawOver) this.drawOver(t);
955: 
956:     ctx.restore();
957: 
958:     if (this.flash > 0.01) {
959:       ctx.fillStyle = `rgba(${this.flashColor},${Math.min(0.5, this.flash * 0.4)})`;
960:       ctx.fillRect(0, 0, cw, ch);
961:     }
962:   }
963: 
964:   drawBallEntity(ball, t) {
965:     if (!ball) return;
966:     const ctx = this.ctx;
967:     const fall = ball.falling ? Math.min(1, ball.fallT / 0.75) : 0;
968:     const opacity = ball.isBoss ? 1 : 1 - fall * 0.85;
969:     const speed = Math.hypot(ball.vx, ball.vy);
970:     const look = norm(ball.vx || Math.cos(ball.facing), ball.vy || Math.sin(ball.facing));
971:     const face = speed > 20 ? { x: look.x, y: look.y } : { x: Math.cos(ball.facing || 0) * 0.35, y: Math.sin(ball.facing || 0) * 0.35 };
972:     const dashes = ball.dashTimer > 0;
973: 
974:     // trail
975:     for (const p of ball.trail) {
976:       ctx.fillStyle = alpha(ball.config.color, (p.life / 0.24) * 0.12);
977:       ctx.beginPath();
978:       ctx.arc(p.x, p.y, p.size * (p.life / 0.24), 0, TAU);
979:       ctx.fill();
980:     }
981: 
982:     if (ball.slow > 0) {
983:       ctx.strokeStyle = 'rgba(155,231,255,0.45)';
984:       ctx.lineWidth = 2;
985:       ctx.beginPath();
986:       ctx.arc(ball.x, ball.y, ball.r * 1.17, t * 2, t * 2 + 4.2);
987:       ctx.stroke();
988:     }
989:     if (ball.burn > 0) {
990:       ctx.strokeStyle = 'rgba(255,138,76,0.4)';
991:       ctx.lineWidth = 2.5;
992:       ctx.beginPath();
993:       ctx.arc(ball.x, ball.y, ball.r * 1.13, -t * 2.5, -t * 2.5 + 3.4);
994:       ctx.stroke();
995:     }
996:     if (ball.stats.gadgetTags?.has('shield')) {
997:       ctx.strokeStyle = 'rgba(103,232,249,0.28)';
998:       ctx.lineWidth = 1.5;
999:       ctx.beginPath();
1000:       ctx.arc(ball.x, ball.y, ball.r * 1.28, 0, TAU);
1001:       ctx.stroke();
1002:     }
1003: 
1004:     ctx.save();
1005:     if (fall > 0) {
1006:       ctx.translate(0, fall * 30);
1007:       const sc = 1 - fall * 0.55;
1008:       ctx.translate(ball.x, ball.y);
1009:       ctx.scale(sc, sc);
1010:       ctx.translate(-ball.x, -ball.y);
1011:     }
1012: 
1013:     drawBlob(ctx, {
1014:       x: ball.x,
1015:       y: ball.y,
1016:       r: ball.r,
1017:       config: ball.config,
1018:       t,
1019:       face,
1020:       layouts: ball.layouts,
1021:       expression: ball.hitFlash > 0.03 ? 'hit' : null,
1022:       glow: dashes ? 0.55 : 0,
1023:       squashDir: speed > 40 ? Math.atan2(ball.vy, ball.vx) : null,
1024:       speedRatio: clamp(speed / Math.max(60, ball.stats.maxSpeed), 0, 1),
1025:       alpha: ball.isBoss ? 1 : Math.max(0, opacity),
