367:     const bO = RACE.outerB - ball.r * 0.92;
368:     let nx = (ball.x - CX) / aO;
369:     let ny = (ball.y - CY) / bO;
370:     let f = nx * nx + ny * ny;
371:     if (f > 1) {
372:       const k = 1 / Math.sqrt(f);
373:       ball.x = CX + (ball.x - CX) * k;
374:       ball.y = CY + (ball.y - CY) * k;
375:       const gn = norm((ball.x - CX) / (aO * aO), (ball.y - CY) / (bO * bO));
376:       const vn = ball.vx * gn.x + ball.vy * gn.y;
377:       if (vn > 0) {
378:         ball.vx -= (1 + e) * vn * gn.x;
379:         ball.vy -= (1 + e) * vn * gn.y;
380:       }
381:     }
382: 
383:     // inner wall
384:     const aI = RACE.innerA + ball.r * 0.92;
385:     const bI = RACE.innerB + ball.r * 0.92;
386:     nx = (ball.x - CX) / aI;
387:     ny = (ball.y - CY) / bI;
388:     f = nx * nx + ny * ny;
389:     if (f < 1) {
390:       if (f < 0.0001) {
391:         ball.x = CX + aI;
392:         ball.y = CY;
393:       } else {
394:         const k = 1 / Math.sqrt(f);
395:         ball.x = CX + (ball.x - CX) * k;
396:         ball.y = CY + (ball.y - CY) * k;
397:       }
398:       const gn = norm((ball.x - CX) / (aI * aI), (ball.y - CY) / (bI * bI));
399:       const vn = ball.vx * gn.x + ball.vy * gn.y;
400:       if (vn < 0) {
401:         ball.vx -= (1 + e) * vn * gn.x;
402:         ball.vy -= (1 + e) * vn * gn.y;
403:       }
404:     }
405:   },
