514:       ball.y = CY + ny * R;
515:       const vn = ball.vx * nx + ball.vy * ny;
516:       if (vn > 0) {
517:         ball.vx -= (1 + ball.stats.bounce) * vn * nx;
518:         ball.vy -= (1 + ball.stats.bounce) * vn * ny;
