523:   updateBossMovement(dt) {
524:     const boss = this.bossBall;
525:     const player = this.player;
526:     const phase2 = boss.hp < boss.maxHp * 0.5;
527:     boss.hitFlash = Math.max(0, (boss.hitFlash || 0) - dt);
528:     boss.hitCd = Math.max(0, (boss.hitCd || 0) - dt);
529:     if (!boss.attack) {
530:       boss.attackTimer -= dt * (phase2 ? 1.35 : 1);
531:       const d = dist(boss, player);
532:       if (d > 230 && this.elapsed > 1) {
533:         const n = norm(player.x - boss.x, player.y - boss.y);
534:         boss.vx += n.x * 22;
535:         boss.vy += n.y * 22;
536:       }
537:       boss.vx *= Math.exp(-2.6 * dt);
538:       boss.vy *= Math.exp(-2.6 * dt);
539:       boss.x += boss.vx * dt;
540:       boss.y += boss.vy * dt;
541:       if (boss.attackTimer <= 0) this.beginBossAttack(phase2);
542:     } else {
543:       const atk = boss.attack;
544:       atk.t -= dt;
545:       if (atk.type === 'slam') {
546:         boss.vx *= Math.exp(-4 * dt);
547:         boss.vy *= Math.exp(-4 * dt);
548:         boss.x += boss.vx * dt;
549:         boss.y += boss.vy * dt;
550:         if (atk.t <= 0) this.executeSlam(atk, phase2);
551:       } else if (atk.type === 'volley') {
552:         boss.vx *= Math.exp(-4 * dt);
553:         boss.vy *= Math.exp(-4 * dt);
554:         if (atk.t <= 0) this.executeVolley(phase2);
555:       } else if (atk.type === 'chargeWind') {
556:         if (atk.t <= 0) {
557:           const n = norm(player.x - boss.x, player.y - boss.y);
558:           boss.vx = n.x * (phase2 ? 640 : 540);
559:           boss.vy = n.y * (phase2 ? 640 : 540);
560:           boss.attack = { type: 'charge', t: 0.62 };
561:           audio.dash();
562:           this.shake = 6;
563:         }
564:       } else if (atk.type === 'charge') {
565:         boss.x += boss.vx * dt;
566:         boss.y += boss.vy * dt;
567:         boss.vx *= Math.exp(-2.4 * dt);
568:         boss.vy *= Math.exp(-2.4 * dt);
569:         if (Math.random() < 0.5) this.particles.push({
570:           x: boss.x - rand(-40, 40), y: boss.y - rand(-40, 40),
571:           vx: rand(-40, 40), vy: rand(-40, 40), life: 0.4, maxLife: 0.5,
572:           size: rand(5, 12), color: '#ff6b3d', drag: 2, kind: 'dot',
573:         });
