660:     const nx = (player.x - boss.x) / d;
661:     const ny = (player.y - boss.y) / d;
662:     player.x = boss.x + nx * min;
663:     player.y = boss.y + ny * min;
664: 
665:     if (player.dashTimer > 0 && boss.hitCd <= 0) {
666:       const dmg = (player.stats.damage * 2.5 + Math.hypot(player.vx, player.vy) * 0.07) * (boss.dead ? 0 : 1);
667:       this.damageTarget(boss, dmg, player, '#ffd38a');
