753:   scoreShowcase() {
754:     const c = this.save.config;
755:     const phys = this.build.phys;
756:     const packs = new Set(c.gadgets.map((id) => GADGET_MAP[id]?.pack).filter(Boolean));
757:     const tags = phys.gadgetTags || new Set();
758:     const glow = c.glow || 0;
759:     const creativity = clamp(
760:       27 + (c.pattern !== 'solid' ? 12 : 0) + (c.texture !== 'matte' ? 8 : 0) + glow * 18
761:       + c.gadgets.length * 3.1 + packs.size * 5 + (c.mirror ? 6 : 0) + (c.rotation ? 4 : 0)
762:       + (c.accent !== c.color ? 4 : 0),
763:       10, 100,
764:     );
765:     const menace = clamp(
766:       8 + phys.damage * 2.1 + (tags.has('contact') ? 13 : 0) + (tags.has('projectile') ? 9 : 0)
767:       + (c.mood === 'angry' ? 10 : 0) + (phys.maxMass ? 0 : 0),
768:       5, 100,
769:     );
770:     const charm = clamp(
771:       30 + glow * 22 + (['star', 'wide', 'sleepy'].includes(c.eyes) ? 7 : 0)
772:       + (['grin', 'smile', 'ooo'].includes(c.mouth) ? 8 : 0)
773:       + (['giddy', 'calm'].includes(c.mood) ? 12 : 0)
774:       + (c.gadgets.includes('weird_party_hat') ? 15 : 0)
775:       + (c.name.length <= 5 ? 4 : 0),
776:       5, 100,
777:     );
778:     const leftover = 1 - (phys.massCost / phys.maxMass) * 0.7;
779:     const synergy = clamp(
780:       22 + leftover * 42 + packs.size * 6 + (tags.has('luck') ? 6 : 0)
781:       + (['fire', 'electric'].includes(c.core) ? 6 : 0) + (c.mirror ? 5 : 0),
782:       5, 100,
783:     );
784:     const base = creativity * 0.28 + menace * 0.24 + charm * 0.24 + synergy * 0.24;
785:     const score = Math.round(clamp(base + rand(-2, 4) + (phys.luck - 1) * 6, 15, 99));
786:     return {
787:       breakdown: {
788:         creativity: Math.round(creativity),
789:         menace: Math.round(menace),
790:         charm: Math.round(charm),
791:         synergy: Math.round(synergy),
792:       },
793:       score,
794:       t: 0,
795:       chat: 0,
796:       chatTimer: 0,
797:     };
