215: function ellipticalArc(ctx, a, b, from, to) {
216:   ctx.beginPath();
217:   const steps = Math.max(5, Math.ceil(Math.abs(to - from) * 40));
218:   for (let i = 0; i <= steps; i += 1) {
219:     const th = from + ((to - from) * i) / steps;
220:     const x = CX + Math.cos(th) * a;
221:     const y = CY + Math.sin(th) * b;
222:     if (i === 0) ctx.moveTo(x, y);
223:     else ctx.lineTo(x, y);
224:   }
225: }
