  const { cw, ch, dpr, scale, ox, oy } = this;
  if (!cw || !ch) return;
  const key = `${this.mode}:${this.mode === 'sumo' ? Math.round(this.ringR / 6) : 'static'}:${cw}x${ch}@${dpr}`;
  if (this.arenaCanvas && this.arenaKey === key) return;
